DuskShineCore.ToggleTheme = function(P21)
	local V46 = (table.find(P21.ThemeCycle, P21.CurrentThemeName) or 1) + 1

	if V46 > #P21.ThemeCycle then
		V46 = 1
	end

	local V47 = P21.ThemeCycle[V46]

	P21:SetTheme(V47)

	return V47
end
