						ImageColor3 = "SubText"
					}
					DuskShineCore.ThemeObjects[Tab.Indicator] = {
						BackgroundColor3 = "SubText"
					}

					local DuskShineGradient = Tab.Indicator:FindFirstChild("DuskShine_Gradient")

					if DuskShineGradient then
