		}
		ScrollingFrame.ScrollBarImageColor3 = DuskShineCore.CurrentTheme.SubText

		local UIListLayout = Instance.new("UIListLayout", ScrollingFrame)

		UIListLayout.Padding = UDim.new(0, 12)
