]==],
    ["/raw/modules/adm_main/ConfigManager"] = [==[local ConfigManager = { Library = nil, InitTime = 0 }
local HttpService = game:GetService("HttpService")
local OldFileName = "DuskShine_Config.json"

function ConfigManager:Init(LibraryRef)
    self.Library = LibraryRef
    self.InitTime = tick()
    
    if not isfolder("ProjectDusk") then 
        makefolder("ProjectDusk") 
    end
    
    local Ver = getgenv().DuskVersion or "v4.beta1"
    self.FileName = "ProjectDusk/Config_" .. tostring(Ver):gsub("[^%w%.%-]", "_") .. ".json"
end

function ConfigManager:Load()
    if not self.FileName then
        self:Init(getgenv().DuskShine_Core)
    end

    getgenv().DuskConfigCache = {}
    local LoadedData = nil

    if isfile(self.FileName) then
        local S, d = pcall(function() return HttpService:JSONDecode(readfile(self.FileName)) end)
        if S and type(D) == "table" then LoadedData = D end
    elseif isfile(OldFileName) then
        local S, d = pcall(function() return HttpService:JSONDecode(readfile(OldFileName)) end)
        if S and type(D) == "table" then 
            LoadedData = D 
            warn("🔄 [Config] Найдена старая база (" .. OldFileName .. "). Адаптируем под " .. tostring(getgenv().DuskVersion) .. "...")
        end
    end

    if LoadedData then
    for K, V in pairs(LoadedData) do
         
        local ParsedVal = V
        if type(V) == "table" and V.R ~= nil and V.G ~= nil and V.B ~= nil and not V.__type then
            ParsedVal = { __type = "Color3", R = V.R, G = V.G, B = V.B }
        end
        getgenv().DuskConfigCache[K] = ParsedVal
        
         
        if type(ParsedVal) == "table" and ParsedVal.__type == "Color3" then
            getgenv()[K] = Color3.new(ParsedVal.R, ParsedVal.G, ParsedVal.B)
        elseif type(ParsedVal) == "table" and ParsedVal.__type == "KeyCode" then
            getgenv()[K] = Enum.KeyCode[ParsedVal.Name]
        else
            getgenv()[K] = ParsedVal
        end
    end

     
    local TAccent = getgenv().DuskConfigCache.ThemeAccent
    if TAccent and TAccent.R then
        getgenv().ThemeAccentColor = Color3.new(TAccent.R, TAccent.G, TAccent.B)
    end
end

    getgenv().SaveConfig = function() self:Save() end

    if not self.AutoSaveActive then
        self.AutoSaveActive = true
        task.spawn(function()
             
            while not getgenv().AllDuskModulesLoaded do
                task.wait(1)
            end
            
             
            print("✅ [Config] UI builded, auto-save enabled.")
            while task.wait(5) do
                if getgenv().DuskShine_Core then 
                    pcall(function() self:Save() end) 
                end
            end
        end)
    end
end

function ConfigManager:Save()
    if not self.Library then return end
    
    local ToSave = {}
    local CurrentCache = getgenv().DuskConfigCache or {}
    local AllModulesLoaded = getgenv().AllDuskModulesLoaded == true

     
    local CustomGlobals = {
         
        "ThemeAccent", "ThemeAccentColor", "DuskTheme", "UIScaleSize", "UIScaleLocker", "AutoReconnectEnabled", "AutoUpdateKicker", "AnonymousMode",
        "HeapReconnecterEnabled", "HeapLimit", "FPSLimit", "PerformanceModeEnabled",
        "MenuParticlesEnabled", "ParticleType", "CloserType", "MenuBlurEnabled", "ToggleUIKey",
         
        "ProfileData",
         
        "FastMegaTargets", "FastMegaEggTargets", "SWFTargets", "HatchPriority", "HatchLimits", "EcoSavedSettings",
        "AutofarmEnabled", "PetFarmEnabled", "BabyAutofarmEnabled", "EcoFarmEnabled", "AutoHatch", "SWFEnabled", "AutoAgePot", "FastMegaEnabled",
        "SwfMode", "SwfSplitMode", "FastMegaMode", "FastMegaFarmPots", "FastMegaPipeline", "FastMegaPipeMode", "HatchDisabled", "FastMegaBlocked", "FastMegaEggBlocked",
         
        "PlatformColor", "PlatformMaterial", "PlatformTransparency", "PlatformReflectance", 
        "PlatformTextureEnabled", "PlatformTextureID", "PlatformTextureMode", "PlatformTextureScale",
        "CustomSkyEnabled", "CustomSkyID",
         
        "AutoBuyEnabled", "AutoBuyTargets", "GlobalBuyAmount",
        "AutoBuyPetWearEnabled", "PetWearBuyLimit", "CurrentSelectedPetWears",
        "ManualBuyAmount",
        "BucksTransferEnabled", "TransferMethods", "TransferTarget", 
        "MannequinPrice", "MannequinAutoChange",
         
        "VisualBucksAmount", "LoopGettingBucks", "VisualBucksCooldown",
        "SavedPetVisuals", "VisualVars",
        "PotionFeederEnabled", "FeederTargetKinds", "FeederSelectedPotions", "FeederAmount", 
        "FeederUntilFG", "FeederAutoRenewal", "FeederAutoSelectEquipped",
        "AutoCombineEnabled", "CombineQueue", "CombineAutoFeed", "CombineTargetMode",
        "AutoLureEnabled", "SelectedBait",
        "PetPenAutoLoot", "PetPenLootAmount", "PetPenAutoAgeUp", "PetPenSWF", "PetPenHatchEggs",
        "PetPenPriority", "EggPenPriority", "PetPenPrioMode", "PetPenViewMode",
        "PetPenXPLimit", "PetPenXPMode", "AutoUnstackPets", "PetVisCustomColor",
         
        "MasterPopupsEnabled", "DisablePartyInvites", "DisableEventPopups", "DisableTradePopups",
         
        "TradeTargetPlayer", "AutoAcceptMode", "StartTradeTransfer", "AutoAcceptTrades",
        "AutoAddFood", "AutoAcceptOnlyGifts", "DisableTradeFeatures", "DisableTradePopups",
        "DisableTradeFrame", "TradeCategory", "TradeValueType", "TradeCalculatorEnabled",
        "ShowTradeDemands", "TradeBlacklist", "TradeFilters",
         
        "AutoCryptEnabled", "CryptMode", "HalloweenEventFarmEnabled", "GhostClusterEnabled", "AutoClaimHalloweenQuests",
         
        "AutoClaim2DTuesdays"
