    ["/raw/modules/adm_main/Icons"] = [==[local ItemData = {}

 
local CATEGORIES = {
    "pets", "food", "toys", "transport", "strollers", "pet_accessories", "gifts"
}

 
function ItemData:Init(Library, Window, Tab)
     
    getgenv().Icons = self
end

function ItemData:Get(Kind)
    local DefaultResponse = {
        Found = false,
        Name = Kind or "Unknown",
        Image = "rbxassetid://122697490518955",  
        RawDB = nil
    }

    if not Kind then return DefaultResponse end

     
    local InventoryDB = getgenv().DuskCore and getgenv().DuskCore.M and getgenv().DuskCore.M.InventoryDB
    if not InventoryDB then return DefaultResponse end

     
    for _, Category in ipairs(CATEGORIES) do
        if InventoryDB[Category] and InventoryDB[Category][Kind] then
            local Db = InventoryDB[Category][Kind]

            local name = Db.name or Kind
            local ImgRaw = Db.icon or Db.image or Db.shop_image or "122697490518955"
            local ImgFinal = ImgRaw
            
            if not string.find(tostring(ImgRaw), "rbxassetid") and tonumber(ImgRaw) then 
                ImgFinal = "rbxassetid://" .. imgRaw 
            end

            return {
                Found = true,
                Name = name,
                Image = ImgFinal,
                RawDB = Db 
            }
        end
    end

    return DefaultResponse
end

return ItemData]==],
