    ["/raw/modules/adm_main/teleports"] = [==[local TeleportsModule = {}

function TeleportsModule:Init()
    local DuskCore = getgenv().DuskCore
    if not DuskCore then return end

    local M = DuskCore.M
    local Plr = DuskCore.plr

     
    local SetIdentity = (syn and syn.set_thread_identity) or setthreadidentity or setidentity
    local GetIdentity = (syn and syn.get_thread_identity) or getthreadidentity or getidentity

     
    local function SafeTeleport(Dest, Door, Data)
        local CurrentId = GetIdentity and GetIdentity() or 7
        
        if SetIdentity then pcall(SetIdentity, 2) end
        
        local Success, err = pcall(function()
            M.InteriorsM.enter_smooth(Dest, Door, Data)
        end)
        
        if SetIdentity then pcall(SetIdentity, CurrentId) end
        
        if not Success then warn("[D&S] Teleport Error: ", Err) end
    end

     
    getgenv().DuskTeleportTo = function(Location)
        if getgenv().EcoFarmEnabled then
            if getgenv().DuskShine_Core then getgenv().DuskShine_Core:Notify("Error", "Disable Eco Farm before teleporting!", 3) end
            return
        end

        local TargetLocCFrame = nil
        local TargetLoc = nil

         
        pcall(function() game:GetService("RunService"):Set3dRenderingEnabled(true) end)
        task.wait(0.1)

         
        if Location == "Gifts Display" then
            TargetLocCFrame = workspace.Events.Gifts.BigGiftSign.Display.CFrame + Vector3.new(0, 0, 3)
            TargetLoc = "MainMap"
        elseif Location == "Playground" then
            TargetLocCFrame = workspace.StaticMap.Park.BoredAilmentTarget.CFrame + Vector3.new(0, 8, 0)
            TargetLoc = "MainMap"
        elseif Location == "Camping" then
            TargetLocCFrame = workspace.StaticMap.Campsite.CampsiteOrigin.CFrame + Vector3.new(3, 8, 3)
            TargetLoc = "MainMap"
        elseif Location == "Beach" then
            TargetLocCFrame = workspace.StaticMap.Beach.BeachPartyNavTarget.CFrame
            TargetLoc = "MainMap"
        else
             
            SafeTeleport(Location, "MainDoor", {})
            return
        end
        
         
        if TargetLoc and TargetLocCFrame then
            SafeTeleport(TargetLoc, "MainDoor", {["spawn_cframe"] = TargetLocCFrame})
        end
    end
end

return TeleportsModule]==],
