    }

     
     
     
    local function GetRegisterID(TargetName, RegType)
        local Interiors = workspace:FindFirstChild("HouseInteriors")
        local Furniture = Interiors and Interiors:FindFirstChild("furniture")
        if not Furniture then return nil end

        local CleanRegType = RegType:lower():gsub("_", "")
        for _, Item in pairs(Furniture:GetChildren()) do
            if string.find(Item.Name, "^" .. targetName) or string.find(Item.Name, TargetName) then
                local CleanItemName = Item.Name:lower():gsub("_", "")
                if string.find(CleanItemName, CleanRegType) then
                    local CleanID = string.match(Item.Name, "f%-%d+")
                    return CleanID or Item.Name
                end
            end
        end
        return nil
    end

    local function GetMannequinID(TargetName)
        local Interiors = workspace:FindFirstChild("HouseInteriors")
        local Furniture = Interiors and Interiors:FindFirstChild("furniture")
        if not Furniture then return nil end

        for _, Item in pairs(Furniture:GetChildren()) do
            if string.find(Item.Name, "^" .. targetName) or string.find(Item.Name, TargetName) then
                if Item:FindFirstChild("Mannequin") or string.find(Item.Name:lower(), "mannequin") then
                    local CleanID = string.match(Item.Name, "f%-%d+")
                    return CleanID or Item.Name
                end
            end
        end
        return nil
    end

     
     
     
    getgenv().FastMannequinSwap = function()
        if not getgenv().MannequinAutoChange then return false end

        local MyChar = workspace.PlayerCharacters:FindFirstChild(Plr.Name)
        if not MyChar then return false end
        
        local MyFid = GetMannequinID(Plr.Name)
        local ActivateFurnAPI = M.RouterClient.get("HousingAPI/ActivateFurniture")
        local APIFolder = game:GetService("ReplicatedStorage"):WaitForChild("API")
       
        if not MyFid then
            if getgenv().SetLiveStatus then getgenv().SetLiveStatus("Mannequin: Placing new mannequin...") end
            pcall(function()
                local Hrp = MyChar:FindFirstChild("HumanoidRootPart")
                local SpawnCf = Hrp and (Hrp.CFrame * CFrame.new(0, 0, -4)) or CFrame.new(0, 5, 0)
                M.RouterClient.get("HousingAPI/BuyFurnitures"):InvokeServer({{["kind"] = "mannequins_2024_mannequin", ["properties"] = { ["cframe"] = SpawnCf }}})
            end)
            task.wait(2)
            return true
        end

        if not getgenv().MannequinPriceSet then
            local PriceToSet = tonumber(getgenv().MannequinPrice) or 100
            pcall(function() ActivateFurnAPI:InvokeServer(Plr, MyFid, "UseBlock", {["set_price"] = true, ["price"] = PriceToSet}, MyChar) end)
            getgenv().MannequinPriceSet = true
            task.wait(0.5)
        end

        getgenv().MannequinToggleState = not getgenv().MannequinToggleState
        local OutfitName = getgenv().MannequinToggleState and "Skin1" or "Skin2"
        
        pcall(function()
            APIFolder:WaitForChild("AvatarAPI/StartEditingMannequin"):InvokeServer()
            task.wait(0.2)
            if getgenv().MannequinToggleState then
                APIFolder:WaitForChild("AvatarAPI/ResetToRobloxChar"):FireServer("mannequin")
            else
                APIFolder:WaitForChild("AvatarAPI/WearOutfit"):FireServer("mannequin", "Outfit")
            end
            task.wait(0.4)
            ActivateFurnAPI:InvokeServer(Plr, MyFid, "UseBlock", {["save_outfit"] = true, ["outfit_name"] = OutfitName}, MyChar)
        end)

        return true
    end

    task.spawn(function()
        local StartBucks = M.ClientData.get("money") or 0
        local SalesCount = 0

        while task.wait(1) do
            if not getgenv().MannequinAutoChange then 
                StartBucks = M.ClientData.get("money") or 0
                continue 
            end

            local CurrentBucks = M.ClientData.get("money") or 0
            if (CurrentBucks - StartBucks) >= (tonumber(getgenv().MannequinPrice) or 100) then
                SalesCount = SalesCount + 1
                StartBucks = CurrentBucks
                
                if getgenv().ReceiverStatusLbl then getgenv().ReceiverStatusLbl.Text = "Target Status: Sold " .. salesCount .. "/3" end

                if SalesCount >= 3 then
                    if getgenv().ReceiverStatusLbl then getgenv().ReceiverStatusLbl.Text = "Target Status: 180s Cooldown" end
                    task.wait(180)
                    SalesCount = 0
                else
                    if getgenv().FastMannequinSwap then getgenv().FastMannequinSwap() end
                end
            end
        end
    end)

     
     
     
    getgenv().StartTransferLoop = function(StatusLabel)
        task.spawn(function()
            local BuyOutfitAPI = game:GetService("ReplicatedStorage"):WaitForChild("API"):WaitForChild("AvatarAPI/BuyMannequinOutfit")
            getgenv().MannequinBoughtCount = 0

            local function SetStatus(text, Color)
                if StatusLabel then
                    StatusLabel.Text = "Status: " .. text
                    if Color then StatusLabel.TextColor3 = Color end
                end
                if getgenv().SetLiveStatus then getgenv().SetLiveStatus("Transfer: " .. text) end
            end

            while getgenv().BucksTransferEnabled do
                local Nick = getgenv().TransferTarget
                if not Nick or Nick == "" then break end
                local TargetPlayer = game:GetService("Players"):FindFirstChild(Nick)
                if not TargetPlayer then task.wait(1); continue end

                SetStatus("Subscribing to House...", Color3.fromRGB(255, 200, 50))
                pcall(function() API.SubscribeToHouse:FireServer(TargetPlayer) end)
                task.wait(2)

                local Queue = {}
                local Methods = getgenv().TransferMethods or {}
                if Methods.reg then table.insert(Queue, {id = "cash_register", type = "reg", amt = 50}) end
                if Methods.gold then table.insert(Queue, {id = "golden_cash_register", type = "gold", amt = 50}) end
                if Methods.man then table.insert(Queue, {id = "mannequin", type = "man", amt = 100}) end

                if #Queue == 0 then
                    SetStatus("No methods selected!", Color3.fromRGB(255, 50, 50))
                    task.wait(2)
                    continue
                end

                local MyChar = Plr.Character
                if not MyChar then task.wait(1); continue end

                for _, MethodData in ipairs(Queue) do
                    if not getgenv().BucksTransferEnabled then break end

                    local Fid = nil
                    if MethodData.type == "man" then
                        Fid = GetMannequinID(TargetPlayer.Name)
                    else
                        Fid = GetRegisterID(TargetPlayer.Name, MethodData.id)
                    end

                    if not Fid then continue end

                    if MethodData.type == "man" then
                        local AllData = M.ClientData.get_data()
                        local HouseData = AllData and AllData[TargetPlayer.Name] and AllData[TargetPlayer.Name].house_interior or M.ClientData.get("house_interior")
                        local FurnData = HouseData and HouseData.furniture and HouseData.furniture[Fid]
                        local RealOutfitId = FurnData and FurnData.outfit_version

                        if RealOutfitId then
                            pcall(function() BuyOutfitAPI:InvokeServer(TargetPlayer, Fid, RealOutfitId, 100) end)
                            getgenv().MannequinBoughtCount = getgenv().MannequinBoughtCount + 1
                            SetStatus("Mannequin Bought (" .. (getgenv().MannequinBoughtCount * 100) .. "$)", Color3.fromRGB(46, 204, 113))
                        end
                        task.wait(1.5)
                    else
                        SetStatus("Paying " .. methodData.type .. "...", Color3.fromRGB(255, 255, 255))
                        for I = 1, 3 do
                            if not getgenv().BucksTransferEnabled then break end
                            pcall(function() API.ActivateFurniture:InvokeServer(TargetPlayer, Fid, "UseBlock", {["expected_price"] = MethodData.amt}, MyChar) end)
                            task.wait(1.5)
                        end
                    end
                end

                SetStatus("Unsubscribing...")
                pcall(function() API.UnsubscribeFromHouse:InvokeServer(TargetPlayer) end)

                if getgenv().BucksTransferEnabled then
                    SetStatus("Cooldown 180s...", Color3.fromRGB(100, 150, 255))
                    for S = 180, 1, -1 do
                        if not getgenv().BucksTransferEnabled then break end
                        SetStatus("Next batch in: " .. s .. "s")
                        task.wait(1)
                    end
                end
            end

            SetStatus("Idle", Color3.fromRGB(150, 150, 150))
        end)
    end

     
     
     
    local function Normalize(Str)
        return tostring(Str):lower():gsub("[%s_%-]", "")
    end
    getgenv().NormalizeWearStr = Normalize

    local function GetClientData()
        local OldIdentity = getthreadidentity and getthreadidentity() or 8
        if setthreadidentity then setthreadidentity(2) end
        local Success, Fsys = pcall(function() return require(game:GetService("ReplicatedStorage"):WaitForChild("Fsys")) end)
        local ClientData = Success and Fsys.load("ClientData") or nil
        if setthreadidentity then setthreadidentity(OldIdentity) end
        return ClientData
    end

    getgenv().GetSplitPetWearLists = function()
        local ActiveStockMap = {}
        local ClientData = GetClientData()
        local Plr = game:GetService("Players").LocalPlayer

        if ClientData then
            local AllData = ClientData.get_data()
            local MyData = AllData and AllData[Plr.Name]
            if MyData and MyData.hat_shop_stock then
                for _, Item in pairs(MyData.hat_shop_stock) do
                    if type(Item) == "table" and Item.accessory_id then
                        local ServerID = Item.accessory_id
                        local ServerName = ServerID:gsub("^gifthat_%d+_", ""):gsub("^pet_accessories:", "")
                        ActiveStockMap[Normalize(ServerName)] = true
                    end
                end
            end
        end

        local StockList = {}
        local OtherList = {}
        local RarityWeight = { ["legendary"] = 1, ["ultra-rare"] = 2, ["rare"] = 3, ["uncommon"] = 4, ["common"] = 5 }

        for _, Item in ipairs(getgenv().PetWearItemList) do
            local NormName = Normalize(Item.name)
            local ItemData = { kind = Item.name, name = Item.name, rarity = Item.rarity, img = Item.img }
            if ActiveStockMap[NormName] then
                table.insert(StockList, ItemData)
            else
                table.insert(OtherList, ItemData)
            end
        end

        table.sort(StockList, function(A, B) return (RarityWeight[A.rarity] or 5) < (RarityWeight[B.rarity] or 5) end)
        table.sort(OtherList, function(A, B) return (RarityWeight[A.rarity] or 5) < (RarityWeight[B.rarity] or 5) end)
        
        return StockList, OtherList
    end

     
     
     
    getgenv().PerformSmartPurchase = function(ItemData, Amount)
        local TargetCategory = nil
        for Cat, Items in pairs(getgenv().ShopData) do
            for _, CheckItem in ipairs(Items) do
                if CheckItem.kind == ItemData.kind then TargetCategory = Cat; break end
            end
            if TargetCategory then break end
        end
        if not TargetCategory then return 0, Amount end

         
        local Currency = ItemData.currency or "bucks"
        local Balance = 0
        if Currency == "candy_2026" then
            Balance = M.ClientData.get("candy_2026") or M.ClientData.get("candy") or 0
        else
            Balance = M.ClientData.get("money") or 0
        end

        local ActualAmount = Amount
        if ItemData.price and ItemData.price > 0 then
            local MaxAffordable = math.floor(Balance / ItemData.price)
            ActualAmount = math.min(Amount, MaxAffordable)
        end
        
        if ActualAmount > 0 then 
            pcall(function()
                API.BuyItem:InvokeServer(TargetCategory, ItemData.kind, {["buy_count"] = ActualAmount})
            end)
        end

        return ActualAmount, Amount
    end

    local IsBuyingPetWear = false
    local BuyFunction = ReplicatedStorage:WaitForChild("API"):WaitForChild("ShopAPI/BuyItem")

    local function CheckAndBuyStock()
        if not getgenv().AutoBuyPetWearEnabled or IsBuyingPetWear then return end
        IsBuyingPetWear = true

        task.spawn(function()
            local ClientData = GetClientData()
            if not ClientData then IsBuyingPetWear = false; return end
            
            local AllData = ClientData.get_data()
            local MyData = AllData and AllData[Plr.Name]
            if not MyData or not MyData.hat_shop_stock then IsBuyingPetWear = false; return end

            for _, Item in pairs(MyData.hat_shop_stock) do
                if getgenv().PetWearBoughtCount >= getgenv().PetWearBuyLimit then
                    getgenv().AutoBuyPetWearEnabled = false
                    if getgenv().SetLiveStatus then getgenv().SetLiveStatus("Pet Wear Buy Limit Reached!") end
                    break
                end

                if type(Item) == "table" and Item.accessory_id then
                    local ServerID = Item.accessory_id
                    local ServerName = ServerID:gsub("^gifthat_%d+_", ""):gsub("^pet_accessories:", "")
                    local NormName = Normalize(ServerName)

                    if getgenv().CurrentSelectedPetWears[NormName] and not getgenv().AlreadyBoughtPetWears[ServerID] then
                        local Success = pcall(function()
                            return BuyFunction:InvokeServer("pet_accessories", ServerID, { buy_count = 1 })
                        end)
                        
                        if Success then
                            getgenv().AlreadyBoughtPetWears[ServerID] = true
                            getgenv().PetWearBoughtCount = getgenv().PetWearBoughtCount + 1
                            task.wait(0.5)
                        end
                    end
                end
            end
            IsBuyingPetWear = false 
        end)
    end
    getgenv().TriggerPetWearBuy = CheckAndBuyStock

     
     
     
    task.spawn(function()
        local LastStockSignature = ""
        while task.wait(1) do
            local ClientData = GetClientData()
            if ClientData then
                local AllData = ClientData.get_data()
                local MyData = AllData and AllData[Plr.Name]

                if MyData and MyData.hat_shop_stock then
                    local CurrentSignature = ""
                    for _, Item in pairs(MyData.hat_shop_stock) do
                        if type(Item) == "table" and Item.accessory_id then
                            CurrentSignature = CurrentSignature .. tostring(Item.accessory_id)
                        end
                    end

                    if CurrentSignature ~= LastStockSignature then
                        LastStockSignature = CurrentSignature
                        getgenv().AlreadyBoughtPetWears = {}
                        CheckAndBuyStock()
                        if getgenv().RenderPetWearShop then getgenv().RenderPetWearShop() end
                    end
                end
            end
        end
    end)

     
    task.spawn(function()
        while task.wait(0.5) do
            if getgenv().AutoBuyEnabled then
                local AmountSetting = getgenv().GlobalBuyAmount or 1
                local IsUnlimited = (type(AmountSetting) == "string" and AmountSetting:lower() == "unlimited") or AmountSetting == math.huge
                local TargetAmount = IsUnlimited and 0 or (tonumber(AmountSetting) or 1)

                for Kind, IsEnabled in pairs(getgenv().AutoBuyTargets) do
                    if IsEnabled then
                        local ItemData = nil
                        for Cat, Items in pairs(getgenv().ShopData) do
                            for _, Item in ipairs(Items) do
                                if Item.kind == Kind then ItemData = Item; break end
                            end
                            if ItemData then break end
                        end
                        
                        if ItemData then
                             
                            local Currency = ItemData.currency or "bucks"
                            local Balance = 0
                            if Currency == "candy_2026" then
                                Balance = M.ClientData.get("candy_2026") or M.ClientData.get("candy") or 0
                            else
                                Balance = M.ClientData.get("money") or 0
                            end

                            local Affordable = 0
                            if ItemData.price > 0 then
                                Affordable = math.floor(Balance / ItemData.price)
                            else
                                Affordable = IsUnlimited and 30 or TargetAmount
                            end
                            
                            if IsUnlimited and Affordable > 0 then
                                pcall(function() 
                                    API.BuyItem:InvokeServer(ItemData.api_cat or "pets", ItemData.kind, {["buy_count"] = Affordable}) 
                                end)
                                getgenv().AutoBuyCount = getgenv().AutoBuyCount + Affordable
                                task.wait(0.5)
                                
                            elseif not IsUnlimited and Affordable >= TargetAmount then
                                pcall(function() 
                                    API.BuyItem:InvokeServer(ItemData.api_cat or "pets", ItemData.kind, {["buy_count"] = TargetAmount}) 
                                end)
                                getgenv().AutoBuyCount = getgenv().AutoBuyCount + TargetAmount
                                task.wait(0.5)
                            end
                        end
                    end
                end
            end
        end
    end)
end

