            if Days == 0 and Hours == 0 and Mins == 0 then TimeString = "< 1m" end

             
            pcall(function()
                LblFirst.Text = tostring(Pd.FirstInjected) .. " (" .. tostring(Pd.FirstVersion or "v3.3.4") .. ")"
                LblTime.Text = TimeString
                LblPots.Text = FormatNumber(Pd.AgePotionsFarmed or 0)
                LblBucks.Text = FormatNumber(Pd.BucksEarned or 0) .. " $"
            end)
        end
    end)

     
     
     
