                Lbl.TextColor3 = Color3.fromRGB(150, 255, 150)
                Lbl.TextXAlignment = Enum.TextXAlignment.Left
                Lbl.Text = LogMsg
                Lbl.Parent = Scroll
                
                task.delay(0.05, function() Scroll.CanvasPosition = Vector2.new(0, Scroll.AbsoluteCanvasSize.Y) end)
                
                local Logs = Scroll:GetChildren()
                local Count = 0
                for _, V in ipairs(Logs) do if V:IsA("TextLabel") then Count = Count + 1 end end
                if Count > 40 then
                    for _, V in ipairs(Logs) do if V:IsA("TextLabel") then V:Destroy() break end end
                end
            end
        end
    end

