            TweenService:Create(Shadow, TweenInfo.new(0.2), {ImageTransparency = 0.8}):Play()
        end)
        
        ExitBtn.MouseLeave:Connect(function()
            TweenService:Create(ExitBtn, TweenInfo.new(0.2), {BackgroundTransparency = 0.2}):Play()
