            TweenService:Create(Shadow, TweenInfo.new(0.2), {ImageTransparency = 0.9}):Play()
        end)

        ExitBtn.MouseButton1Click:Connect(function()
             
            pcall(function() setfpscap(0) end)
            pcall(function() RunService:Set3dRenderingEnabled(true) end)
            
