            for _, V in pairs(Lighting:GetDescendants()) do
                if V:IsA("PostEffect") or V:IsA("Atmosphere") or V:IsA("Sky") then V:Destroy() end
            end
            for _, V in pairs(Workspace:GetDescendants()) do
                if V:IsA("BasePart") and not V:IsA("MeshPart") then
                    V.Material = Enum.Material.SmoothPlastic; V.Reflectance = 0; V.CastShadow = false
                elseif V:IsA("Decal") or V:IsA("Texture") or V:IsA("ParticleEmitter") or V:IsA("Trail") then
                    V:Destroy()
                elseif V:IsA("MeshPart") then
                    V.Material = Enum.Material.SmoothPlastic; V.TextureID = ""
                end
            end
            if Workspace:FindFirstChildOfClass("Terrain") then Workspace.Terrain:Clear() end
        end)

        getgenv().EcoLog("System Check: Map graphics nuked. RAM freed.")
    end

    getgenv().AutoHatch = getgenv().AutoHatch or false
    getgenv().HatchPriority = getgenv().HatchPriority or {} 
    getgenv().HatchDisabled = getgenv().HatchDisabled or {} 
    getgenv().HatchLimits = getgenv().HatchLimits or {}
    getgenv().ActiveHatchUIDs = {}

    local function ProcessHatchQueue()
        if not getgenv().AutoHatch then return end
        local AllData = M.ClientData.get_data() or {}
        local PlayerData = AllData[Plr.Name] or {}
        local Inv = AllData.inventory or PlayerData.inventory or M.ClientData.get("inventory")
        if not Inv or not Inv.pets then return end
        local EqMan = AllData.equip_manager or PlayerData.equip_manager or M.ClientData.get("equip_manager")
        local SubManager = AllData.subscription_manager or PlayerData.subscription_manager or M.ClientData.get("subscription_manager")
        local Ipm = AllData.idle_progression_manager or PlayerData.idle_progression_manager or M.ClientData.get("idle_progression_manager")
        if not Inv or not Inv.pets then return end
        local ActivePets = EqMan and EqMan.pets or {}
        local EquippedUIDs = {}
        for _, P in ipairs(ActivePets) do table.insert(EquippedUIDs, P.unique) end

        getgenv().CachedMaxSlots = getgenv().CachedMaxSlots or 1
        if SubManager and SubManager.equip_2x_pets then
            local State = tostring(SubManager.equip_2x_pets.state):lower()
            if State ~= "neversubscribed" and State ~= "expired" and State ~= "canceled" then
                getgenv().CachedMaxSlots = 2
            else
                getgenv().CachedMaxSlots = 1
            end
        end
        local MaxSlots = getgenv().CachedMaxSlots
        local LockedUIDs = {}
        if Ipm and Ipm.active_pets then for LUid, _ in pairs(Ipm.active_pets) do LockedUIDs[LUid] = true end end

        local AvailableEggs = {}
        local TotalValidEggs = 0

         
        for Uid, PData in pairs(Inv.pets) do
            if LockedUIDs[Uid] then continue end
            local Kind = PData.kind or PData.id
            local Db = M.InventoryDB.pets[Kind]
            
            if Db and Db.is_egg and not getgenv().HatchDisabled[Kind] then
                local Limit = getgenv().HatchLimits[Kind] or 0
                local Hatched = getgenv().HatchedSessionCounts[Kind] or 0
                
                if Limit == 0 or Hatched < Limit then
                    if not AvailableEggs[Kind] then AvailableEggs[Kind] = {} end
                    table.insert(AvailableEggs[Kind], Uid)
                    TotalValidEggs = TotalValidEggs + 1
                end
            end
        end

         
        for Kind, Uids in pairs(AvailableEggs) do
            table.sort(Uids)
        end

         
        if TotalValidEggs == 0 then
            getgenv().AutoHatch = false
            table.clear(getgenv().ActiveHatchUIDs)
            if getgenv().EcoLog then getgenv().EcoLog("Auto Hatch stopped: No valid eggs found or limits reached.") end
            return
        end

        local IdealEquip = {}

         
        for _, ActiveUid in ipairs(EquippedUIDs) do
            for Kind, Uids in pairs(AvailableEggs) do
                if table.find(Uids, ActiveUid) then
                     
                    local IsPriority = (#getgenv().HatchPriority == 0) or table.find(getgenv().HatchPriority, Kind)
                    if IsPriority then
                        table.insert(IdealEquip, ActiveUid)
                        break
                    end
                end
            end
            if #IdealEquip >= MaxSlots then break end
        end
        
         
        if #IdealEquip < MaxSlots then
            for _, PriorityKind in ipairs(getgenv().HatchPriority) do
                if AvailableEggs[PriorityKind] then
                    for _, Uid in ipairs(AvailableEggs[PriorityKind]) do
                        if not table.find(IdealEquip, Uid) then
                            table.insert(IdealEquip, Uid)
                            if #IdealEquip >= MaxSlots then break end
                        end
                    end
                end
                if #IdealEquip >= MaxSlots then break end
            end
        end

         
        if #IdealEquip < MaxSlots and #getgenv().HatchPriority == 0 then
            for Kind, Uids in pairs(AvailableEggs) do
                for _, Uid in ipairs(Uids) do
                    if not table.find(IdealEquip, Uid) then
                        table.insert(IdealEquip, Uid)
                        if #IdealEquip >= MaxSlots then break end
                    end
                end
                if #IdealEquip >= MaxSlots then break end
            end
        end

         
        local NeedsEquip = false
        if #IdealEquip ~= #EquippedUIDs then
            NeedsEquip = true
        else
            for _, Uid in ipairs(IdealEquip) do
                if not table.find(EquippedUIDs, Uid) then NeedsEquip = true; break end
            end
        end

        if not NeedsEquip then return end  

         
        table.clear(getgenv().ActiveHatchUIDs)
        
         
        for _, Uid in ipairs(EquippedUIDs) do
            if not table.find(IdealEquip, Uid) then
                task.spawn(function() pcall(function() API.Unequip:InvokeServer(Uid) end) end)
                task.wait(1.5)
            end
        end

         
        for Index, Uid in ipairs(IdealEquip) do
            local Kind = Inv.pets[Uid].kind or Inv.pets[Uid].id
            getgenv().ActiveHatchUIDs[Uid] = Kind
            
            if not table.find(EquippedUIDs, Uid) then
                if getgenv().EcoLog then getgenv().EcoLog("Equipping egg: " .. tostring(Kind)) end
                task.spawn(function()
                    pcall(function() 
                        API.Equip:InvokeServer(Uid, {
                            ["use_sound_delay"] = true, 
                            ["equip_as_last"] = (Index > 1)
                        }) 
                    end)
                end)
                task.wait(1.5)
            end
        end
    end
    
     
    getgenv().ProcessHatchQueue = ProcessHatchQueue

    getgenv().AutoAgePot = getgenv().AutoAgePot or false

    local function ProcessAgePotQueue()
        local IsTimerActive = getgenv().FastMegaTimer and getgenv().FastMegaTimer > os.time()
        
        if not getgenv().AutoAgePot and not IsTimerActive then 
            return 
        end

        local AllData = M.ClientData.get_data() or {}
        local PlayerData = AllData[Plr.Name] or {}
        
        local Inv = AllData.inventory or PlayerData.inventory or M.ClientData.get("inventory")
        if not Inv or not Inv.pets then return end

        local EqMan = AllData.equip_manager or PlayerData.equip_manager or M.ClientData.get("equip_manager")
        local SubManager = AllData.subscription_manager or PlayerData.subscription_manager or M.ClientData.get("subscription_manager")
        local Ipm = AllData.idle_progression_manager or PlayerData.idle_progression_manager or M.ClientData.get("idle_progression_manager")


        local MaxSlots = 1
        if SubManager and SubManager.equip_2x_pets then
            local State = tostring(SubManager.equip_2x_pets.state):lower()
            if State ~= "neversubscribed" and State ~= "expired" and State ~= "canceled" then
                MaxSlots = 2
            end
        end

        local ActivePets = EqMan and EqMan.pets or {}
        local EquippedUIDs = {}
        for _, P in ipairs(ActivePets) do EquippedUIDs[P.unique] = true end

        local IdealEquip = {}

         
        for _, P in ipairs(ActivePets) do
            local Uid = P.unique
            local PData = Inv.pets[Uid]
            if PData then
                local Kind = PData.kind or PData.id
                local Db = M.InventoryDB.pets[Kind]
                if Db and not Db.is_egg then
                    local Props = PData.properties or {}
                     
                    if Props.age == 6 then
                        table.insert(IdealEquip, Uid)
                        if #IdealEquip >= MaxSlots then break end
                    end
                end
            end
        end

         
        local LockedUIDs = {}
        if Ipm and Ipm.active_pets then for LUid, _ in pairs(Ipm.active_pets) do LockedUIDs[LUid] = true end end

         
        if #IdealEquip < MaxSlots then
            for Uid, PData in pairs(Inv.pets) do
                if LockedUIDs[Uid] then continue end
                 
                if not table.find(IdealEquip, Uid) then
                    local Kind = PData.kind or PData.id
                    local Db = M.InventoryDB.pets[Kind]
                    
                    if Db and not Db.is_egg then
                        local Props = PData.properties or {}
                        if Props.age == 6 then
                            table.insert(IdealEquip, Uid)
                            if #IdealEquip >= MaxSlots then break end
                        end
                    end
                end
            end
        end

        
        if #IdealEquip == 0 then
             
            if IsTimerActive then
                getgenv().FastMegaTimer = 0
            end
            
             
            if getgenv().AutoAgePot then
                getgenv().AutoAgePot = false
                if getgenv().AgePotToggleUI then pcall(function() getgenv().AgePotToggleUI.SetState(false) end) end
            end
            
            if getgenv().EcoLog then getgenv().EcoLog("Age Pot Farm stopped: No Full Grown/Mega pets found.") end
            return
        end

         
        local NeedsEquip = false
        if #IdealEquip ~= #ActivePets then
            NeedsEquip = true
        else
            for _, Uid in ipairs(IdealEquip) do
                if not EquippedUIDs[Uid] then NeedsEquip = true; break end
            end
        end

         
        if NeedsEquip then
            if getgenv().EcoLog then getgenv().EcoLog("Switching FG Pets for Age Potions...") end
             
            for _, P in ipairs(ActivePets) do
                if not table.find(IdealEquip, P.unique) then
                    pcall(function() API.Unequip:InvokeServer(P.unique) end)
                    task.wait(1.5)
                end
            end
            
             
            for Index, Uid in ipairs(IdealEquip) do
                if not EquippedUIDs[Uid] then
                    pcall(function() 
                        API.Equip:InvokeServer(Uid, {
                            ["use_sound_delay"] = true, 
                            ["equip_as_last"] = (Index == MaxSlots)
                        }) 
                    end)
                    task.wait(3.0)
                end
            end
        end
    end
    
    getgenv().ProcessAgePotQueue = ProcessAgePotQueue

    getgenv().SWFEnabled = getgenv().SWFEnabled or false
    getgenv().SwfMode = getgenv().SwfMode or "Regular"
    getgenv().SWFTargets = getgenv().SWFTargets or {}
    getgenv().SwfSplitMode = getgenv().SwfSplitMode or false
    getgenv().ExpectedSwfEquip = {}
    getgenv().LastSwfManualOverride = 0
    getgenv().SwfEquipCooldown = 0

    local function ProcessSWFQueue()
        if not getgenv().SWFEnabled then return end
        local AllData = M.ClientData.get_data() or {}
        local PlayerData = AllData[Plr.Name] or {}
        
        local Inv = AllData.inventory or PlayerData.inventory or M.ClientData.get("inventory")
        if not Inv or not Inv.pets then return end

        local EqMan = AllData.equip_manager or PlayerData.equip_manager or M.ClientData.get("equip_manager")
        local SubManager = AllData.subscription_manager or PlayerData.subscription_manager or M.ClientData.get("subscription_manager")
        local Ipm = AllData.idle_progression_manager or PlayerData.idle_progression_manager or M.ClientData.get("idle_progression_manager")

        local ActivePets = EqMan and EqMan.pets or {}
        local CurrentActiveUIDs = {}
        for _, P in ipairs(ActivePets) do table.insert(CurrentActiveUIDs, P.unique) end

        local Now = os.time()

         
        if #getgenv().ExpectedSwfEquip > 0 and Now > getgenv().SwfEquipCooldown then
            local UserInterfered = false
            
            if #getgenv().ExpectedSwfEquip ~= #CurrentActiveUIDs then
                UserInterfered = true
            else
                for _, ActiveUid in ipairs(CurrentActiveUIDs) do
                    if not table.find(getgenv().ExpectedSwfEquip, ActiveUid) then
                        UserInterfered = true
                        break
                    end
                end
            end

            if UserInterfered then
                if Now - getgenv().LastSwfManualOverride < 15 then
                     
                     
                    getgenv().ExpectedSwfEquip = {}
                    getgenv().SwfEquipCooldown = Now + 5
                    if getgenv().EcoLog then getgenv().EcoLog("SWF Sync: Network lag detected, recalculating queue.") end
                    return
                else
                    getgenv().LastSwfManualOverride = Now
                    if getgenv().EcoLog then getgenv().EcoLog("SWF Sync: Restoring expected pets.") end
                end
            end
        end

         
        getgenv().CachedMaxSlots = getgenv().CachedMaxSlots or 1
        if SubManager and SubManager.equip_2x_pets then
            local State = tostring(SubManager.equip_2x_pets.state):lower()
            if State ~= "neversubscribed" and State ~= "expired" and State ~= "canceled" then
                getgenv().CachedMaxSlots = 2
            else
                getgenv().CachedMaxSlots = 1
            end
        end
        local MaxSlots = getgenv().CachedMaxSlots

         
        local LockedUIDs = {}
        if Ipm and Ipm.active_pets then for LUid, _ in pairs(Ipm.active_pets) do LockedUIDs[LUid] = true end end

         
        local ValidPetsByKind = {}
        for Uid, PData in pairs(Inv.pets) do
            if LockedUIDs[Uid] then continue end
            local Kind = PData.kind or PData.id
            if getgenv().SWFTargets[Kind] then
                local Db = M.InventoryDB.pets[Kind]
                if Db and not Db.is_egg then
                    local Props = PData.properties or {}
                    
                    local IsMega = (Props.mega_neon == true or Props.mega_neon == 1 or Props.is_mega == true or Props.is_mega == 1)
                    local IsNeon = (Props.neon == true or Props.neon == 1 or Props.is_neon == true or Props.is_neon == 1)
                    local Age = tonumber(Props.age) or 1

                    if not IsMega and Age < 6 then
                        if (getgenv().SwfMode == "Neon" and IsNeon) or (getgenv().SwfMode == "Regular" and not IsNeon) then
                            if not ValidPetsByKind[Kind] then ValidPetsByKind[Kind] = {} end
                             
                            table.insert(ValidPetsByKind[Kind], {uid = Uid, age = Age})
                        end
                    end
                end
            end
        end

         
        local SortedKinds = {}
        for Kind, PetsList in pairs(ValidPetsByKind) do
            table.insert(SortedKinds, Kind)
             
            table.sort(PetsList, function(A, B) return A.age > B.age end)
        end
        table.sort(SortedKinds)  

        local IdealEquip = {}
        local UsedKinds = {}

         
         
        for _, ActiveUid in ipairs(CurrentActiveUIDs) do
            for _, Kind in ipairs(SortedKinds) do
                local Uids = ValidPetsByKind[Kind]
                local Found = false
                for _, PetData in ipairs(Uids) do
                    if PetData.uid == ActiveUid then
                        if getgenv().SwfSplitMode and UsedKinds[Kind] then break end
                        table.insert(IdealEquip, ActiveUid)
                        UsedKinds[Kind] = true
                        Found = true
                        break
                    end
                end
                if Found then break end
            end
            if #IdealEquip >= MaxSlots then break end
        end

         
        if #IdealEquip < MaxSlots then
            if getgenv().SwfSplitMode then
                for _, Kind in ipairs(SortedKinds) do
                    if not UsedKinds[Kind] then
                        for _, PetData in ipairs(ValidPetsByKind[Kind]) do
                            if not table.find(IdealEquip, PetData.uid) then
                                table.insert(IdealEquip, PetData.uid)
                                UsedKinds[Kind] = true
                                break
                            end
                        end
                    end
                    if #IdealEquip >= MaxSlots then break end
                end
                
                if #IdealEquip < MaxSlots then
                    for _, Kind in ipairs(SortedKinds) do
                        for _, PetData in ipairs(ValidPetsByKind[Kind]) do
                            if not table.find(IdealEquip, PetData.uid) then
                                table.insert(IdealEquip, PetData.uid)
                                if #IdealEquip >= MaxSlots then break end
                            end
                        end
                        if #IdealEquip >= MaxSlots then break end
                    end
                end
            else
                for _, Kind in ipairs(SortedKinds) do
                    for _, PetData in ipairs(ValidPetsByKind[Kind]) do
                        if not table.find(IdealEquip, PetData.uid) then
                            table.insert(IdealEquip, PetData.uid)
                            if #IdealEquip >= MaxSlots then break end
                        end
                    end
                    if #IdealEquip >= MaxSlots then break end
                end
            end
        end

        if #IdealEquip == 0 then
            getgenv().ExpectedSwfEquip = {}
            return 
        end

         
        local NeedsEquip = false
        if #IdealEquip ~= #CurrentActiveUIDs then
            NeedsEquip = true
        else
            for _, Uid in ipairs(IdealEquip) do
                if not table.find(CurrentActiveUIDs, Uid) then NeedsEquip = true; break end
            end
        end

        if NeedsEquip then
            if getgenv().EcoLog then getgenv().EcoLog("SWF: Swapping pets to target candidates...") end
            getgenv().SwfEquipCooldown = Now + 10 

            for _, Uid in ipairs(CurrentActiveUIDs) do
                if not table.find(IdealEquip, Uid) then
                    task.spawn(function() pcall(function() API.Unequip:InvokeServer(Uid) end) end)
                    task.wait(1.5)
                end
            end
            
            for Index, Uid in ipairs(IdealEquip) do
                if not table.find(CurrentActiveUIDs, Uid) then
                    task.spawn(function()
                        pcall(function() 
                            API.Equip:InvokeServer(Uid, {
                                ["use_sound_delay"] = true, 
                                ["equip_as_last"] = (Index == MaxSlots)
                            }) 
                        end)
                    end)
                    task.wait(1.5)
                end
            end
            
            getgenv().ExpectedSwfEquip = IdealEquip
        end
    end

     
     
     
    getgenv().FastMegaTimer = 0

    local function ProcessFastMegaQueue()
        local DuskCore = getgenv().DuskCore
        local M = DuskCore.M
        local API = DuskCore.API
        local CPrint = DuskCore.print or print 

        if not (getgenv().FastMegaEnabled or getgenv().FastMegaPipeline) or not getgenv().AutofarmEnabled then 
            if getgenv().FastMegaWasActive then
                getgenv().AutoCombineEnabled = false
                getgenv().PotionFeederEnabled = false
                getgenv().AutoAgePot = false
                getgenv().FastMegaWasActive = false
                CPrint("🛑 [Fast Mega] Paused. Waiting for Master Autofarm or turned off.")
            end
            return 
        end
        
        getgenv().FastMegaWasActive = true
        local AllData = M.ClientData.get_data() or {}
        local PlayerData = AllData[Plr.Name] or {}
        local Inv = AllData.inventory or PlayerData.inventory or M.ClientData.get("inventory")
        if not Inv or not Inv.pets then return end

        local EqMan = AllData.equip_manager or PlayerData.equip_manager or M.ClientData.get("equip_manager")
        local Ipm = AllData.idle_progression_manager or PlayerData.idle_progression_manager or M.ClientData.get("idle_progression_manager")
        
        local Now = os.time()
        local PotCount = 0
        if Inv.food then
            for _, F in pairs(Inv.food) do
                local Fid = F.id or F.kind
                if Fid == "pet_age_potion" or Fid == "age_potion" or Fid == "small_age_potion" or Fid == "super_age_potion" then PotCount = PotCount + 1 end
            end
        end
        
         
        if getgenv().FastMegaFarmPots then
            if PotCount < 7 and getgenv().FastMegaTimer == 0 and getgenv().AutoCombineEnabled then
                getgenv().FastMegaTimer = Now + 3600
                CPrint("⚠️ [Fast Mega] Potions < 7 (" .. potCount .. "). Starting 1-Hour Age-Pot Farm!")
                if getgenv().EcoLog then getgenv().EcoLog("Fast Mega: Low potions. Farming Age Pots for 1 hour.") end
            end
            
            if getgenv().FastMegaTimer > Now then
                getgenv().AutoCombineEnabled = false 
                getgenv().PotionFeederEnabled = false
                
                 
                if getgenv().ProcessAgePotQueue then getgenv().ProcessAgePotQueue() end
                return 
            else
                if getgenv().FastMegaTimer ~= 0 then 
                    CPrint("✅ [Fast Mega] 1-Hour Pot Farm finished. Resuming Mega logic.") 
                    getgenv().AutoCombineEnabled = true
                end
                getgenv().FastMegaTimer = 0
            end
        end

         
        if getgenv().FastMegaPipeline and getgenv().FastMegaPipeMode == "Selected" then
            local HasSelection = false
            for _, V in pairs(getgenv().FastMegaTargets or {}) do if V then HasSelection = true break end end
            if not HasSelection then
                for _, V in pairs(getgenv().FastMegaEggTargets or {}) do if V then HasSelection = true break end end
            end
            if not HasSelection then
                if getgenv().FastMegaWasActive then CPrint("🛑 [Pipeline] MODE: SELECTED, but NO Eggs or Pets are chosen! Paused.") end
                getgenv().AutoCombineEnabled = false; getgenv().PotionFeederEnabled = false; getgenv().AutoAgePot = false
                return
            end
        end
        
        local TargetKindsList = {}
        if getgenv().FastMegaPipeline and getgenv().FastMegaPipeMode == "All" then
            for _, PData in pairs(Inv.pets) do
                local Kind = PData.kind or PData.id
                local Db = M.InventoryDB.pets[Kind]
                if Db and not Db.is_egg and not table.find(TargetKindsList, Kind) then
                    table.insert(TargetKindsList, Kind)
                end
            end
        else
            for Kind, IsSelected in pairs(getgenv().FastMegaTargets or {}) do
                if IsSelected then table.insert(TargetKindsList, Kind) end
            end
        end

         
        local LockedUIDs = {}
        if Ipm and Ipm.active_pets then for LUid, _ in pairs(Ipm.active_pets) do LockedUIDs[LUid] = true end end

         
        local ValidToEquip = {}
        for Uid, PData in pairs(Inv.pets) do
            if LockedUIDs[Uid] then continue end
            local Kind = PData.kind or PData.id
            local Db = M.InventoryDB.pets[Kind]
            
            if Db and not Db.is_egg then
                local IsAllowed = false
                if getgenv().FastMegaPipeline and getgenv().FastMegaPipeMode == "All" and not (getgenv().FastMegaBlocked and getgenv().FastMegaBlocked[Kind]) then
                    IsAllowed = true
                else
                    IsAllowed = (getgenv().FastMegaTargets and getgenv().FastMegaTargets[Kind] == true)
                end
                
                if IsAllowed then
                    local Age = (PData.properties and PData.properties.age) or 1
                    local IsNeon = PData.properties.neon or PData.properties.is_neon
                    local IsMega = PData.properties.mega_neon or PData.properties.is_mega
                    
                    if not IsMega and Age < 6 then
                        if getgenv().FastMegaMode == "Neon" and not IsNeon then table.insert(ValidToEquip, Uid) 
                        elseif getgenv().FastMegaMode == "Mega" then table.insert(ValidToEquip, Uid) end
                    end
                end
            end
        end
        
        local CurrentEq = EqMan and EqMan.pets and EqMan.pets[1] and EqMan.pets[1].unique

        if #ValidToEquip > 0 then
            getgenv().AutoAgePot = false
            if getgenv().AgePotToggleUI then pcall(function() getgenv().AgePotToggleUI.SetState(false) end) end
            getgenv().SWFEnabled = false 
        
            local IsCurrentValid = table.find(ValidToEquip, CurrentEq) ~= nil
            if not IsCurrentValid then
                local TargetUid = ValidToEquip[1]
                CPrint("🔄 [Fast Mega] Forced Equip! Found valid pet -> " .. tostring(TargetUid))
                task.spawn(function()
                    if CurrentEq then
                        pcall(function() API.Unequip:InvokeServer(CurrentEq) end)
                        task.wait(0.5)
                    end
                    pcall(function() API.Equip:InvokeServer(TargetUid, {["equip_as_last"] = true}) end)
                end)
                getgenv().PotionFeederEnabled = false 
                return
            end
        else
             
            getgenv().AutoAgePot = false
            if getgenv().AgePotToggleUI then pcall(function() getgenv().AgePotToggleUI.SetState(false) end) end
            getgenv().SWFEnabled = false
            getgenv().AutoCombineEnabled = false

             
            local EggEquipped = false
            local TargetEggUid = CurrentEq

            if getgenv().FastMegaPipeline then
                if CurrentEq and Inv.pets[CurrentEq] then
                    local PData = Inv.pets[CurrentEq]
                    local Kind = PData.kind or PData.id
                    local Db = M.InventoryDB.pets[Kind]
                    if Db and Db.is_egg then
                        if getgenv().FastMegaPipeMode == "All" and not (getgenv().FastMegaEggBlocked and getgenv().FastMegaEggBlocked[Kind]) then
                            EggEquipped = true
                        elseif getgenv().FastMegaEggTargets and getgenv().FastMegaEggTargets[Kind] then
                            EggEquipped = true
                        end
                    end
                end

                if not EggEquipped then
                for Uid, PData in pairs(Inv.pets) do
                    if LockedUIDs[Uid] then continue end  
                    local Kind = PData.kind or PData.id
                        local Db = M.InventoryDB.pets[Kind]
                        if Db and Db.is_egg and not (getgenv().FastMegaEggBlocked and getgenv().FastMegaEggBlocked[Kind]) then
                            if getgenv().FastMegaPipeMode == "All" or (getgenv().FastMegaEggTargets and getgenv().FastMegaEggTargets[Kind]) then
                                CPrint("🥚 [Pipeline] Equipping egg -> " .. tostring(Kind))
                                task.spawn(function()
                                    if CurrentEq then
                                        pcall(function() API.Unequip:InvokeServer(CurrentEq) end)
                                        task.wait(0.8)
                                    end
                                    pcall(function() API.Equip:InvokeServer(Uid, {["equip_as_last"] = true}) end)
                                end)
                                getgenv().PotionFeederEnabled = false 
                                return
                            end
                        end
                    end
                end
            end

            if EggEquipped then
                getgenv().PotionFeederEnabled = false  
                CPrint("⏳ [Pipeline] Waiting for normal hatch...")
                return 
            end

            if #TargetKindsList == 0 and not EggEquipped then
                CPrint("⏳ [Fast Mega] Queue is empty. No pets or eggs to process.")
                getgenv().AutoCombineEnabled = false; getgenv().PotionFeederEnabled = false; getgenv().AutoAgePot = false
                return
            end

            CPrint("⏳ [Fast Mega] All target pets are Max Level! Falling back to Age-Pot Farm.")
            getgenv().AutoCombineEnabled = false; getgenv().PotionFeederEnabled = false
            if getgenv().ProcessAgePotQueue then getgenv().ProcessAgePotQueue() end
            return 
        end

         
        getgenv().CombineQueue = TargetKindsList
        getgenv().CombineTargetMode = string.upper(getgenv().FastMegaMode or "NEON")
        getgenv().AutoCombineEnabled = true
        
        getgenv().SWFEnabled = false 
        getgenv().AutoAgePot = false

        if not getgenv().PotionFeederEnabled then
            getgenv().UsedPotionUIDs = {}
            getgenv().FeederTargetKinds = {} 
            getgenv().FeederAutoSelectEquipped = true 
            getgenv().FeederUntilFG = true
            getgenv().FeederFedCount = 0
            getgenv().FeederSelectedPotions = {
                ["pet_age_potion"] = true, ["age_potion"] = true, ["small_age_potion"] = true, ["super_age_potion"] = true
            }
            getgenv().PotionFeederEnabled = true
        end
    end

     
    task.spawn(function()
        while task.wait(2.5) do
            if getgenv().DuskSessionID ~= getgenv().DuskSessionID then break end  
            
             
            if not getgenv().AutofarmEnabled then continue end
            
             
            if getgenv().IsBusyWithAction then continue end 
            
             
            local IsAnyActive = getgenv().AutoHatch or getgenv().SWFEnabled or getgenv().AutoAgePot or getgenv().FastMegaEnabled or getgenv().FastMegaPipeline
            if not IsAnyActive then continue end

             
            local AllData = M.ClientData.get_data() or {}
            local PlayerData = AllData[Plr.Name] or {}
            
            local Inv = AllData.inventory or PlayerData.inventory or M.ClientData.get("inventory")
            if not Inv or not Inv.pets then continue end
            
            local EqMan = AllData.equip_manager or PlayerData.equip_manager or M.ClientData.get("equip_manager")
            local ActivePets = EqMan and EqMan.pets or {}

             
             
             
            if getgenv().AutoHatch then
                local NeedsEquip = false
                 
                for TrackingUid, _ in pairs(getgenv().ActiveHatchUIDs) do
                    local IsEquipped = false
                    for _, ActiveP in ipairs(ActivePets) do
                        if ActiveP.unique == TrackingUid then IsEquipped = true break end
                    end
                    if not IsEquipped then NeedsEquip = true break end
                end
                
                 
                if next(getgenv().ActiveHatchUIDs) == nil or NeedsEquip then
                    getgenv().ProcessHatchQueue()
                end
            end

             
             
             
            if getgenv().SWFEnabled and not getgenv().AutoHatch then
                ProcessSWFQueue()
            end

             
             
             
            if getgenv().AutoAgePot then
                getgenv().ProcessAgePotQueue()
            end

             
             
             
            if getgenv().FastMegaEnabled or getgenv().FastMegaPipeline then
                if type(ProcessFastMegaQueue) == "function" then
                    ProcessFastMegaQueue()
                end
            end
        end
    end)
end

