    local function CreateInstantSubPage(title)
        local SubPageUI = Library.Utils.Make("Frame", {
            Name = "InstantSubPage_" .. title:gsub("%s+", ""),
            Size = UDim2.new(1, 0, 1, 0), Position = UDim2.new(0, 0, 0, 0),
