        local CloseBtn = Library.Utils.Make("TextButton", { Text = "", Size = UDim2.new(0, 34, 0, 34), Position = UDim2.new(0, 10, 0, 10), BackgroundTransparency = 1, Parent = TopBar })
        local BtnBg = Library.Utils.Make("Frame", { Size = UDim2.new(1, 0, 1, 0), Parent = CloseBtn }, { BackgroundColor3 = "Section" })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 6), Parent = BtnBg})
        Library.Utils.Make("UIStroke", {Parent = BtnBg}, {Color = "Stroke"})
        
        local BgGrad = Instance.new("UIGradient", BtnBg)
        BgGrad.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(0.5, 0.6), NumberSequenceKeypoint.new(1, 0) })
        
        Library.Utils.Make("TextLabel", { Text = "←", Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 1, Font = Enum.Font.GothamBold, TextSize = 18, Parent = CloseBtn }, { TextColor3 = "Text" })

        Library:Connect(CloseBtn.MouseEnter, function() BtnBg.BackgroundColor3 = Library.CurrentTheme.Stroke end)
        Library:Connect(CloseBtn.MouseLeave, function() BtnBg.BackgroundColor3 = Library.CurrentTheme.Section end)

        Library.Utils.Make("TextLabel", { Text = title, Size = UDim2.new(1, -60, 0, 20), Position = UDim2.new(0, 55, 0, 17), BackgroundTransparency = 1, Font = Enum.Font.GothamBlack, TextSize = 16, TextXAlignment = Enum.TextXAlignment.Left, Parent = SubPageUI }, { TextColor3 = "Text" })

        local Scroll = Library.Utils.Make("ScrollingFrame", { Size = UDim2.new(1, 0, 1, -50), Position = UDim2.new(0, 0, 0, 50), BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 2, AutomaticCanvasSize = Enum.AutomaticSize.Y, CanvasSize = UDim2.new(0, 0, 0, 0), Parent = SubPageUI }, { ScrollBarImageColor3 = "SubText" })
        Library.Utils.Make("UIPadding", { PaddingTop = UDim.new(0, 5), PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12), PaddingBottom = UDim.new(0, 15), Parent = Scroll })

        local function Open()
            if SubPageUI.Visible then return end
            if #InstantNav.Stack == 0 then
                InstantNav.SavedCanvasPos = Tab.Page.CanvasPosition  
                table.clear(InstantNav.HiddenRootElements)
                for _, Child in ipairs(Tab.Page:GetChildren()) do
                    if Child:IsA("GuiObject") and Child.Visible and not Child:IsA("UIListLayout") and not Child:IsA("UIPadding") then
                        table.insert(InstantNav.HiddenRootElements, Child)
                        Child.Visible = false
                    end
                end
            else
                InstantNav.Stack[#InstantNav.Stack].Visible = false
            end
            SubPageUI.Visible = true
            Scroll.CanvasPosition = Vector2.new(0, 0)
            table.insert(InstantNav.Stack, SubPageUI)
        end

        local function Close()
            if InstantNav.Stack[#InstantNav.Stack] ~= SubPageUI then return end
            table.remove(InstantNav.Stack, #InstantNav.Stack)
            SubPageUI.Visible = false
            if #InstantNav.Stack == 0 then
                for _, Child in ipairs(InstantNav.HiddenRootElements) do if Child then Child.Visible = true end end
                table.clear(InstantNav.HiddenRootElements)
                task.spawn(function() task.wait(); Tab.Page.CanvasPosition = InstantNav.SavedCanvasPos end)  
            else
                InstantNav.Stack[#InstantNav.Stack].Visible = true
            end
        end

        CloseBtn.MouseButton1Click:Connect(Close)
        return { Container = Scroll, Open = Open, Close = Close, UI = SubPageUI }
    end

     





































































































































































































































































































     
     
     
