    local function GetAutoBuyData()
        local ItemsList = {}
        for Category, Items in pairs(getgenv().ShopData or {}) do
            for _, Item in ipairs(Items) do
                local PImg = Item.image or "122697490518955"
                if not string.find(tostring(PImg), "rbxassetid") and tonumber(PImg) then PImg = "rbxassetid://"..pImg end
                
                 
                local CurrencySymbol = (Item.currency == "candy_2026") and " 🍬" or " $"
            local PriceTag = (Item.price == 0 and "FREE" or Item.price .. currencySymbol)
                
                table.insert(ItemsList, { id = Item.kind, name = Item.name, image = PImg, tags = (Item.price == 0 and "FREE" or Item.price .. currencySymbol) })
            end
        end
        table.sort(ItemsList, function(A, B) return A.name < B.name end)
        return ItemsList
    end

