    local function UpdateABVisuals(Val)
        local Pct = math.clamp((Val - AbMin) / (AbMax - AbMin), 0, 1)
        TweenService:Create(ABSliderFill, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Size = UDim2.new(Pct, 0, 1, 0)}):Play()
        
        if Val == AbMax then
            ABLimitInput.Text = "Unlimited"
            if not IsABUncapped then
                IsABUncapped = true
                if Library.ThemeObjects[ABLimitInput] then Library.ThemeObjects[ABLimitInput] = { TextColor3 = "Accent" } end
                if Library.ThemeObjects[ABInputStroke] then Library.ThemeObjects[ABInputStroke] = { Color = "Accent" } end
                TweenService:Create(ABLimitInput, TweenInfo.new(0.2), {TextColor3 = Library.CurrentTheme.Accent}):Play()
                TweenService:Create(ABInputStroke, TweenInfo.new(0.2), {Color = Library.CurrentTheme.Accent}):Play()
                ABInputScale.Scale = 0.85
                TweenService:Create(ABInputScale, TweenInfo.new(0.4, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1}):Play()
            end
        else
            ABLimitInput.Text = tostring(Val)
            if IsABUncapped then
                IsABUncapped = false
                if Library.ThemeObjects[ABLimitInput] then Library.ThemeObjects[ABLimitInput] = { TextColor3 = "Text" } end
                if Library.ThemeObjects[ABInputStroke] then Library.ThemeObjects[ABInputStroke] = { Color = "Stroke" } end
                TweenService:Create(ABLimitInput, TweenInfo.new(0.2), {TextColor3 = Library.CurrentTheme.Text}):Play()
                TweenService:Create(ABInputStroke, TweenInfo.new(0.2), {Color = Library.CurrentTheme.Stroke}):Play()
            end
        end
    end

    local function UpdateABSlider(Input, RawValue)
        local Val = RawValue
        if not Val then
            local Pos = math.clamp((Input.Position.X - ABSliderTrack.AbsolutePosition.X) / ABSliderTrack.AbsoluteSize.X, 0, 1)
            Val = math.floor(AbMin + ((AbMax - AbMin) * Pos))
        end
        Val = math.clamp(Val, AbMin, AbMax)
        CurrentVisualAB = Val
        UpdateABVisuals(CurrentVisualAB)
        getgenv().GlobalBuyAmount = (Val == AbMax) and 0 or Val
        if getgenv().SaveConfig then pcall(getgenv().SaveConfig) end
    end

