    local function ApplyABSearchFilter(Query)
        Query = Query:lower()
        if Query == "" then
            local Unselected, visibleCount = {}, 0
            for _, Tile in ipairs(AllAutoBuyTiles) do
                Tile.Frame.Visible = false; Tile.DimOverlay.BackgroundTransparency = 1 
                if getgenv().AutoBuyTargets[Tile.ID] then Tile.Frame.Visible = true; visibleCount = VisibleCount + 1 else table.insert(Unselected, Tile) end
            end
            for I = #Unselected, 2, -1 do local J = math.random(I); Unselected[I], Unselected[J] = Unselected[J], Unselected[I] end
            for I = 1, math.min(#Unselected, math.max(0, 6 - VisibleCount)) do Unselected[I].Frame.Visible = true end
        else
            for _, Tile in ipairs(AllAutoBuyTiles) do
                if string.find(Tile.Name, Query, 1, true) then Tile.Frame.Visible = true; TweenService:Create(Tile.DimOverlay, TweenInfo.new(0.3), {BackgroundTransparency = 1}):Play()
                else Tile.Frame.Visible = false end
            end
        end
    end

     
     
     
