    getgenv().RenderPetWearShop = function()
        local Query = PWSearchInput.Text:lower()
        for _, Child in ipairs(PWGridsContainer:GetChildren()) do if Child:IsA("GuiObject") and not Child:IsA("UIListLayout") then Child:Destroy() end end

        local StockList, otherList = {}, {}
        if getgenv().GetSplitPetWearLists then StockList, otherList = getgenv().GetSplitPetWearLists() end

        local LayoutOrderOffset = 1
        local function BuildSection(title, List)
            local Filtered = {}
            for _, Item in ipairs(List) do if Query == "" or Item.name:lower():find(Query, 1, true) then table.insert(Filtered, Item) end end
            if #Filtered == 0 then return end

            Library.Utils.Make("TextLabel", { Text = title, Size = UDim2.new(1, 0, 0, 30), BackgroundTransparency = 1, Font = Enum.Font.GothamBold, TextSize = 14, TextXAlignment = Enum.TextXAlignment.Left, LayoutOrder = LayoutOrderOffset, Parent = PWGridsContainer }, { TextColor3 = "Text" })
            LayoutOrderOffset = LayoutOrderOffset + 1
            
            local Grid = Library.Utils.Make("Frame", { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, LayoutOrder = LayoutOrderOffset, Parent = PWGridsContainer })
            LayoutOrderOffset = LayoutOrderOffset + 1
            Library.Utils.Make("UIGridLayout", { CellSize = UDim2.new(0, 175, 0, 175), CellPadding = UDim2.new(0, 12, 0, 12), SortOrder = Enum.SortOrder.LayoutOrder, HorizontalAlignment = Enum.HorizontalAlignment.Center, Parent = Grid })
            
            for _, Data in ipairs(Filtered) do
                local NormName = getgenv().NormalizeWearStr and getgenv().NormalizeWearStr(Data.kind) or Data.kind
                local IsTarget = getgenv().CurrentSelectedPetWears[NormName] == true
                
                local F = Library.Utils.Make("TextButton", { Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 0.3, Text = "", ClipsDescendants = true, Parent = Grid }, { BackgroundColor3 = "Section" })
                Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 12), Parent = F})
                
                local StrokeColor = IsTarget and Color3.fromRGB(46, 204, 113) or Color3.fromRGB(120, 120, 125)
                local Stroke = Library.Utils.Make("UIStroke", {Thickness = 1, Color = StrokeColor, Transparency = 0.6, Parent = F})
                local WaveGradient = Instance.new("UIGradient", Stroke)
                WaveGradient.Color = ColorSequence.new(Color3.new(1, 1, 1))
                local WaveAnim = TweenService:Create(WaveGradient, TweenInfo.new(1.5, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut, -1), {Rotation = 360})
                
                local Scale = Instance.new("UIScale", F)
                local HoverOverlay = Library.Utils.Make("Frame", { Size = UDim2.new(1, 0, 1, 0), BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 1, ZIndex = 2, Parent = F })
                Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 12), Parent = HoverOverlay})

                Library.Utils.Make("ImageLabel", { Size = UDim2.new(0.6, 0, 0.4, 0), Position = UDim2.new(0.2, 0, 0.1, 0), BackgroundTransparency = 1, ScaleType = Enum.ScaleType.Fit, Image = Data.img, ZIndex = 3, Parent = F })
                local RColor = RarityColors[Data.rarity] or Color3.fromRGB(200, 200, 200)
                local RarityLine = Library.Utils.Make("Frame", { Size = UDim2.new(0.6, 0, 0, 2), Position = UDim2.new(0.2, 0, 1, -45), BackgroundColor3 = RColor, BorderSizePixel = 0, ZIndex = 3, Parent = F })
                Library.Utils.Make("UICorner", {CornerRadius = UDim.new(1, 0), Parent = RarityLine})

                Library.Utils.Make("TextLabel", { Text = Data.name, Size = UDim2.new(1, -20, 0, 20), Position = UDim2.new(0, 12, 1, -32), BackgroundTransparency = 1, Font = Enum.Font.GothamBold, TextSize = 14, TextColor3 = Color3.fromRGB(255, 255, 255), TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, ZIndex = 3, Parent = F })
                local CheckmarkIcon = Library.Utils.Make("ImageLabel", { Image = "rbxassetid://115929304045144", Size = UDim2.new(0, 20, 0, 20), Position = UDim2.new(1, -30, 1, -30), BackgroundTransparency = 1, ImageColor3 = IsTarget and Color3.fromRGB(46, 204, 113) or Color3.fromRGB(255, 255, 255), ImageTransparency = IsTarget and 0 or 1, ZIndex = 5, Parent = F })

                F.MouseEnter:Connect(function()
                    local AccentColor = Library.CurrentTheme and Library.CurrentTheme.Accent or Color3.fromRGB(46, 204, 113)
                    local H, S, v = Color3.toHSV(AccentColor)
                    WaveGradient.Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, Color3.fromHSV(H, S, math.min(V + 0.4, 1))), ColorSequenceKeypoint.new(0.5, AccentColor), ColorSequenceKeypoint.new(1, Color3.fromHSV(math.fmod(H + 0.08, 1), S, V)) })
                    TweenService:Create(Stroke, TweenInfo.new(0.3), {Thickness = 2, Transparency = 0}):Play()
                    TweenService:Create(HoverOverlay, TweenInfo.new(0.3), {BackgroundTransparency = 0.88}):Play()
                    TweenService:Create(Scale, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1.02}):Play()
                    WaveAnim:Play()
                end)

                F.MouseLeave:Connect(function()
                    local IsNowTarget = getgenv().CurrentSelectedPetWears[NormName] == true
                    local DefaultStroke = Library.CurrentTheme and Library.CurrentTheme.Stroke or Color3.fromRGB(120, 120, 125)
                    TweenService:Create(Stroke, TweenInfo.new(0.3), {Thickness = 1, Color = IsNowTarget and Color3.fromRGB(46, 204, 113) or DefaultStroke, Transparency = 0.6}):Play()
                    TweenService:Create(HoverOverlay, TweenInfo.new(0.3), {BackgroundTransparency = 1}):Play()
                    TweenService:Create(Scale, TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Scale = 1}):Play()
                    WaveGradient.Color = ColorSequence.new(Color3.new(1, 1, 1)); WaveAnim:Cancel(); WaveGradient.Rotation = 0
                end)

                F.MouseButton1Click:Connect(function()
                    HoverOverlay.BackgroundTransparency = 0.7
                    TweenService:Create(HoverOverlay, TweenInfo.new(0.5), {BackgroundTransparency = 0.88}):Play()
                    TweenService:Create(Scale, TweenInfo.new(0.1), {Scale = 0.96}):Play()
                    task.delay(0.1, function() TweenService:Create(Scale, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1.02}):Play() end)
                    
                    getgenv().CurrentSelectedPetWears[NormName] = not getgenv().CurrentSelectedPetWears[NormName]
                    local IsNowTarget = getgenv().CurrentSelectedPetWears[NormName] == true
                    Stroke.Color = IsNowTarget and Color3.fromRGB(46, 204, 113) or Color3.fromRGB(120, 120, 125)
                    TweenService:Create(CheckmarkIcon, TweenInfo.new(0.2), {ImageTransparency = IsNowTarget and 0 or 1, ImageColor3 = IsNowTarget and Color3.fromRGB(46, 204, 113) or Color3.fromRGB(255, 255, 255)}):Play()
                    local ActionText = IsNowTarget and "Added" or "Removed"
                    Library:Notify("Pet Wear", ActionText .. " " .. data.name, 2, "rbxassetid://9405926389", "rbxassetid://72958619361915")
                    if getgenv().TriggerPetWearBuy then getgenv().TriggerPetWearBuy() end
                    if getgenv().SaveConfig then pcall(getgenv().SaveConfig) end
                end)
            end
        end
        BuildSection("🔥 Current Stock", StockList); BuildSection("📦 Rest of Shop", OtherList)
        if Query ~= "" then PWSearchInput:CaptureFocus(); PWSearchInput.CursorPosition = #PWSearchInput.Text + 1 end
    end
    PWSearchInput:GetPropertyChangedSignal("Text"):Connect(function() getgenv().RenderPetWearShop() end)


     
     
     
