    local ToggleBg = Library.Utils.Make("Frame", { Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 0.2, ClipsDescendants = true, Parent = ToggleBtn }, { BackgroundColor3 = ApState and "Accent" or "ToggleOff" })
    Library.Utils.Make("UICorner", {CornerRadius = UDim.new(1, 0), Parent = ToggleBg})
    local OnP = UDim2.new(1, -22, 0.5, -10); local OffP = UDim2.new(0, 2, 0.5, -10)
    local ToggleKnob = Library.Utils.Make("Frame", { Size = UDim2.new(0, 20, 0, 20), Position = ApState and OnP or OffP, Parent = ToggleBg }, { BackgroundColor3 = "Knob" })
    Library.Utils.Make("UICorner", {CornerRadius = UDim.new(1, 0), Parent = ToggleKnob})

    local function SetMasterAutoPurchase(NewState)
        ApState = NewState
         
        getgenv().AutoBuyEnabled = ApState
        getgenv().AutoBuyPetWearEnabled = ApState
        
        Library.ThemeObjects[ToggleBg] = { BackgroundColor3 = NewState and "Accent" or "ToggleOff" }
        local TargetColor = NewState and (Library.CurrentTheme and Library.CurrentTheme.Accent or Color3.fromRGB(46, 204, 113)) or (Library.CurrentTheme and Library.CurrentTheme.ToggleOff or Color3.fromRGB(55, 55, 60))
        Library.Utils.TBT(ToggleBg, 0.25, {BackgroundColor3 = TargetColor})
        TweenService:Create(ToggleKnob, TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Position = NewState and OnP or OffP}):Play()
        
        if NewState then
            Library.Utils.ApplyGradient(ToggleBg, Library.CurrentTheme and Library.CurrentTheme.Accent or Color3.fromRGB(46, 204, 113))
            Library:Notify("Auto Purchases", "Auto Buy (Items & Pet Wear) Started!", 3, "rbxassetid://9405926389", "rbxassetid://72958619361915")
            if getgenv().TriggerPetWearBuy then getgenv().TriggerPetWearBuy() end
        else
            local Grad = ToggleBg:FindFirstChild("DuskShine_Gradient")
            if Grad then Grad:Destroy() end
            Library:Notify("Auto Purchases", "Auto Purchases Stopped!", 2, "rbxassetid://9405926389", "rbxassetid://72958619361915")
        end
        if getgenv().SaveConfig then pcall(getgenv().SaveConfig) end
    end

