    local KindDB = getgenv().DuskCore.M.KindDB
    local LocalPlayer = game:GetService("Players").LocalPlayer
    local MPS = game:GetService("MarketplaceService")
    local ShopData = { pets = {}, gifts = {}, food = {}, toys = {}, strollers = {} }
    
     
    local HasVip = false
    pcall(function()
        HasVip = MPS:UserOwnsGamePassAsync(LocalPlayer.UserId, 3196348)
    end)

     
    local CurrentActiveEggs = {}
    
     
    local IgnoreList = {
        ["endangered_2026_endangered_egg"] = true,
        ["starter_egg"] = true
    }
    
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    
     
    pcall(function()
        local SharedConstants = require(ReplicatedStorage:WaitForChild("ClientDB"):WaitForChild("SharedConstants"))
        if SharedConstants and SharedConstants.egg_event then
            local PostEgg = SharedConstants.egg_event.gumball_egg_kind_post_release
            if PostEgg and type(PostEgg) == "string" and not IgnoreList[PostEgg] then 
                table.insert(CurrentActiveEggs, PostEgg)
            end
        end
    end)

     
    for Id, Data in pairs(KindDB) do
        if type(Data) == "table" and Data.is_egg and not Data.is_non_event_egg then
            local Year = Data.origin_entry and Data.origin_entry.year or 0
            if Year == 2026 and (Data.cost and Data.cost > 0) and not Data.unavailable and not Data.is_unavailable then
                if not IgnoreList[Id] and not table.find(CurrentActiveEggs, Id) then
                    table.insert(CurrentActiveEggs, Id)
                end
            end
        end
    end

     
    local AllowedStaticPets = { 
        cracked_egg = true, regular_pet_egg = true, royal_egg = true, sky_ux_2023_grinmoire = true 
    }
    if HasVip then
        AllowedStaticPets.retired_egg = true  
    end

    local AllowedGifts = {
        legend_hat_2022_simple_chest = true, legend_hat_2022_regal_chest = true,
        wings_2022_bucks_wing_chest = true, smallgift = true, biggift = true, massivegift = true
    }

    local AllowedFood = {
         
        big_head_potion = true, hyperspeed_potion = true, nograv_potion = true,
        pet_shrink_potion = true, pet_grow_potion = true, grow_potion = true, pet_translucency_potion = true,
        water = true, apple = true, free_pizza = true, ice_cream_2025_snow_cone = true,
        ice_cream_2025_cup = true, icecream = true, tea = true, hotdog = true, chocolate_milk = true,
        lemonade = true, cheese = true, watermelon = true, cotton_candy_stick = true,
        raspberry_pie = true, ham = true, coffee = true, camping_2023_smores = true,
        baby_bottle = true, smores = true, pet_food = true, pet_treat = true, babyformula = true,
         
        teachers_apple = true, healing_apple = true, schospital_refresh_2023_cafeteria_sandwich = true,
        pizza_shop_pizza = true, winter_2025_temp_hot_cocoa = true, donut = true,
        funiture_2025_cookie = true, sofahog_2024_diner_hot_dog_and_fries = true, water_paper_cup = true,
        soda_fountain_soda = true, royal_palace_2022_tea_party_scone = true, sofahog_2024_diner_mac_and_cheese = true,
        marshmallow_on_a_stick = true, sofahog_2024_diner_milkshake = true, sofahog_2024_diner_lemonade = true,
        sofahog_2024_diner_pancakes = true, sofahog_2024_diner_apple_pie = true
    }

     
    for Id, Data in pairs(KindDB) do
        if type(Data) == "table" and Data.category then
            local ItemData = {
                name = Data.name or Id,
                kind = Id,
                price = Data.cost or 0,
                image = Data.image or "122697490518955",
                vip_only = Data.vip_only or false,
                currency = Data.currency_id or "bucks"  
            }

            if Data.category == "pets" then
                if (AllowedStaticPets[Id] or table.find(CurrentActiveEggs, Id) or Data.currency_id == "candy_2026") and ItemData.price > 0 then
                    table.insert(ShopData.pets, ItemData)
                end
            elseif Data.category == "gifts" then
                if AllowedGifts[Id] then table.insert(ShopData.gifts, ItemData) end
            elseif Data.category == "food" then
                if AllowedFood[Id] then table.insert(ShopData.food, ItemData) end
             
            elseif Data.category == "toys" then
                if Data.currency_id == "candy_2026" then table.insert(ShopData.toys, ItemData) end
            elseif Data.category == "strollers" then
                if Data.currency_id == "candy_2026" then table.insert(ShopData.strollers, ItemData) end
            end
        end
    end

    local function SortByPrice(A, B) return A.price < B.price end
    table.sort(ShopData.pets, SortByPrice)
    table.sort(ShopData.gifts, SortByPrice)
    table.sort(ShopData.food, SortByPrice)
    table.sort(ShopData.toys, SortByPrice)
    table.sort(ShopData.strollers, SortByPrice)

