    Library.Utils.Make("UICorner", { CornerRadius = UDim.new(1, 0), Parent = ManKnob })
    local ManKnobScale = Instance.new("UIScale", ManKnob)

    local ManTrigger = Library.Utils.Make("TextButton", { Size = UDim2.new(1, 0, 0, 30), Position = UDim2.new(0, 0, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5), BackgroundTransparency = 1, Text = "", Parent = ManSliderTrack })

    local ManDragging = false
    local function UpdateManSlider(Input, RawValue)
        local Val = RawValue
        if not Val then
            local Pos = math.clamp((Input.Position.X - ManSliderTrack.AbsolutePosition.X) / ManSliderTrack.AbsoluteSize.X, 0, 1)
            Val = math.floor(ManMin + ((ManMax - ManMin) * Pos))
        end
        Val = math.clamp(Val, ManMin, ManMax)
        local Pct = (Val - ManMin) / (ManMax - ManMin)
        
         
        TweenService:Create(ManSliderFill, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Size = UDim2.new(Pct, 0, 1, 0)}):Play()
        ManLimitInput.Text = tostring(Val)
        getgenv().ManualBuyAmount = Val
    end

    ManLimitInput.FocusLost:Connect(function() 
        local Num = tonumber(ManLimitInput.Text)
        if Num then 
            UpdateManSlider(nil, Num) 
            Library:Notify("Purchase Amount", "Set to " .. tostring(getgenv().ManualBuyAmount), 2, "rbxassetid://6908632622", "rbxassetid://72958619361915")
        else 
            ManLimitInput.Text = tostring(getgenv().ManualBuyAmount) 
        end 
    end)
    
    local UIS = game:GetService("UserInputService")
    ManTrigger.InputBegan:Connect(function(Input) 
        if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then 
            ManDragging = true
            TweenService:Create(ManKnobScale, TweenInfo.new(0.2, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1.35}):Play()
            UpdateManSlider(Input) 
        end 
    end)
    UIS.InputEnded:Connect(function(Input) 
        if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then 
            if ManDragging then
                ManDragging = false
                TweenService:Create(ManKnobScale, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Scale = 1}):Play()
                Library:Notify("Purchase Amount", "Set to " .. tostring(getgenv().ManualBuyAmount), 2, "rbxassetid://6908632622", "rbxassetid://72958619361915")
            end
        end 
    end)
    UIS.InputChanged:Connect(function(Input) 
        if ManDragging and (Input.UserInputType == Enum.UserInputType.MouseMovement or Input.UserInputType == Enum.UserInputType.Touch) then 
            UpdateManSlider(Input) 
        end 
    end)
     
    local function BuildModernManualSection(CategoryName, CategoryKey)
        if not ShopData[CategoryKey] or #ShopData[CategoryKey] == 0 then return end

         
        local TitleContainer = Library.Utils.Make("Frame", { Size = UDim2.new(1, 0, 0, 30), BackgroundTransparency = 1, Parent = Tab.Page })
        Library.Utils.Make("TextLabel", { Text = CategoryName, Size = UDim2.new(1, 0, 1, 0), Position = UDim2.new(0, 5, 0, 5), BackgroundTransparency = 1, Font = Enum.Font.GothamBold, TextSize = 16, TextXAlignment = Enum.TextXAlignment.Left, Parent = TitleContainer }, { TextColor3 = "Text" })

        local GridContainer = Library.Utils.Make("Frame", { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, Parent = Tab.Page })
