            local F = Library.Utils.Make("TextButton", { Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 0.3, Text = "", ClipsDescendants = true, Parent = GridContainer }, { BackgroundColor3 = "Section" })
            Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 16), Parent = F})
            
            local Stroke = Library.Utils.Make("UIStroke", {Thickness = 1, Transparency = 0.6, Parent = F}, {Color = "Stroke"})
            local WaveGradient = Instance.new("UIGradient", Stroke)
