            local WaveAnim = TweenService:Create(WaveGradient, TweenInfo.new(1.5, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut, -1), {Rotation = 360})
            
            local Scale = Instance.new("UIScale", F)
