            Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 16), Parent = HoverOverlay})
            
            Library.Utils.Make("ImageLabel", { Size = UDim2.new(0.6, 0, 0.5, 0), Position = UDim2.new(0.2, 0, 0.1, 0), BackgroundTransparency = 1, ScaleType = Enum.ScaleType.Fit, Image = PImg, ZIndex = 3, Parent = F })
            Library.Utils.Make("TextLabel", { Text = PriceTag, Size = UDim2.new(1, -20, 0, 15), Position = UDim2.new(0, 15, 1, -45), BackgroundTransparency = 1, Font = Enum.Font.GothamMedium, TextSize = 11, TextColor3 = Item.price == 0 and Color3.fromRGB(46, 204, 113) or Color3.fromRGB(180, 180, 180), TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 3, Parent = F })
            Library.Utils.Make("TextLabel", { Text = Item.name, Size = UDim2.new(1, -30, 0, 20), Position = UDim2.new(0, 15, 1, -30), BackgroundTransparency = 1, Font = Enum.Font.GothamBold, TextSize = 14, TextColor3 = Color3.fromRGB(255, 255, 255), TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, ZIndex = 3, Parent = F })
            
             
            local CartIcon = Library.Utils.Make("ImageLabel", { Image = "rbxassetid://7733902979", Size = UDim2.new(0, 20, 0, 20), Position = UDim2.new(1, -30, 1, -30), BackgroundTransparency = 1, ImageTransparency = 1, ZIndex = 5, Parent = F }, {ImageColor3 = "Accent"})

            F.MouseEnter:Connect(function()
                local AccentColor = Library.CurrentTheme and Library.CurrentTheme.Accent or Color3.fromRGB(46, 204, 113)
                local H, S, v = Color3.toHSV(AccentColor)
                WaveGradient.Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, Color3.fromHSV(H, S, math.min(V + 0.4, 1))), ColorSequenceKeypoint.new(0.5, AccentColor), ColorSequenceKeypoint.new(1, Color3.fromHSV(math.fmod(H + 0.08, 1), S, V)) })
                
                TweenService:Create(Stroke, TweenInfo.new(0.3), {Thickness = 2, Transparency = 0}):Play()
                TweenService:Create(HoverOverlay, TweenInfo.new(0.3), {BackgroundTransparency = 0.88}):Play()
                TweenService:Create(Scale, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1.02}):Play()
                TweenService:Create(CartIcon, TweenInfo.new(0.2), {ImageTransparency = 0}):Play()
                WaveAnim:Play()
            end)

            F.MouseLeave:Connect(function()
                local DefaultStroke = Library.CurrentTheme and Library.CurrentTheme.Stroke or Color3.fromRGB(120, 120, 125)
                TweenService:Create(Stroke, TweenInfo.new(0.3), {Thickness = 1, Color = DefaultStroke, Transparency = 0.6}):Play()
                TweenService:Create(HoverOverlay, TweenInfo.new(0.3), {BackgroundTransparency = 1}):Play()
                TweenService:Create(Scale, TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Scale = 1}):Play()
                TweenService:Create(CartIcon, TweenInfo.new(0.2), {ImageTransparency = 1}):Play()
                WaveGradient.Color = ColorSequence.new(Color3.new(1, 1, 1)); WaveAnim:Cancel(); WaveGradient.Rotation = 0
            end)

            F.MouseButton1Click:Connect(function()
                HoverOverlay.BackgroundTransparency = 0.7
                TweenService:Create(HoverOverlay, TweenInfo.new(0.5), {BackgroundTransparency = 0.88}):Play()
                TweenService:Create(Scale, TweenInfo.new(0.1), {Scale = 0.96}):Play()
                task.delay(0.1, function() TweenService:Create(Scale, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1.02}):Play() end)
                
                local Amt = getgenv().ManualBuyAmount or 1
                
                if getgenv().PerformSmartPurchase then 
                    local ActualBought, requestedAmt = getgenv().PerformSmartPurchase(Item, Amt)
                    
                    if ActualBought and ActualBought > 0 then
                        if ActualBought < RequestedAmt then
                            Library:Notify("Manual Shop", "Bought " .. actualBought .. " out of " .. requestedAmt .. " " .. item.name .. " (Balance Limit)", 4, "rbxassetid://11385395241", "rbxassetid://72958619361915")
                        else
                            Library:Notify("Manual Shop", "Successfully bought " .. actualBought .. "x " .. item.name, 3, "rbxassetid://11385395241", "rbxassetid://72958619361915")
                        end
                    else
