                    end
                end
            end)
        end
    end

    BuildModernManualSection("Eggs & Pets", "pets")
    BuildModernManualSection("Gifts & Chests", "gifts")
    BuildModernManualSection("Food & Potions", "food")

    RenderAllAutoBuyTiles()
    ABSearchInput:GetPropertyChangedSignal("Text"):Connect(function() ApplyABSearchFilter(ABSearchInput.Text) end)
end

