    ["/raw/modules/adm_main/autofarm_ui"] = [==[local AutoFarmUI = {}

function AutoFarmUI:Init(Library, Window, Tab)
    local TweenService = game:GetService("TweenService")
    local RunService = game:GetService("RunService")

    if getgenv().AutofarmThemeConns then
        for _, Conn in ipairs(getgenv().AutofarmThemeConns) do 
            if Conn.Disconnect then Conn:Disconnect() end 
        end
    end
    getgenv().AutofarmThemeConns = {}

    local LastSaveTime = 0
    getgenv().SafeSaveConfig = function()
        local SaveFunc = getgenv().SaveConfig
        if not SaveFunc then return end
        if os.clock() - LastSaveTime < 1.5 then return end
        LastSaveTime = os.clock()
        task.spawn(function() pcall(SaveFunc) end)
    end

    Tab:CreateDivider({ Text = "Main Automation" })

    Tab:CreateNotice({ Text = "If you want to receive the most important status notifications from the farm features, enable the <b>Notify Hook</b> in settings." })

     
     
     
    local InstantNav = {
        Stack = {},
        HiddenRootElements = {}
    }

     
    Tab.Page:GetPropertyChangedSignal("Visible"):Connect(function()
        if not Tab.Page.Visible and #InstantNav.Stack > 0 then
             
            for _, P in ipairs(InstantNav.Stack) do P.Visible = false end
            table.clear(InstantNav.Stack)
            
             
            for _, Child in ipairs(InstantNav.HiddenRootElements) do 
                if Child then Child.Visible = true end 
            end
            table.clear(InstantNav.HiddenRootElements)
        end
    end)

    if Tab.Btn then
        Tab.Btn.MouseButton1Click:Connect(function()
            if Tab.Page.Visible and #InstantNav.Stack > 0 then
                for _, P in ipairs(InstantNav.Stack) do P.Visible = false end
                table.clear(InstantNav.Stack)
                for _, Child in ipairs(InstantNav.HiddenRootElements) do 
                    if Child then Child.Visible = true end 
                end
                table.clear(InstantNav.HiddenRootElements)
            end
        end)
    end

    local function CreateInstantSubPage(title)
        local SubPageUI = Library.Utils.Make("Frame", {
            Name = "InstantSubPage_" .. title:gsub("%s+", ""),
            Size = UDim2.new(1, 0, 1, 0), Position = UDim2.new(0, 0, 0, 0),
            BackgroundTransparency = 1, Visible = false, Parent = Tab.Page.Parent
        })

        local TopBar = Library.Utils.Make("Frame", { Size = UDim2.new(1, 0, 0, 40), BackgroundTransparency = 1, Parent = SubPageUI })
        
        local BaseCloseBtn = Library.Utils.Make("TextButton", { Text = "←", Size = UDim2.new(0, 34, 0, 34), Position = UDim2.new(0, 10, 0, 10), Font = Enum.Font.GothamBold, TextSize = 18, Parent = TopBar }, { BackgroundColor3 = "Section", TextColor3 = "Text" })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 6), Parent = BaseCloseBtn})
        Library.Utils.Make("UIStroke", {Parent = BaseCloseBtn}, {Color = "Stroke"})

