    local PulseCircle = Library.Utils.Make("Frame", { Size = UDim2.new(0, 8, 0, 8), Position = UDim2.new(0, 15, 0, 14), BackgroundColor3 = Color3.fromRGB(150, 150, 160), ZIndex = 3, Parent = MasterContainer })
