    Library.Utils.Make("UICorner", {CornerRadius = UDim.new(1, 0), Parent = ToggleBg})
    
    local OnP = UDim2.new(1, -22, 0.5, -10); local OffP = UDim2.new(0, 2, 0.5, -10)
    local ToggleKnob = Library.Utils.Make("Frame", { Size = UDim2.new(0, 20, 0, 20), Position = state and OnP or OffP, Parent = ToggleBg }, { BackgroundColor3 = "Knob" })
    Library.Utils.Make("UICorner", {CornerRadius = UDim.new(1, 0), Parent = ToggleKnob})

    local function UpdateToggle(NewState, SkipCallback)
        state = NewState
        getgenv().AutofarmEnabled = state
        Library.ThemeObjects[ToggleBg] = { BackgroundColor3 = NewState and "Accent" or "ToggleOff" }
        local TargetColor = NewState and (Library.CurrentTheme and Library.CurrentTheme.Accent or Color3.fromRGB(46, 204, 113)) or (Library.CurrentTheme and Library.CurrentTheme.ToggleOff or Color3.fromRGB(55, 55, 60))
        Library.Utils.TBT(ToggleBg, 0.25, {BackgroundColor3 = TargetColor})
        TweenService:Create(ToggleKnob, TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Position = NewState and OnP or OffP}):Play()
        for _, V in ipairs(ToggleBg:GetChildren()) do if V:IsA("UIGradient") then V:Destroy() end end
        if NewState then Library.Utils.ApplyGradient(ToggleBg, Library.CurrentTheme and Library.CurrentTheme.Accent or Color3.fromRGB(46, 204, 113)) end
        if not SkipCallback and getgenv().SetPetFarmState then getgenv().SetPetFarmState(NewState, true) end
        if not SkipCallback then
            if NewState then
                local IsDoingSomething = getgenv().PetFarmEnabled or getgenv().BabyAutofarmEnabled or getgenv().AutoHatch or getgenv().SWFEnabled or getgenv().AutoAgePot or getgenv().FastMegaEnabled
                if not IsDoingSomething then
                    Library:Notify("Autofarm", "Enabled, but NO modes are selected!", 4, "rbxassetid://90981936239657", "rbxassetid://72958619361915")
                else
                    Library:Notify("Autofarm", "Autofarm Enabled!", 3, "rbxassetid://17829956110", "rbxassetid://72958619361915")
                end
            else
                Library:Notify("Autofarm", "Autofarm Disabled!", 2, "rbxassetid://90865958932830", "rbxassetid://72958619361915")
            end
        end
    end

    ToggleBtn.MouseButton1Click:Connect(function() UpdateToggle(not state); getgenv().SafeSaveConfig() end)
    getgenv().UpdateMasterToggle = UpdateToggle

     
     
     
