            local S = Diff % 60
            if H > 0 then
                UptimeText.Text = string.format("⏱ %02d:%02d:%02d", H, m, S)
            else
                UptimeText.Text = string.format("⏱ %02d:%02d", m, S)
            end
        end
    end)

     
     
     
