    local AllModeTiles = {}
    local function CreateTileButton(parent, name, ImageId, TargetPage, keywords)
        local F = Library.Utils.Make("ImageButton", { Image = ImageId, ScaleType = Enum.ScaleType.Crop, ClipsDescendants = true, Parent = parent }, { BackgroundColor3 = "Section" })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 16), Parent = F})
        local SearchDimOverlay = Library.Utils.Make("Frame", { Size = UDim2.new(1, 0, 1, 0), BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 1, ZIndex = 4, Parent = F })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 16), Parent = SearchDimOverlay})
        
        local Stroke = Library.Utils.Make("UIStroke", {Thickness = 1, Color = Color3.fromRGB(120, 120, 125), Transparency = 0.6, Parent = F})
        
        local WaveGradient = Instance.new("UIGradient", Stroke)
        WaveGradient.Color = ColorSequence.new(Color3.new(1, 1, 1))
        
        local Scale = Instance.new("UIScale", F)

        local HoverOverlay = Library.Utils.Make("Frame", { Size = UDim2.new(1, 0, 1, 0), BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 1, ZIndex = 2, Parent = F })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 16), Parent = HoverOverlay})

        local ThemeLightenOverlay = Library.Utils.Make("Frame", { Size = UDim2.new(1, 0, 1, 0), BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 1, ZIndex = 1, Parent = F })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 16), Parent = ThemeLightenOverlay})
        
        local ThemeDetector = Library.Utils.Make("Frame", {Visible = false, Parent = F}, {BackgroundColor3 = "Section"})
        local function UpdateTileTheme()
            local _, _, v = ThemeDetector.BackgroundColor3:ToHSV()
            ThemeLightenOverlay.BackgroundTransparency = (V > 0.6) and 0.65 or 1
        end
        ThemeDetector:GetPropertyChangedSignal("BackgroundColor3"):Connect(UpdateTileTheme)
        task.spawn(function() task.wait() UpdateTileTheme() end)
        
        local Title = Library.Utils.Make("TextLabel", { Text = name, Size = UDim2.new(1, -20, 0, 40), Position = UDim2.new(0, 15, 1, -45), BackgroundTransparency = 1, Font = Enum.Font.GothamBold, TextSize = 15, TextXAlignment = Enum.TextXAlignment.Left, TextWrapped = true, ZIndex = 3, Parent = F, TextColor3 = Color3.new(1, 1, 1) })
        local Arrow = Library.Utils.Make("ImageLabel", { 
            Image = "rbxassetid://115929304045144",
            Size = UDim2.new(0, 20, 0, 20),
            Position = UDim2.new(1, -38, 1, -32),
            BackgroundTransparency = 1, 
            ImageColor3 = Color3.new(1, 1, 1),
            ZIndex = 3, 
            Parent = F
        })
        
         
        local TQuick = TweenInfo.new(0.3)
        local TBackOut = TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
        local TQuadOut = TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
        local TClick = TweenInfo.new(0.1)

         
        local WaveAnim = TweenService:Create(WaveGradient, TweenInfo.new(1.5, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut, -1), {Rotation = 360})
        
        local TweenHoverEnter = TweenService:Create(HoverOverlay, TQuick, {BackgroundTransparency = 0.88})
        local TweenStrokeEnter = TweenService:Create(Stroke, TQuick, {Thickness = 2, Transparency = 0})
        local TweenScaleEnter = TweenService:Create(Scale, TBackOut, {Scale = 1.02})
        local TweenFEnter = TweenService:Create(F, TBackOut, {Rotation = 1.5})
        local TweenArrowEnter = TweenService:Create(Arrow, TBackOut, {Position = UDim2.new(1, -22, 1, -35)})

        local TweenHoverLeave = TweenService:Create(HoverOverlay, TQuick, {BackgroundTransparency = 1})
        local TweenStrokeLeave = TweenService:Create(Stroke, TQuick, {Thickness = 1, Color = Color3.fromRGB(120, 120, 125), Transparency = 0.6})
        local TweenScaleLeave = TweenService:Create(Scale, TQuadOut, {Scale = 1})
        local TweenFLeave = TweenService:Create(F, TQuadOut, {Rotation = 0})
        local TweenArrowLeave = TweenService:Create(Arrow, TQuadOut, {Position = UDim2.new(1, -38, 1, -35)})
        
        local TweenHoverClick = TweenService:Create(HoverOverlay, TweenInfo.new(0.5), {BackgroundTransparency = 0.88})
        local TweenScaleClick = TweenService:Create(Scale, TClick, {Scale = 0.96})

         
        F.MouseEnter:Connect(function()
            local accent = Library.CurrentTheme and Library.CurrentTheme.Accent or Color3.fromRGB(46, 204, 113)
            local H, S, v = Color3.toHSV(accent)
            
            local C1 = Color3.fromHSV(H, S, math.min(V + 0.4, 1)) 
            local C2 = accent 
            local C3 = Color3.fromHSV(math.fmod(H + 0.08, 1), S, V) 

            WaveGradient.Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, C1),
                ColorSequenceKeypoint.new(0.5, C2),
                ColorSequenceKeypoint.new(1, C3)
            })

            TweenHoverEnter:Play()
            TweenStrokeEnter:Play()
            TweenScaleEnter:Play()
            TweenFEnter:Play()
            TweenArrowEnter:Play()
            WaveAnim:Play()
        end)

        table.insert(AllModeTiles, {
            Name = string.lower(name),
            Keywords = keywords and string.lower(keywords) or "",
            Frame = F,
            DimOverlay = SearchDimOverlay
        })
        
        F.MouseLeave:Connect(function()
            TweenHoverLeave:Play()
            TweenStrokeLeave:Play()
            TweenScaleLeave:Play()
            TweenFLeave:Play()
            TweenArrowLeave:Play()
            
            WaveGradient.Color = ColorSequence.new(Color3.new(1, 1, 1))
            WaveAnim:Cancel()
            WaveGradient.Rotation = 0
        end)
        
        F.MouseButton1Click:Connect(function()
            ModeSearchInput.Text = ""
            HoverOverlay.BackgroundTransparency = 0.7
            
            TweenHoverClick:Play()
            TweenScaleClick:Play()
            
            task.delay(0.1, function()
                TweenScaleEnter:Play()  
            end)
            
            TargetPage:Open()
        end)
    end

