    local ModeSearchThread
ModeSearchInput:GetPropertyChangedSignal("Text"):Connect(function()
    if ModeSearchThread then task.cancel(ModeSearchThread) end
    ModeSearchThread = task.delay(0.2, function()
        local Query = string.lower(ModeSearchInput.Text)
        
        for _, Tile in ipairs(AllModeTiles) do
            if Query == "" or string.find(Tile.Name, Query, 1, true) or string.find(Tile.Keywords, Query, 1, true) then
                TweenService:Create(Tile.DimOverlay, TweenInfo.new(0.3), {BackgroundTransparency = 1}):Play()
            else
                TweenService:Create(Tile.DimOverlay, TweenInfo.new(0.3), {BackgroundTransparency = 0.2}):Play()
            end
        end
    end)
end)

     
     
     
    local function CreateInnerToggle(parent, name, desc, Flag, Default, Callback)
        local Card = Library.Utils.Make("Frame", { Size = UDim2.new(1, 0, 0, 60), BackgroundTransparency = 0.3, Parent = parent }, { BackgroundColor3 = "Section" })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 8), Parent = Card})
        Library.Utils.Make("UIStroke", {Thickness = 1, Parent = Card}, { Color = "Stroke" })
        Library.Utils.Make("TextLabel", { Text = name, Size = UDim2.new(1, -70, 0, 16), Position = UDim2.new(0, 15, 0, 12), BackgroundTransparency = 1, Font = Enum.Font.GothamBold, TextSize = 14, TextXAlignment = Enum.TextXAlignment.Left, Parent = Card }, { TextColor3 = "Text" })
        Library.Utils.Make("TextLabel", { Text = desc, Size = UDim2.new(1, -70, 0, 14), Position = UDim2.new(0, 15, 0, 32), BackgroundTransparency = 1, Font = Enum.Font.GothamMedium, TextSize = 11, TextXAlignment = Enum.TextXAlignment.Left, Parent = Card }, { TextColor3 = "SubText" })

        local Sw = Library.Utils.Make("TextButton", { Text = "", Size = UDim2.new(0, 44, 0, 24), AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -15, 0.5, 0), BackgroundTransparency = 1, Parent = Card })
        local state = Default
        
        local ToggleBg = Library.Utils.Make("Frame", { Size = UDim2.new(1, 0, 1, 0), Parent = Sw }, { BackgroundColor3 = state and "Accent" or "ToggleOff" })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(1,0), Parent = ToggleBg})
        
        local OnP = UDim2.new(1, -22, 0.5, -10); local OffP = UDim2.new(0, 2, 0.5, -10)
        local Kn = Library.Utils.Make("Frame", { Size = UDim2.new(0, 20, 0, 20), Position = state and OnP or OffP, Parent = ToggleBg }, { BackgroundColor3 = "Knob" })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(1,0), Parent = Kn})

        local function SetState(NewState, SkipCallback)
            state = NewState
            getgenv()[Flag] = state
            
            Library.ThemeObjects[ToggleBg] = { BackgroundColor3 = NewState and "Accent" or "ToggleOff" }
            local TargetColor = NewState and (Library.CurrentTheme and Library.CurrentTheme.Accent or Color3.fromRGB(46, 204, 113)) or (Library.CurrentTheme and Library.CurrentTheme.ToggleOff or Color3.fromRGB(55, 55, 60))
            
             
            Library.Utils.TBT(ToggleBg, 0.25, {BackgroundColor3 = TargetColor})
            Library.Utils.TBT(Kn, 0.25, {Position = NewState and OnP or OffP})

            for _, V in ipairs(ToggleBg:GetChildren()) do if V:IsA("UIGradient") then V:Destroy() end end
            if NewState then
                Library.Utils.ApplyGradient(ToggleBg, Library.CurrentTheme and Library.CurrentTheme.Accent or Color3.fromRGB(46, 204, 113))
            end
            
            if not SkipCallback and Callback then pcall(Callback, state) end
            getgenv().SafeSaveConfig()
        end

        Sw.MouseButton1Click:Connect(function() SetState(not state) end)
        return Card, SetState
    end

    local SetPetFarmState, SetBabyFarmState, SetHatchState, SetSwfState, SetAgePotState, SetMegaState, SetPipelineState

    local function EnforceExclusiveMode(ActiveMode)
        if ActiveMode ~= "AutoHatch" and getgenv().AutoHatch and SetHatchState then SetHatchState(false, true) end
        if ActiveMode ~= "SWFEnabled" and getgenv().SWFEnabled and SetSwfState then SetSwfState(false, true) end
        if ActiveMode ~= "AutoAgePot" and getgenv().AutoAgePot and SetAgePotState then SetAgePotState(false, true) end
        if ActiveMode ~= "FastMegaEnabled" and getgenv().FastMegaEnabled and SetMegaState then SetMegaState(false, true) end
        if ActiveMode ~= "FastMegaPipeline" and getgenv().FastMegaPipeline and SetPipelineState then SetPipelineState(false, true) end
    end

     
