            local Found = false
            for name, Data in pairs(EcoCards) do
                if Query ~= "" and string.find(string.lower(name), Query) then Data.Card.Visible = true; found = true else Data.Card.Visible = false end
            end
            EcoEmptyState.Visible = not Found
        end)
    end)

    local function CreatePetCard(parent, Item, state, OnClickCallback)
        local Kind = Item.kind
        local Count = Item.count
        local Db = Item.db
        
        local BlockColor = Color3.fromRGB(255, 75, 75)
        local IsActive = state.active or false
        local IsBlocked = state.blocked or false
        local ShowGlow = IsActive or IsBlocked

        local OuterGlow = Library.Utils.Make("Frame", { Size = UDim2.new(1, 0, 1, 0), BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = ShowGlow and 0 or 1, Parent = parent })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 10), Parent = OuterGlow})
        
        local GlowGrad = Instance.new("UIGradient", OuterGlow)
        GlowGrad.Offset = Vector2.new(-1, 0)
        local GradTween = TweenService:Create(GlowGrad, TweenInfo.new(1.5, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut, -1), {Offset = Vector2.new(1, 0)})
        if IsActive then GradTween:Play() end

        local Card = Library.Utils.Make("TextButton", { Size = UDim2.new(1, -4, 1, -4), Position = UDim2.new(0.5, 0, 0.5, 0), AnchorPoint = Vector2.new(0.5, 0.5), Text = "", Parent = OuterGlow }, { BackgroundColor3 = "Section" })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 8), Parent = Card})
        
        local PImg = Db.icon or Db.image or Db.shop_image or "122697490518955"
        if not string.find(tostring(PImg), "rbxassetid") and tonumber(PImg) then PImg = "rbxassetid://"..pImg end
        local EggImg = Library.Utils.Make("ImageLabel", { Size = UDim2.new(0, 50, 0, 50), Position = UDim2.new(0.5, -25, 0, 8), BackgroundTransparency = 1, ScaleType = Enum.ScaleType.Fit, Image = PImg, ImageTransparency = IsBlocked and 0.6 or 0, Parent = Card })
        Library.Utils.Make("TextLabel", { Text = Item.name, Size = UDim2.new(1, -4, 0, 15), Position = UDim2.new(0, 2, 1, -20), BackgroundTransparency = 1, Font = Enum.Font.GothamMedium, TextSize = 10, TextWrapped = true, Parent = Card }, { TextColor3 = "Text" })

         
        local CountLbl = Library.Utils.Make("TextLabel", { 
            Text = "x" .. (Count > 99 and "99+" or tostring(Count)), 
            Size = UDim2.new(0, 24, 0, 15), Position = UDim2.new(0, 4, 0, 4), 
            Rotation = -15, BackgroundTransparency = 1, Font = Enum.Font.GothamBlack, 
            TextSize = 12, ZIndex = 4, Visible = (Count > 0), Parent = Card 
        }, { TextColor3 = "Accent" })
        local TxtStroke = Instance.new("UIStroke", CountLbl)
        TxtStroke.Color = Color3.new(0, 0, 0); TxtStroke.Thickness = 1.5

        local AccentLine = Library.Utils.Make("Frame", { Size = UDim2.new(0.6, 0, 0, 2), Position = UDim2.new(0.5, 0, 1, -6), AnchorPoint = Vector2.new(0.5, 0), BackgroundTransparency = ShowGlow and 0 or 1, BorderSizePixel = 0, Parent = Card })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(1, 0), Parent = AccentLine})

        local IconState = Library.Utils.Make("ImageLabel", { Size = UDim2.new(0, 20, 0, 20), Position = UDim2.new(1, -5, 0, 5), AnchorPoint = Vector2.new(1, 0), BackgroundTransparency = 1, ZIndex = 5, Parent = Card })
        
        local function UpdateCardVisuals()
            local ACol = Library.CurrentTheme.Accent
            local SCol = Library.CurrentTheme.Stroke
            if IsActive then
                GlowGrad.Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, SCol), ColorSequenceKeypoint.new(0.5, ACol), ColorSequenceKeypoint.new(1, SCol) })
                AccentLine.BackgroundColor3 = ACol
                IconState.Image = "rbxassetid://6031094667"; IconState.ImageColor3 = Color3.fromRGB(46, 204, 113); IconState.ImageTransparency = 0
            elseif IsBlocked then
                GlowGrad.Color = ColorSequence.new(BlockColor)
                AccentLine.BackgroundColor3 = BlockColor
                IconState.Image = "rbxassetid://90865958932830"; IconState.ImageColor3 = BlockColor; IconState.ImageTransparency = 0
            else
                GlowGrad.Color = ColorSequence.new(SCol)
                IconState.ImageTransparency = 1
            end
        end

        UpdateCardVisuals()
        local ThemeConn = table.insert(getgenv().AutofarmThemeConns, Library.OnThemeChange.Event:Connect(UpdateCardVisuals))
        OuterGlow.Destroying:Connect(function() GradTween:Cancel() if ThemeConn then ThemeConn:Disconnect() end end)

         
        local function UpdateState(NewCount, NewState)
            Count = NewCount
            IsActive = NewState.active or false
            IsBlocked = NewState.blocked or false
            
            CountLbl.Text = "x" .. (Count > 99 and "99+" or tostring(Count))
            CountLbl.Visible = (Count > 0)
            
            local NewShowGlow = IsActive or IsBlocked
            OuterGlow.BackgroundTransparency = NewShowGlow and 0 or 1
            AccentLine.BackgroundTransparency = NewShowGlow and 0 or 1
            
            if IsActive then
                GradTween:Play()
                Library.Utils.TBT(EggImg, 0.2, {ImageTransparency = 0})
            elseif IsBlocked then
                GradTween:Pause(); GlowGrad.Offset = Vector2.new(-1, 0)
                Library.Utils.TBT(EggImg, 0.2, {ImageTransparency = 0.6})
            else
                GradTween:Pause(); GlowGrad.Offset = Vector2.new(-1, 0)
                Library.Utils.TBT(EggImg, 0.2, {ImageTransparency = 0})
            end
            UpdateCardVisuals()
        end

        local CScale = Instance.new("UIScale", Card)
        Card.MouseButton1Click:Connect(function()
            Library.Utils.TBT(CScale, 0.1, {Scale = 0.85}).Completed:Connect(function() Library.Utils.TBT(CScale, 0.15, {Scale = 1}, Enum.EasingStyle.Bounce) end)
            local NewActive, newBlocked = OnClickCallback(Kind)
            UpdateState(Count, {active = NewActive, blocked = NewBlocked})  
        end)
        
        return OuterGlow, UpdateState
    end

     
