    local function SyncHatchTabs()
        local IsAll = getgenv().HatchShowAll
        local Theme = Library.CurrentTheme or Library.Themes.Dark
        local r, g, b = Theme.Accent.R, Theme.Accent.G, Theme.Accent.B
        local Brightness = (r * 299 + g * 587 + b * 114) / 1000
        local ActiveText = Brightness > 0.5 and Color3.fromRGB(20, 20, 25) or Color3.new(1, 1, 1)

        TweenService:Create(BtnOwned, TweenInfo.new(0.2), { BackgroundColor3 = not IsAll and Theme.Accent or Theme.Sidebar, TextColor3 = not IsAll and ActiveText or Theme.SubText }):Play()
        TweenService:Create(BtnAll, TweenInfo.new(0.2), { BackgroundColor3 = IsAll and Theme.Accent or Theme.Sidebar, TextColor3 = IsAll and ActiveText or Theme.SubText }):Play()
        BtnOwned.BackgroundTransparency = not IsAll and 0 or 1
        BtnAll.BackgroundTransparency = IsAll and 0 or 1
    end
