    local ActiveInspectorEgg = nil
    LimitInput.FocusLost:Connect(function()
        if not ActiveInspectorEgg then return end
        local Num = tonumber(LimitInput.Text)
        
        if Num and Num >= 0 then
            local CurrentOwned = 0
            local DuskCore = getgenv().DuskCore
            if DuskCore and DuskCore.M then
                local Inv = DuskCore.M.ClientData.get("inventory")
                if Inv and Inv.pets then
                    for _, PData in pairs(Inv.pets) do
                        if (PData.kind or PData.id) == ActiveInspectorEgg then 
                            CurrentOwned = CurrentOwned + 1 
                        end
                    end
                end
            end
            
             
            if Num > CurrentOwned then
                Num = CurrentOwned
            end
            
            getgenv().HatchLimits[ActiveInspectorEgg] = math.floor(Num)
            LimitInput.Text = tostring(math.floor(Num))
        else
            LimitInput.Text = tostring(getgenv().HatchLimits[ActiveInspectorEgg] or 0)
        end
        
        getgenv().SafeSaveConfig()
    end)

     
