    local HatchCardsCache = {}
    PopulateHatchSettings = function()
        local Env = getgenv()
        local DuskCore = Env.DuskCore
        if not DuskCore or not DuskCore.M or not DuskCore.M.InventoryDB then return end
        
         
        Env.HatchPriority = Env.HatchPriority or {}
        Env.HatchLimits = Env.HatchLimits or {}
        Env.HatchDisabled = {}
        
         
        local hatchPriority = Env.HatchPriority
        local hatchLimits = Env.HatchLimits
        local hatchShowAll = Env.HatchShowAll
        local hatchSearchQuery = Env.HatchSearchQuery

        local OwnedEggs = {}
        local Inv = DuskCore.M.ClientData.get("inventory")
        if Inv and Inv.pets then
            for Uid, PetData in pairs(Inv.pets) do
                local K = PetData.kind or PetData.id
                OwnedEggs[K] = (OwnedEggs[K] or 0) + 1
            end
        end

        local RenderList = {}
         
        local LowerSearchQuery = hatchSearchQuery ~= "" and string.lower(hatchSearchQuery) or ""

        for Kind, Db in pairs(DuskCore.M.InventoryDB.pets) do
            if Db.is_egg then
                local Count = OwnedEggs[Kind] or 0
                
                 
                if hatchLimits[Kind] and hatchLimits[Kind] > Count then
                    hatchLimits[Kind] = Count
                end
                
                if not hatchShowAll and Count == 0 then continue end
                
                local EggName = Db.name or Kind
                if LowerSearchQuery ~= "" and not string.find(string.lower(EggName), LowerSearchQuery, 1, true) then continue end
                
                table.insert(RenderList, {kind = Kind, db = Db, count = Count, name = EggName})
            end
        end

        table.sort(RenderList, function(A, b) return A.name < b.name end)

        for _, Cache in pairs(HatchCardsCache) do Cache.InUse = false end

        task.spawn(function()
            local FrameTimer = os.clock()
            
            for Index, Item in ipairs(RenderList) do
                local Kind = Item.kind
                
                 
                local IsPrio = table.find(hatchPriority, Kind) ~= nil
                local StateObj = { active = IsPrio, blocked = false }

                if HatchCardsCache[Kind] then
                    local Cache = HatchCardsCache[Kind]
                    Cache.InUse = true
                    Cache.UI.Visible = true
                    Cache.UI.LayoutOrder = Index
                    Cache.Update(Item.count, StateObj)
                else
                    local Ui, updateFunc = CreatePetCard(HatchGridContainer, Item, StateObj, function(ClickedKind)
                        local WasPrio = table.find(hatchPriority, ClickedKind) ~= nil
                        local NewActive = WasPrio
                        
                        if WasPrio then
                            if ActiveInspectorEgg == ClickedKind then
                                local Idx = table.find(hatchPriority, ClickedKind)
                                if Idx then table.remove(hatchPriority, Idx) end
                                ActiveInspectorEgg = nil
                                TweenService:Create(InspectorBar, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.In), {Position = UDim2.new(0, 15, 1, 60)}):Play()
                                NewActive = false
                            else
                                ActiveInspectorEgg = ClickedKind
                            end
                        else
                            table.insert(hatchPriority, ClickedKind)
                            ActiveInspectorEgg = ClickedKind
                            NewActive = true
                        end

                        if ActiveInspectorEgg == ClickedKind then
                            local PImg = Item.db.icon or Item.db.image or Item.db.shop_image or "122697490518955"
                            if not string.find(tostring(PImg), "rbxassetid") and tonumber(PImg) then PImg = "rbxassetid://"..pImg end
                            
                            InspIcon.Image = PImg
                            InspTitle.Text = Item.name .. " (Max: " .. tostring(Item.count) .. ")"
                            
                            if not hatchLimits[ClickedKind] or hatchLimits[ClickedKind] == 0 then
                                hatchLimits[ClickedKind] = (Item.count > 0) and Item.count or 1
                            end
                            LimitInput.Text = tostring(hatchLimits[ClickedKind])
                            
                            TweenService:Create(InspectorBar, TweenInfo.new(0.4, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Position = UDim2.new(0, 15, 1, -65)}):Play()
                        end

                        getgenv().SafeSaveConfig()  
                        return NewActive, false
                    end)
                    Ui.LayoutOrder = Index
                    HatchCardsCache[Kind] = { UI = Ui, Update = UpdateFunc, InUse = true }
                end

                if os.clock() - FrameTimer > 0.012 then
                    task.wait()
                    FrameTimer = os.clock()
                end
            end

            for _, Cache in pairs(HatchCardsCache) do
                if not Cache.InUse then Cache.UI.Visible = false end
            end
        end)
    end

