    local SwfCardsCache = {}
    local SwfLazyLoad = {
        IsLoading = false,
        RenderedCount = 0,
        ChunkSize = 50,
        List = {},
        Connection = nil
    }

    PopulateSWFSettings = function()
        local Env = getgenv()
        Env.SwfRenderTicket = (Env.SwfRenderTicket or 0) + 1
        local CurrentTicket = Env.SwfRenderTicket

        local DuskCore = Env.DuskCore
        if not DuskCore or not DuskCore.M or not DuskCore.M.InventoryDB then return end
        
         
        local swfMode = Env.SwfMode
        local SwfTargets = Env.SWFTargets
        local swfShowAll = Env.SwfShowAll
        local swfSearchQuery = Env.SwfSearchQuery
        
        local OwnedCounts = {}
        local Inv = DuskCore.M.ClientData.get("inventory")
        if Inv and Inv.pets then
            for Uid, PetData in pairs(Inv.pets) do
                local Props = PetData.properties or {}
                local IsMega = Props.mega_neon or Props.is_mega
                local IsNeon = Props.neon or Props.is_neon
                local Age = tonumber(Props.age) or 1
                if not IsMega then 
                    local K = PetData.kind or PetData.id
                     
                    if (swfMode == "Neon" and IsNeon) or (swfMode == "Regular" and not IsNeon) then
                        if Age < 6 then OwnedCounts[K] = (OwnedCounts[K] or 0) + 1 end
                    end
                end
            end
        end

        local RenderList = {}
         
        local LowerSearchQuery = swfSearchQuery ~= "" and string.lower(swfSearchQuery) or ""

        for Kind, Db in pairs(DuskCore.M.InventoryDB.pets) do
            if not Db.is_egg then
                local Count = OwnedCounts[Kind] or 0
                if not swfShowAll and Count == 0 then continue end
                local PetName = Db.name or Kind
                
                 
                if LowerSearchQuery ~= "" and not string.find(string.lower(PetName), LowerSearchQuery, 1, true) then continue end
                table.insert(RenderList, {kind = Kind, db = Db, count = Count, name = PetName})
            end
        end

        table.sort(RenderList, function(A, b) return A.name < b.name end)

        SwfLazyLoad.List = RenderList
        SwfLazyLoad.RenderedCount = 0
        SwfLazyLoad.IsLoading = false

        for _, Cache in pairs(SwfCardsCache) do Cache.InUse = false; Cache.UI.Visible = false end

        local function LoadNextChunk()
            if SwfLazyLoad.IsLoading then return end
            if SwfLazyLoad.RenderedCount >= #SwfLazyLoad.List then return end
            if Env.SwfRenderTicket ~= CurrentTicket then return end

            SwfLazyLoad.IsLoading = true

            local StartIdx = SwfLazyLoad.RenderedCount + 1
            local EndIdx = math.min(StartIdx + SwfLazyLoad.ChunkSize - 1, #SwfLazyLoad.List)
            local FrameTimer = os.clock()

            for I = StartIdx, EndIdx do
                if Env.SwfRenderTicket ~= CurrentTicket then break end
                
                local Item = SwfLazyLoad.List[I]
                local Kind = Item.kind
                
                 
                local IsSelected = SwfTargets[Kind] == true
                local StateObj = { active = IsSelected, blocked = false }

                if SwfCardsCache[Kind] then
                    local Cache = SwfCardsCache[Kind]
                    Cache.InUse = true
                    Cache.UI.Visible = true
                    Cache.UI.LayoutOrder = I
                    Cache.Update(Item.count, StateObj)
                else
                    local Ui, updateFunc = CreatePetCard(SwfGridContainer, Item, StateObj, function(ClickedKind)
                         
                        SwfTargets[ClickedKind] = not SwfTargets[ClickedKind]
                        
                         
                        getgenv().SafeSaveConfig() 
                        return SwfTargets[ClickedKind] == true, false
                    end)
                    Ui.LayoutOrder = I
                    SwfCardsCache[Kind] = { UI = Ui, Update = UpdateFunc, InUse = true }
                end

                if os.clock() - FrameTimer > 0.012 then
                    task.wait()
                    FrameTimer = os.clock()
                end
            end

            SwfLazyLoad.RenderedCount = EndIdx
            SwfLazyLoad.IsLoading = false
        end

        task.spawn(LoadNextChunk)

        if SwfLazyLoad.Connection then SwfLazyLoad.Connection:Disconnect() end
        SwfLazyLoad.Connection = FullgrownPage.Container:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
            local scroll = FullgrownPage.Container
            if scroll.CanvasPosition.Y + scroll.AbsoluteWindowSize.Y >= scroll.AbsoluteCanvasSize.Y - 150 then
                task.spawn(LoadNextChunk)
            end
        end)
    end
    
    task.spawn(function()
        local Attempts = 0
        while not (getgenv().DuskCore and getgenv().DuskCore.M and getgenv().DuskCore.M.InventoryDB) do 
            Attempts = Attempts + 1
            if Attempts > 60 then warn("[Autofarm] DuskCore load timeout!") break end
            task.wait(0.5) 
        end
        if Attempts <= 60 then pcall(PopulateSWFSettings) end
    end)

     
