    PipelineCard, PipelineToggleFunc = CreateInnerToggle(MegaPage.Container, "Hatch-to-Mega Pipeline", "Insta-grows hatched pets. (Idea: _crestar_)", "FastMegaPipeline", getgenv().FastMegaPipeline or false, function(state)
        if state then
