    local function SyncMegaTabs()
        local IsAll = getgenv().MegaShowAll
        local IsEggs = getgenv().MegaViewType == "Eggs"
        local Theme = Library.CurrentTheme or Library.Themes.Dark
        local r, g, b = Theme.Accent.R, Theme.Accent.G, Theme.Accent.B
        local Brightness = (r * 299 + g * 587 + b * 114) / 1000
        local ActiveText = Brightness > 0.5 and Color3.fromRGB(20, 20, 25) or Color3.new(1, 1, 1)

        TweenService:Create(MegaBtnInv, TweenInfo.new(0.2), { BackgroundColor3 = not IsAll and Theme.Accent or Theme.Sidebar, TextColor3 = not IsAll and ActiveText or Theme.SubText }):Play()
        TweenService:Create(MegaBtnAll, TweenInfo.new(0.2), { BackgroundColor3 = IsAll and Theme.Accent or Theme.Sidebar, TextColor3 = IsAll and ActiveText or Theme.SubText }):Play()
        TweenService:Create(MegaBtnPets, TweenInfo.new(0.2), { BackgroundColor3 = not IsEggs and Theme.Accent or Theme.Sidebar, TextColor3 = not IsEggs and ActiveText or Theme.SubText }):Play()
        TweenService:Create(MegaBtnEggs, TweenInfo.new(0.2), { BackgroundColor3 = IsEggs and Theme.Accent or Theme.Sidebar, TextColor3 = IsEggs and ActiveText or Theme.SubText }):Play()
        
        MegaBtnInv.BackgroundTransparency = not IsAll and 0 or 1; MegaBtnAll.BackgroundTransparency = IsAll and 0 or 1
        MegaBtnPets.BackgroundTransparency = not IsEggs and 0 or 1; MegaBtnEggs.BackgroundTransparency = IsEggs and 0 or 1
    end
    table.insert(getgenv().AutofarmThemeConns, Library.OnThemeChange.Event:Connect(SyncMegaTabs))

