    local IsMGridExpanded = false
    local function UpdateMegaGrid()
        local TotalItems = 0
        for _, C in ipairs(MegaGridContainer:GetChildren()) do if not C:IsA("UILayout") and not C:IsA("UIPadding") and C.Visible then TotalItems = TotalItems + 1 end end
        
        if TotalItems <= 4 then
            MegaGridBg.AutomaticSize = Enum.AutomaticSize.Y
            MegaGridBg.Size = UDim2.new(1, 0, 0, 0)
            MFadeOverlay.Visible = false
            MBottomBtn.Visible = false
        else
            MBottomBtn.Visible = true
            if IsMGridExpanded then
                MegaGridBg.AutomaticSize = Enum.AutomaticSize.Y
                MegaGridBg.Size = UDim2.new(1, 0, 0, 0)
                MFadeOverlay.Visible = false
                MExpandText.Text = "Show Less ▲"
            else
                MegaGridBg.AutomaticSize = Enum.AutomaticSize.None
                MegaGridBg.Size = UDim2.new(1, 0, 0, 130)
                MFadeOverlay.Visible = true
                MExpandText.Text = "Show More ▼"
            end
        end
    end
    MBottomBtn.MouseButton1Click:Connect(function() 
        IsMGridExpanded = not IsMGridExpanded
        UpdateMegaGrid() 
    end)
    MGrid:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(UpdateMegaGrid)

    local MegaCardsCache = {}
     
    local MegaLazyLoad = {
        IsLoading = false,
        RenderedCount = 0,
        ChunkSize = 50,  
        List = {},
        Connection = nil
    }

    PopulateMegaSettings = function()
        IsMGridExpanded = false
        UpdateMegaGrid()

        local Env = getgenv()
        local SaveConfigFunc = Env.SaveConfig
        
        Env.MegaRenderTicket = (Env.MegaRenderTicket or 0) + 1
        local CurrentTicket = Env.MegaRenderTicket

        local DuskCore = Env.DuskCore
        if not DuskCore or not DuskCore.M or not DuskCore.M.InventoryDB then return end
        
         
        local megaViewType = Env.MegaViewType
        local fastMegaMode = Env.FastMegaMode
        local megaShowAll = Env.MegaShowAll
        local megaSearchQuery = Env.MegaSearchQuery
        
         
        local MegaTargets = Env.FastMegaTargets
        local MegaEggTargets = Env.FastMegaEggTargets
        local MegaBlocked = Env.FastMegaBlocked
        local MegaEggBlocked = Env.FastMegaEggBlocked

        local OwnedCounts = {}
        local Inv = DuskCore.M.ClientData.get("inventory")
        if Inv and Inv.pets then
            for Uid, PetData in pairs(Inv.pets) do
                local Props = PetData.properties or {}
                local IsMega = Props.mega_neon or Props.is_mega
                local IsNeon = Props.neon or Props.is_neon
                local Age = tonumber(Props.age) or 1
                local K = PetData.kind or PetData.id
                local DbEntry = DuskCore.M.InventoryDB.pets[K]
                
                 
                if megaViewType == "Eggs" then
                    if DbEntry and DbEntry.is_egg then OwnedCounts[K] = (OwnedCounts[K] or 0) + 1 end
                else
                    if DbEntry and not DbEntry.is_egg then
                        if not IsMega and Age < 6 then
                            if fastMegaMode == "Neon" and not IsNeon then OwnedCounts[K] = (OwnedCounts[K] or 0) + 1
                            elseif fastMegaMode == "Mega" then OwnedCounts[K] = (OwnedCounts[K] or 0) + 1 end
                        end
                    end
                end
            end
        end

        local RenderList = {}
         
        local LowerSearchQuery = megaSearchQuery ~= "" and string.lower(megaSearchQuery) or ""

        for Kind, Db in pairs(DuskCore.M.InventoryDB.pets) do
            local IsEggMatch = (megaViewType == "Eggs" and Db.is_egg) or (megaViewType == "Pets" and not Db.is_egg)
            if IsEggMatch then
                local Count = OwnedCounts[Kind] or 0
                if not megaShowAll and Count == 0 then continue end
                
                local PetName = Db.name or Kind
                 
                if LowerSearchQuery ~= "" and not string.find(string.lower(PetName), LowerSearchQuery, 1, true) then continue end
                
                table.insert(RenderList, {kind = Kind, db = Db, count = Count, name = PetName})
            end
        end

        table.sort(RenderList, function(A, b) return A.name < b.name end)

        MegaLazyLoad.List = RenderList
        MegaLazyLoad.RenderedCount = 0
        MegaLazyLoad.IsLoading = false

        for _, Cache in pairs(MegaCardsCache) do Cache.InUse = false; Cache.UI.Visible = false end

        local function LoadNextChunk()
            if MegaLazyLoad.IsLoading then return end
            if MegaLazyLoad.RenderedCount >= #MegaLazyLoad.List then return end
            if Env.MegaRenderTicket ~= CurrentTicket then return end 

            MegaLazyLoad.IsLoading = true

            local StartIdx = MegaLazyLoad.RenderedCount + 1
            local EndIdx = math.min(StartIdx + MegaLazyLoad.ChunkSize - 1, #MegaLazyLoad.List)
            local FrameTimer = os.clock()

            for I = StartIdx, EndIdx do
                if Env.MegaRenderTicket ~= CurrentTicket then break end
                
                local Item = MegaLazyLoad.List[I]
                local Kind = Item.kind
                local IsEggs = (megaViewType == "Eggs")
                
                 
                local IsSelected = IsEggs and (MegaEggTargets[Kind] == true) or (not IsEggs and MegaTargets[Kind] == true)
                local IsBlocked = IsEggs and (MegaEggBlocked[Kind] == true) or (not IsEggs and MegaBlocked[Kind] == true)
                local StateObj = { active = IsSelected, blocked = IsBlocked }

                if MegaCardsCache[Kind] then
                    local Cache = MegaCardsCache[Kind]
                    Cache.InUse = true
                    Cache.UI.Visible = true
                    Cache.UI.LayoutOrder = I
                    Cache.Update(Item.count, StateObj)
                else
                    local Ui, updateFunc = CreatePetCard(MegaGridContainer, Item, StateObj, function(ClickedKind)
                         
                        local WasSelected = IsEggs and (MegaEggTargets[ClickedKind] == true) or (not IsEggs and MegaTargets[ClickedKind] == true)
                        local WasBlocked = IsEggs and (MegaEggBlocked[ClickedKind] == true) or (not IsEggs and MegaBlocked[ClickedKind] == true)

                        local NewActive, newBlocked = false, false
                        
                        if WasSelected then
                            if IsEggs then 
                                MegaEggTargets[ClickedKind] = nil
                                MegaEggBlocked[ClickedKind] = true 
                            else 
                                MegaTargets[ClickedKind] = nil
                                MegaBlocked[ClickedKind] = true 
                            end
                            NewBlocked = true
                        elseif WasBlocked then
                            if IsEggs then 
                                MegaEggBlocked[ClickedKind] = nil 
                            else 
                                MegaBlocked[ClickedKind] = nil 
                            end
                        else
                            if IsEggs then 
                                MegaEggBlocked[ClickedKind] = nil
                                MegaEggTargets[ClickedKind] = true 
                            else 
                                MegaBlocked[ClickedKind] = nil
                                MegaTargets[ClickedKind] = true 
                            end
                            NewActive = true
                        end
                        
                         
                        if SaveConfigFunc then pcall(SaveConfigFunc) end
                        return NewActive, NewBlocked 
                    end)
                    Ui.LayoutOrder = I
                    MegaCardsCache[Kind] = { UI = Ui, Update = UpdateFunc, InUse = true }
                end

                if os.clock() - FrameTimer > 0.012 then
                    task.wait()
                    FrameTimer = os.clock()
                end
            end

            MegaLazyLoad.RenderedCount = EndIdx
            MegaLazyLoad.IsLoading = false
            
            UpdateMegaGrid()
        end

        task.spawn(LoadNextChunk)

        if MegaLazyLoad.Connection then MegaLazyLoad.Connection:Disconnect() end
        
        MegaLazyLoad.Connection = MegaPage.Container:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
            local scroll = MegaPage.Container
            if scroll.CanvasPosition.Y + scroll.AbsoluteWindowSize.Y >= scroll.AbsoluteCanvasSize.Y - 150 then
                if IsMGridExpanded then 
                    task.spawn(LoadNextChunk)
                end
            end
        end)
    end
    task.spawn(function() task.wait() SyncMegaTabs() PopulateMegaSettings() end)
end

     
     
     
