    local function UpdatePlatGradient()
        local BaseColor = Library.CurrentTheme.Accent
        local H, S, v = BaseColor:ToHSV()
        local DarkColor = Color3.fromHSV(H, math.clamp(S + 0.1, 0, 1), math.clamp(V - 0.3, 0, 1))
        
        PlatGradient.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, DarkColor),
            ColorSequenceKeypoint.new(0.5, BaseColor),
            ColorSequenceKeypoint.new(1, DarkColor)
        })
    end
    table.insert(getgenv().AutofarmThemeConns, Library.OnThemeChange.Event:Connect(UpdatePlatGradient))    
