    local function UpdateFarmPlatform()
        local function ApplyProps(Part)
            Part.Material = Enum.Material[getgenv().PlatformMaterial or "SmoothPlastic"]
            Part.Color = getgenv().PlatformColor or Color3.fromRGB(170, 85, 255)
            Part.Transparency = (getgenv().PlatformTransparency or 50) / 100
            Part.Reflectance = (getgenv().PlatformReflectance or 0) / 100
            
            local Tex = Part:FindFirstChild("DuskCustomTexture")
            if getgenv().PlatformTextureEnabled and getgenv().PlatformTextureID and getgenv().PlatformTextureID ~= "" then
                if not Tex then
                    Tex = Instance.new("Texture", Part)
                    Tex.Name = "DuskCustomTexture"
                    Tex.Face = Enum.NormalId.Top
                end
                local Id = getgenv().PlatformTextureID
                if tonumber(Id) then Id = "rbxassetid://" .. id end
                Tex.Texture = Id
                Tex.Transparency = (getgenv().PlatformTransparency or 50) / 100
                
                if getgenv().PlatformTextureMode == "Multi" then
                    local scale = getgenv().PlatformTextureScale or 12
                    Tex.StudsPerTileU = scale; Tex.StudsPerTileV = scale
                else
                    Tex.StudsPerTileU = Part.Size.X; Tex.StudsPerTileV = Part.Size.Z
                end
                Part.Color = Color3.fromRGB(255, 255, 255) 
            else
                if Tex then Tex:Destroy() end
            end
        end

        local CS = game:GetService("CollectionService")
        for _, Platform in pairs(CS:GetTagged("DuskPlat")) do
            if Platform:IsA("BasePart") then ApplyProps(Platform) end
        end
    end

