        local CamMat = Instance.new("Camera"); CamMat.CFrame = CFrame.new(Vector3.new(0, 0, 2.8), Vector3.new(0, 0, 0)); VpfMat.CurrentCamera = CamMat
        local Part = Instance.new("Part", VpfMat); Part.Shape = Enum.PartType.Ball; Part.Size = Vector3.new(2, 2, 2); Part.Material = Mat; Part.Color = Color3.fromRGB(180, 180, 180)

