        local SliderBG = Library.Utils.Make("Frame", { Size = UDim2.new(1, -30, 0, 6), Position = UDim2.new(0, 15, 0, YPos + 25), Parent = parent }, { BackgroundColor3 = "Sidebar" })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(1, 0), Parent = SliderBG})
        
