        local Dragging = false
        local function Update(Input)
            local Pos = UDim2.new(math.clamp((Input.Position.X - SliderBG.AbsolutePosition.X) / SliderBG.AbsoluteSize.X, 0, 1), 0, 1, 0)
            SliderFill.Size = Pos
            local Val = math.floor(Min + ((Max - Min) * Pos.X.Scale))
            ValText.Text = tostring(Val)
            pcall(Callback, Val)
        end

        Trigger.InputBegan:Connect(function(Input) if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then Dragging = true; Update(Input) end end)
        UIS.InputEnded:Connect(function(Input) if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then Dragging = false end end)
        UIS.InputChanged:Connect(function(Input) if Dragging and (Input.UserInputType == Enum.UserInputType.MouseMovement or Input.UserInputType == Enum.UserInputType.Touch) then Update(Input) end end)
