    local function AddInteractiveImageInput(Default, Callback)
        local F = Library.Utils.Make("Frame", { Size = UDim2.new(1, 0, 0, 105), Parent = PlatformPage.Container, Visible = false }, { BackgroundColor3 = "Section" })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 10), Parent = F})
