        local BoxBG = Library.Utils.Make("Frame", { Size = UDim2.new(1, -100, 0, 30), Position = UDim2.new(0, 15, 0, 35), Parent = F }, { BackgroundColor3 = "Sidebar" })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 6), Parent = BoxBG})
        local Box = Library.Utils.Make("TextBox", { Size = UDim2.new(1, -20, 1, 0), Position = UDim2.new(0, 10, 0, 0), BackgroundTransparency = 1, PlaceholderText = "Paste Image ID...", Text = Default, Font = Enum.Font.GothamMedium, TextSize = 12, ClearTextOnFocus = false, TextXAlignment = Enum.TextXAlignment.Left, Parent = BoxBG }, { TextColor3 = "Text" })

        local PreviewImgBg = Library.Utils.Make("Frame", { Size = UDim2.new(0, 60, 0, 60), AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -15, 0.5, 0), Parent = F }, { BackgroundColor3 = "Sidebar" })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 6), Parent = PreviewImgBg})
        local PreviewImg = Library.Utils.Make("ImageLabel", { Size = UDim2.new(1, -4, 1, -4), Position = UDim2.new(0.5, 0, 0.5, 0), AnchorPoint = Vector2.new(0.5, 0.5), BackgroundTransparency = 1, ScaleType = Enum.ScaleType.Fit, Parent = PreviewImgBg })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 4), Parent = PreviewImg})
        
        local CurrentSavedID = Default
        if CurrentSavedID ~= "" then PreviewImg.Image = "rbxassetid://" .. currentSavedID:match("%d+") end

        local ActionFrame = Library.Utils.Make("Frame", { Size = UDim2.new(1, -100, 0, 24), Position = UDim2.new(0, 15, 0, 70), BackgroundTransparency = 1, Visible = false, Parent = F })
        local ApplyBtn = Library.Utils.Make("TextButton", { Size = UDim2.new(0.48, 0, 1, 0), Position = UDim2.new(0, 0, 0, 0), Text = "Apply", Font = Enum.Font.GothamBold, TextSize = 12, BackgroundColor3 = Color3.fromRGB(46, 204, 113), TextColor3 = Color3.fromRGB(255, 255, 255), Parent = ActionFrame })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 4), Parent = ApplyBtn})
        local CancelBtn = Library.Utils.Make("TextButton", { Size = UDim2.new(0.48, 0, 1, 0), Position = UDim2.new(0.52, 0, 0, 0), Text = "Cancel", Font = Enum.Font.GothamBold, TextSize = 12, BackgroundColor3 = Color3.fromRGB(255, 75, 75), TextColor3 = Color3.fromRGB(255, 255, 255), Parent = ActionFrame })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 4), Parent = CancelBtn})

        Box:GetPropertyChangedSignal("Text"):Connect(function()
            if Box.Text ~= CurrentSavedID then
                ActionFrame.Visible = true
                local Num = Box.Text:match("%d+")
                if Num then PreviewImg.Image = "rbxassetid://" .. num else PreviewImg.Image = "" end
            else
                ActionFrame.Visible = false
            end
        end)

        ApplyBtn.MouseButton1Click:Connect(function()
            local Num = Box.Text:match("%d+")
            if Num then
                CurrentSavedID = Num
                Box.Text = Num
                ActionFrame.Visible = false
                pcall(Callback, Num)
            end
        end)

        CancelBtn.MouseButton1Click:Connect(function()
            Box.Text = CurrentSavedID
            ActionFrame.Visible = false
            if CurrentSavedID ~= "" then PreviewImg.Image = "rbxassetid://" .. currentSavedID else PreviewImg.Image = "" end
        end)

        return F
    end

     
