    local SkyInputCard = nil

    local function UpdateCustomSky()
        local Lighting = game:GetService("Lighting")
        local Sky = Lighting:FindFirstChild("DuskCustomSky")
        
        if getgenv().CustomSkyEnabled and getgenv().CustomSkyID and getgenv().CustomSkyID ~= "" then
            if not Sky then
                Sky = Instance.new("Sky")
                Sky.Name = "DuskCustomSky"
                Sky.Parent = Lighting
            end
            
            local Id = getgenv().CustomSkyID
            if tonumber(Id) then Id = "rbxassetid://" .. id end
            
             
            Sky.SkyboxBk = Id
            Sky.SkyboxDn = Id
            Sky.SkyboxFt = Id
            Sky.SkyboxLf = Id
            Sky.SkyboxRt = Id
            Sky.SkyboxUp = Id
        else
             
            if Sky then Sky:Destroy() end
        end
    end

     
