						continue
					end

					V12 = V14

					break
				end

				return V11, V12
			end

			local HouseInteriors = game.Workspace:FindFirstChild("HouseInteriors")
			local furniture = HouseInteriors and HouseInteriors:FindFirstChild("furniture")

			if furniture then
				local V17 = string.gsub(P1, "_", "")

				for _, Child in pairs(furniture:GetChildren()) do
					local V20 = string.match(Child.Name, "f%-%d+")

					if not V20 then
						continue
					end

					for _, Child2 in pairs(Child:GetChildren()) do
						if not Child2:IsA("Model") or not string.find(string.lower(Child2.Name), V17) then
							continue
						end

						local BasePart = Child2:FindFirstChildWhichIsA("BasePart", true) or Child2.PrimaryPart

						if BasePart then
