			local Pets = P3.Pets or {}

			for _, Pet in ipairs(Pets) do
				if Pet.needs then
					if Pet.needs[P2] and Pet.char then
						table.insert(T1, {
							type = "Pet",
							char = Pet.char,
							uid = Pet.uid
						})
					end
				end
			end

			if #T1 == 0 then
				return false
			end

			local cFrame
			local V29
			local S1 = "MainMap"

			if P2 == "party_zone" then
				local PartyZone = require(game:GetService("ReplicatedStorage").new.modules.AdminAbuse).get_value("party_zone")

				if not PartyZone then
					return false
				end

				S1 = PartyZone.destination_id
