					return false
				end

				cFrame = V32:IsA("Model") and V32:GetPivot() or V32.CFrame
			end

			local EventPlatform = P5("EventPlatform")

			EventPlatform.CFrame = cFrame * CFrame.new(0, -3.5, 0)
			P6(EventPlatform)

			if P2 == "leaf_pile" or P2 == "snow" or P2 == "diving_board" then
				if V29 then
					Print("[DuskCore-Debug] 🟢 Запускаем взаимодействие. FID = " .. tostring(V29))

					if P2 == "diving_board" then
						for _, V in ipairs(T1) do
							if DuskCore.IsRespawning() then
								break
							end

							Print("[DuskCore-Debug] 🏊 Прыжок для: " .. tostring(V.uid))

							if Plr.Character and Plr.Character.PrimaryPart then
								Plr.Character:PivotTo(cFrame * CFrame.new(0, 2, 0))
							end

							task.wait(0.5)
							pcall(function()
								local SetThreadIdentity = syn and syn.set_thread_identity or setthreadidentity or setidentity
								local GetThreadIdentity = syn and syn.get_thread_identity or getthreadidentity or getidentity
								local V38 = GetThreadIdentity and GetThreadIdentity() or 7

								if SetThreadIdentity then
									SetThreadIdentity(2)
								end

								pcall(function()
									require(game:GetService("ReplicatedStorage").SharedModules.ContentPacks.WeatherAilments2026.Furniture)
								end)

								if SetThreadIdentity then
									SetThreadIdentity(V38)
								end

								local V39

								for _, V2 in pairs(getgc(true)) do
									if type(V2) == "table" and rawget(V2, "AilmentFurnitureDone") and rawget(V2, "AilmentFurnitureUse") then
										V39 = V2

										break
									end
								end

								game:GetService("ReplicatedStorage"):WaitForChild("API"):WaitForChild("HousingAPI/ActivateInteriorFurniture"):InvokeServer(V29, "UseBlock", nil, Plr.Character)
								task.wait(0.5)

								if V39 then
									Print("[DuskCore-Debug] 🎯 Отправка AilmentFurnitureDone...")
									V39.AilmentFurnitureDone:fire_server()
