				end
			else
				for _, V in ipairs(T1) do
					if V.type == "Pet" and V.char and V.char.PrimaryPart then
						V.char:PivotTo(cFrame)
					end
				end
			end

			local Now = os.time()

			while os.time() - Now < 40 do
				task.wait(1)

				if DuskCore.IsRespawning() or Cac.CurrentLocation ~= S1 then
					break
				end

				local V48 = false
				local AilmentsManager = M.ClientData.get("ailments_manager")

				if AilmentsManager then
