							local V57 = AilmentsManager.ailments[V.uid] or {}

							for _, V2 in Pairs(V57) do
								if V2.kind == P2 then
									V48 = true

									break
								end
							end
						end
					end
				end

				if not V48 then
					break
				end
			end

			P6(P5("Main"))

			return true
		end
	end
}
