    local MinH, maxH = 500, 3000
    local CurH = getgenv().HeapLimit or 1500
    getgenv().HeapLimit = CurH
    local HDragging = false

     
    local UserInputService = game:GetService("UserInputService")

    local function UpdateH(Val)
        local Pct = math.clamp((Val - MinH) / (MaxH - MinH), 0, 1)
        TweenService:Create(HFill, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Size = UDim2.new(Pct, 0, 1, 0)}):Play()
        HVal.Text = tostring(Val) .. " MB"
    end

    local function ApplyHDrag(Input)
        local Pct = math.clamp((Input.Position.X - HTrack.AbsolutePosition.X) / HTrack.AbsoluteSize.X, 0, 1)
        CurH = math.floor(MinH + (MaxH - MinH) * Pct)
        UpdateH(CurH)
        getgenv().HeapLimit = CurH
        if getgenv().SaveConfig then pcall(getgenv().SaveConfig) end
    end

    HVal.FocusLost:Connect(function()
        local Num = tonumber(HVal.Text:match("%d+"))
        if Num then
            CurH = math.clamp(Num, MinH, MaxH)
            getgenv().HeapLimit = CurH
            UpdateH(CurH)
            if getgenv().SaveConfig then pcall(getgenv().SaveConfig) end
        else
            HVal.Text = tostring(CurH) .. " MB"
        end
    end)
    UpdateH(CurH)

    Library:Connect(HTrack.InputBegan, function(Input)
        if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then HDragging = true; ApplyHDrag(Input) end
    end)
    Library:Connect(UserInputService.InputEnded, function(Input)
        if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then HDragging = false end
    end)
    Library:Connect(UserInputService.InputChanged, function(Input)
        if HDragging and (Input.UserInputType == Enum.UserInputType.MouseMovement or Input.UserInputType == Enum.UserInputType.Touch) then ApplyHDrag(Input) end
    end)

    task.spawn(function()
        while task.wait(1) do
            if not getgenv().DuskShine_Core or getgenv().DS_StopExecution then break end
            local Mb = math.floor(gcinfo() / 1024)
            local Status = Mb <= 1200 and "(Normal)" or (Mb < CurH and "(High)" or "(CRITICAL)")
            CurrentHeapText.Text = string.format("Current Heap: %d MB %s", Mb, Status)
            
            if Mb > 1200 then
                Library.ThemeObjects[CurrentHeapText] = { TextColor3 = "Accent" }
                TweenService:Create(CurrentHeapText, TweenInfo.new(0.3), {TextColor3 = Library.CurrentTheme.Accent}):Play()
            else
                Library.ThemeObjects[CurrentHeapText] = { TextColor3 = "SubText" }
                TweenService:Create(CurrentHeapText, TweenInfo.new(0.3), {TextColor3 = Library.CurrentTheme.SubText}):Play()
            end
        end
    end)
    Tab:CreateToggle({
        Name = "Anonymous Mode", Description = "Hides your identity to prevent streaming snipes.", Flag = "AnonymousMode", Default = getgenv().AnonymousMode or false,
        Callback = function(State)
