    }, { BackgroundColor3 = "Section" })
    Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 10), Parent = KeybindCard})
    
    local KeyStroke = Library.Utils.Make("UIStroke", {Thickness = 1, Parent = KeybindCard}, {Color = "Stroke"})
    KeybindCard.MouseEnter:Connect(function() Library.Utils.TBT(KeyStroke, 0.25, {Color = Library.CurrentTheme.Accent}) end)
    KeybindCard.MouseLeave:Connect(function() Library.Utils.TBT(KeyStroke, 0.25, {Color = Library.CurrentTheme.Stroke}) end)
    
    Library.Utils.Make("TextLabel", { Text = "Toggle Menu Key", Size = UDim2.new(1, -120, 0, 20), Position = UDim2.new(0, 20, 0, 15), BackgroundTransparency = 1, Font = Enum.Font.GothamBold, TextSize = 16, TextXAlignment = Enum.TextXAlignment.Left, Parent = KeybindCard }, { TextColor3 = "Text" })
    Library.Utils.Make("TextLabel", { Text = "Key to hide or show the menu.", Size = UDim2.new(1, -120, 0, 15), Position = UDim2.new(0, 20, 0, 38), BackgroundTransparency = 1, Font = Enum.Font.Gotham, TextSize = 13, TextXAlignment = Enum.TextXAlignment.Left, Parent = KeybindCard }, { TextColor3 = "SubText" })

    local BindBtn = Library.Utils.Make("TextButton", { Size = UDim2.new(0, 80, 0, 34), AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -20, 0.5, 0), Font = Enum.Font.Gotham, TextSize = 13, AutoButtonColor = false, Text = (getgenv().ToggleUIKey or Enum.KeyCode.RightControl).Name, Parent = KeybindCard }, { BackgroundColor3 = "Sidebar", TextColor3 = "SubText" })
    Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 8), Parent = BindBtn})
    Library.Utils.Make("UIStroke", {Thickness = 1, Parent = BindBtn}, {Color = "Stroke"})

    local Listening = false
    Library:Connect(BindBtn.MouseButton1Click, function()
        if Listening then return end
        Listening = true
        BindBtn.Text = "..."
        Library.Utils.TBT(BindBtn, 0.2, {TextColor3 = Library.CurrentTheme.Accent})

        local TempConnection
        TempConnection = game:GetService("UserInputService").InputBegan:Connect(function(Input)
            local IsKey = Input.UserInputType == Enum.UserInputType.Keyboard
            local IsMouse = Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.MouseButton2 or Input.UserInputType == Enum.UserInputType.MouseButton3

            if IsKey or IsMouse then
                local NewKey = IsKey and Input.KeyCode or Input.UserInputType
                if NewKey == Enum.KeyCode.Escape then NewKey = Enum.KeyCode.Unknown end

                getgenv().ToggleUIKey = NewKey
                BindBtn.Text = NewKey.Name
                Listening = false
                Library.Utils.TBT(BindBtn, 0.2, {TextColor3 = Library.CurrentTheme.SubText})

                if getgenv().SaveConfig then pcall(getgenv().SaveConfig) end
                if TempConnection then TempConnection:Disconnect() end
            end
        end)
    end)

    Library:Connect(game:GetService("UserInputService").InputBegan, function(Input, Processed)
        if not Processed and Input.KeyCode == getgenv().ToggleUIKey then
            task.spawn(function() if Window.ToggleMenu then Window:ToggleMenu() end end)
        end
    end)

     
     
     
    Tab:CreateDivider({ Text = "Performance" })
    
    local UserInputService = game:GetService("UserInputService")
    
    local SliderContainer = Library.Utils.Make("Frame", { 
        Size = UDim2.new(1, 0, 0, 70), 
        BackgroundTransparency = 0.3, 
        Parent = Tab.Page 
    }, { BackgroundColor3 = "Section" })
    Library.Utils.Make("UICorner", { CornerRadius = UDim.new(0, 10), Parent = SliderContainer })
    
    local ContainerStroke = Library.Utils.Make("UIStroke", { Thickness = 1, Parent = SliderContainer }, { Color = "Stroke" })
    SliderContainer.MouseEnter:Connect(function() Library.Utils.TBT(ContainerStroke, 0.25, {Color = Library.CurrentTheme.Accent}) end)
    SliderContainer.MouseLeave:Connect(function() Library.Utils.TBT(ContainerStroke, 0.25, {Color = Library.CurrentTheme.Stroke}) end)

    Library.Utils.Make("TextLabel", { Text = "Frame Rate Limit", Size = UDim2.new(1, -100, 0, 20), Position = UDim2.new(0, 20, 0, 10), BackgroundTransparency = 1, Font = Enum.Font.GothamBold, TextSize = 16, TextXAlignment = Enum.TextXAlignment.Left, Parent = SliderContainer }, { TextColor3 = "Text" })
    Library.Utils.Make("TextLabel", { Text = "Drag to the far right to completely uncap FPS.", Size = UDim2.new(1, -100, 0, 15), Position = UDim2.new(0, 20, 0, 30), BackgroundTransparency = 1, Font = Enum.Font.Gotham, TextSize = 13, TextXAlignment = Enum.TextXAlignment.Left, Parent = SliderContainer }, { TextColor3 = "SubText" })

    local PillFrame = Library.Utils.Make("Frame", { Size = UDim2.new(0, 76, 0, 24), AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -20, 0, 9), Parent = SliderContainer }, { BackgroundColor3 = "Sidebar" }) 
    Library.Utils.Make("UICorner", { CornerRadius = UDim.new(0, 6), Parent = PillFrame })
    local PillStroke = Library.Utils.Make("UIStroke", { Thickness = 1, Parent = PillFrame }, { Color = "Stroke" })
    
    local ValueText = Library.Utils.Make("TextBox", { Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 1, Font = Enum.Font.Gotham, TextSize = 13, ClearTextOnFocus = false, ZIndex = 2, Parent = PillFrame }, { TextColor3 = "Text" })
    local PillScale = Instance.new("UIScale", PillFrame)

    local Track = Library.Utils.Make("Frame", { Size = UDim2.new(1, -40, 0, 4), Position = UDim2.new(0, 20, 1, -12), AnchorPoint = Vector2.new(0, 1), Parent = SliderContainer }, { BackgroundColor3 = "Sidebar" })
    Library.Utils.Make("UICorner", { CornerRadius = UDim.new(1, 0), Parent = Track })

    local Fill = Library.Utils.Make("Frame", { Size = UDim2.new(0, 0, 1, 0), Parent = Track }, { BackgroundColor3 = "Accent" })
    Library.Utils.Make("UICorner", { CornerRadius = UDim.new(1, 0), Parent = Fill })

    local Knob = Library.Utils.Make("Frame", { Size = UDim2.new(0, 12, 0, 12), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(1, 0, 0.5, 0), Parent = Fill }, { BackgroundColor3 = "Text" })
    Library.Utils.Make("UICorner", { CornerRadius = UDim.new(1, 0), Parent = Knob })
    local KnobScale = Instance.new("UIScale", Knob)
    
     
    local FPSTrigger = Library.Utils.Make("TextButton", { Size = UDim2.new(1, 0, 0, 30), Position = UDim2.new(0, 0, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5), BackgroundTransparency = 1, Text = "", Parent = Track })

    local MinFPS, maxFPS = 2, 360
    local RawSavedFPS = getgenv().FPSLimit or 0
    local CurrentVisualFPS = (RawSavedFPS == 0) and MaxFPS or RawSavedFPS 
    local IsDragging = false
    local IsUncapped = false

    local function UpdateVisuals(Val)
        local Pct = math.clamp((Val - MinFPS) / (MaxFPS - MinFPS), 0, 1)
        TweenService:Create(Fill, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Size = UDim2.new(Pct, 0, 1, 0)}):Play()
        
        if Val == MaxFPS then
            ValueText.Text = "Uncapped"
            if not IsUncapped then
                IsUncapped = true
                if Library.ThemeObjects[ValueText] then Library.ThemeObjects[ValueText] = { TextColor3 = "Accent" } end
                if Library.ThemeObjects[PillStroke] then Library.ThemeObjects[PillStroke] = { Color = "Accent" } end
                TweenService:Create(ValueText, TweenInfo.new(0.2), {TextColor3 = Library.CurrentTheme.Accent}):Play()
                TweenService:Create(PillStroke, TweenInfo.new(0.2), {Color = Library.CurrentTheme.Accent}):Play()
                PillScale.Scale = 0.85; TweenService:Create(PillScale, TweenInfo.new(0.4, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1}):Play()
            end
        else
            ValueText.Text = tostring(Val)
            if IsUncapped then
                IsUncapped = false
                if Library.ThemeObjects[ValueText] then Library.ThemeObjects[ValueText] = { TextColor3 = "Text" } end
                if Library.ThemeObjects[PillStroke] then Library.ThemeObjects[PillStroke] = { Color = "Stroke" } end
                TweenService:Create(ValueText, TweenInfo.new(0.2), {TextColor3 = Library.CurrentTheme.Text}):Play()
                TweenService:Create(PillStroke, TweenInfo.new(0.2), {Color = Library.CurrentTheme.Stroke}):Play()
            end
        end
    end

    local function UpdateDrag(Input)
        local AbsolutePos = Track.AbsolutePosition.X
        local absoluteSize = Track.AbsoluteSize.X
        local Pct = math.clamp((Input.Position.X - AbsolutePos) / absoluteSize, 0, 1)
        local SnappedValue = math.floor(MinFPS + (MaxFPS - MinFPS) * Pct)
        
        if CurrentVisualFPS ~= SnappedValue then
            CurrentVisualFPS = SnappedValue
            UpdateVisuals(CurrentVisualFPS)
            local ActualFPS = (CurrentVisualFPS == MaxFPS) and 0 or CurrentVisualFPS
            getgenv().FPSLimit = ActualFPS
            if not getgenv().EcoModeEnabled and setfpscap then pcall(function() setfpscap(ActualFPS) end) end
        end
    end

    ValueText.FocusLost:Connect(function()
        local Num = tonumber(ValueText.Text:match("%d+"))
        if Num then
            Num = math.clamp(Num, MinFPS, MaxFPS)
            CurrentVisualFPS = Num
            UpdateVisuals(CurrentVisualFPS)
            local ActualFPS = (CurrentVisualFPS == MaxFPS) and 0 or CurrentVisualFPS
            getgenv().FPSLimit = ActualFPS
            if not getgenv().EcoModeEnabled and setfpscap then pcall(function() setfpscap(ActualFPS) end) end
        else
            ValueText.Text = (CurrentVisualFPS == MaxFPS) and "Uncapped" or tostring(CurrentVisualFPS)
        end
    end)

    UpdateVisuals(CurrentVisualFPS)

    Library:Connect(FPSTrigger.InputBegan, function(Input)
        if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then
            IsDragging = true; TweenService:Create(KnobScale, TweenInfo.new(0.2, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1.35}):Play(); UpdateDrag(Input)
        end
    end)

    Library:Connect(UserInputService.InputEnded, function(Input)
        if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then
            IsDragging = false; TweenService:Create(KnobScale, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Scale = 1}):Play()
        end
    end)

    Library:Connect(UserInputService.InputChanged, function(Input)
        if IsDragging and (Input.UserInputType == Enum.UserInputType.MouseMovement or Input.UserInputType == Enum.UserInputType.Touch) then UpdateDrag(Input) end
    end)

    Library:Connect(SliderContainer.MouseEnter, function() TweenService:Create(ContainerStroke, TweenInfo.new(0.3), {Transparency = 0.5}):Play() end)
    Library:Connect(SliderContainer.MouseLeave, function() TweenService:Create(ContainerStroke, TweenInfo.new(0.3), {Transparency = 0}):Play() end)
    
    Tab:CreateToggle({
        Name = "Extreme Performance (NoRender)", Description = "Kills 3D rendering, shadows, and textures for MAX FPS.", Flag = "PerformanceModeEnabled", Default = getgenv().PerformanceModeEnabled or false,
        Callback = function(State)
            getgenv().PerformanceModeEnabled = State
            local Terrain = workspace:FindFirstChildOfClass("Terrain")
            if State then
                Lighting.GlobalShadows = false; Lighting.FogEnd = 9e9; Lighting.ShadowSoftness = 0; Lighting.Brightness = 0
                if Terrain then Terrain.WaterWaveSize = 0; Terrain.WaterWaveSpeed = 0; Terrain.WaterReflectance = 0; Terrain.WaterTransparency = 0 end
                pcall(function() settings().Rendering.QualityLevel = Enum.QualityLevel.Level01 end)
            else
                Lighting.GlobalShadows = true; Lighting.Brightness = 1
                pcall(function() settings().Rendering.QualityLevel = Enum.QualityLevel.Automatic end)
            end
        end
    })
end

return Module]==],
    ["/raw/modules/adm_main/settings"] = [==[local SettingsModule = {}

function SettingsModule:Init()
    local Players = game:GetService("Players")
    local LocalPlayer = Players.LocalPlayer
    local GuiService = game:GetService("GuiService")
    local TeleportService = game:GetService("TeleportService")

    if getgenv().DuskReconnected then
        task.spawn(function()
            local GetThreadId = (getidentity or getthreadidentity or getthreadcontext)
            local SetThreadId = (setidentity or setthreadidentity or setthreadcontext)
            local OldIdentity = GetThreadId and GetThreadId() or 7

            local RS = game:GetService("ReplicatedStorage")
            local Fsys = require(RS:WaitForChild("Fsys"))

            pcall(function() 
                RS:WaitForChild("API"):WaitForChild("MainMenuAPI/AcceptTermsOfServiceAndPrivacyPolicy"):FireServer() 
            end)
            
            if SetThreadId then SetThreadId(2) end
            
            local Success, err = pcall(function()
                local UIManager = Fsys.load("UIManager")
                local SpawnSequenceHelper = Fsys.load("new:SpawnSequenceHelper")
                
                UIManager.wait_for_initialization()

                pcall(function()
                    local Apps = UIManager.apps
                    
                    if Apps.DialogApp and Apps.DialogApp.dialog then
                        Apps.DialogApp.dialog = function(_, Config)
                            if type(Config) == "table" then
                                local DType = Config.dialog_type
                                if DType == "SpawnChooserDialog" then return "Home" end
                                if DType == "ThemeColorDialog" then return "Default" end
                                if DType == "DailyDiscountsDialog" then return "exit" end
                            end
                            return "Okay"
                        end
                    end

                    local MainMenuApp = Apps.MainMenuApp
                    if MainMenuApp then
                        MainMenuApp.show = function() end 
                        if MainMenuApp.instance then
                            MainMenuApp.instance.Enabled = false
                        end
                        if Apps.TransitionsApp then
                            Apps.TransitionsApp:clear_blur(MainMenuApp.ClassName or "MainMenuApp")
                        end
                    end

                    if Apps.NewsApp then
                        Apps.NewsApp.show = function() end
                    end

                    UIManager.set_app_visibility("MainMenuApp", false)
                    UIManager.set_app_visibility("DialogApp", false)
                    UIManager.set_app_visibility("NewsApp", false)

                     
                    if getgenv().HideInvitesMenu then
                        if Apps.PartyInvitesApp then
                            Apps.PartyInvitesApp.show = function() end
                            if Apps.PartyInvitesApp.instance then Apps.PartyInvitesApp.instance.Enabled = false end
                        end
                        UIManager.set_app_visibility("PartyInvitesApp", false)
                    end
                end)
                
                SpawnSequenceHelper.enter_house()
                task.wait(1.5)
                SpawnSequenceHelper.finish_sequence()
            end)

            if SetThreadId then SetThreadId(OldIdentity) end
        end)
    end

     
    task.spawn(function()
        local Domain = getgenv().DuskDomain
        local ApiURL = Domain .. "/api/version/" .. tostring(getgenv().ScriptID)

        while task.wait(300) do  
            if getgenv().AutoUpdateKicker then
                pcall(function()
                    local Response = game:HttpGet(ApiURL)
                    local Data = game:GetService("HttpService"):JSONDecode(Response)
                    
                    if Data and Data.version and Data.version ~= getgenv().DuskVersion then
                        LocalPlayer:Kick("\n[ Dusk & Shine ]\n\nDetected new script version: " .. data.version .. "\nKicked for auto-reconnect update.")
                    end
                end)
            end
        end
    end)

     
    task.spawn(function()
        while task.wait(5) do  
            if getgenv().AutoReconnectEnabled and getgenv().HeapReconnecterEnabled and getgenv().HeapLimit then
                local CurrentMb = math.floor(gcinfo() / 1024)
                
                if CurrentMb >= getgenv().HeapLimit then
                    local LogFunc = (getgenv().DuskCore and getgenv().DuskCore.print) or print
                    LogFunc("[Dusk&Shine] 💥 Lua Heap Limit Exceeded (" .. currentMb .. " MB). Forcing Reconnect!")
                    LocalPlayer:Kick("Memory Limit Reached (Heap Reconnecter)\nReconnecting...")
                end
            end
        end
    end)

     
    GuiService.ErrorMessageChanged:Connect(function(ErrMessage)
        if ErrMessage and ErrMessage ~= "" and getgenv().AutoReconnectEnabled then
            local LogFunc = (getgenv().DuskCore and getgenv().DuskCore.print) or print
            local LowerErr = string.lower(ErrMessage)

             
             
            if string.find(LowerErr, "dusk & shine") or string.find(LowerErr, "banned") or string.find(LowerErr, "268") or string.find(LowerErr, "unexpected client behavior") then
                LogFunc("[Dusk&Shine] 🛑 Critical dsconnect Auto-Reconnect disabled..")
                return 
            end

             
             
             
            if string.find(LowerErr, "teleport") or string.find(LowerErr, "full") or string.find(LowerErr, "restricted") or string.find(LowerErr, "773") or string.find(LowerErr, "770") then
                LogFunc("[Dusk&Shine] 🚷 Server Hop or Rejoin Server issue. staying..")
                
                 
                pcall(function()
                    local VirtualUser = game:GetService("VirtualUser")
                    VirtualUser:CaptureController()
                    VirtualUser:ClickButton1(Vector2.new(0, 0))
                end)
                return
            end

             
            LogFunc("[Dusk&Shine] ⚠️ Network Error. Auto-Reconnecting...")
            
            task.wait(5) 

                        -- Loader reinjection removed (offline build)
                        
            pcall(function()
                TeleportService:TeleportToPlaceInstance(game.PlaceId, game.JobId, LocalPlayer)
            end)
            
            task.wait(6)
            
            pcall(function()
                TeleportService:Teleport(game.PlaceId, LocalPlayer)
            end)
        end
    end)
end

return SettingsModule]==],
    ["/raw/modules/adm_main/halloween_ui"] = [==[local Module = {}

function Module:Init(Library, Window, Tab)
    local TweenService = game:GetService("TweenService")
    
    if Tab.CreateDivider then Tab:CreateDivider({ Text = "Halloween 2026 Events" }) end

    local StatsCard = Library.Utils.Make("Frame", { Size = UDim2.new(1, 0, 0, 105), BackgroundTransparency = 0.3, Parent = Tab.Page }, { BackgroundColor3 = "Section" })
    Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 10), Parent = StatsCard})
    local StatsStroke = Library.Utils.Make("UIStroke", {Thickness = 1, Parent = StatsCard}, {Color = "Stroke"})
    
    StatsCard.MouseEnter:Connect(function() Library.Utils.TBT(StatsStroke, 0.25, {Color = Library.CurrentTheme.Accent}) end)
    StatsCard.MouseLeave:Connect(function() Library.Utils.TBT(StatsStroke, 0.25, {Color = Library.CurrentTheme.Stroke}) end)

     
    local CandyLbl = Library.Utils.Make("TextLabel", { Text = "🍬 Candy: 0", Size = UDim2.new(0.5, -20, 0, 20), Position = UDim2.new(0, 15, 0, 15), BackgroundTransparency = 1, Font = Enum.Font.GothamBold, TextSize = 14, TextXAlignment = Enum.TextXAlignment.Left, Parent = StatsCard }, { TextColor3 = "Text" })
    local UptimeLbl = Library.Utils.Make("TextLabel", { Text = "⏱ Uptime: 00:00:00", Size = UDim2.new(0.5, -20, 0, 20), Position = UDim2.new(0, 15, 0, 45), BackgroundTransparency = 1, Font = Enum.Font.GothamMedium, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left, Parent = StatsCard }, { TextColor3 = "SubText" })
    local KeysLbl = Library.Utils.Make("TextLabel", { Text = "🔑 Keys Looted: 0", Size = UDim2.new(0.5, -20, 0, 20), Position = UDim2.new(0, 15, 0, 75), BackgroundTransparency = 1, Font = Enum.Font.GothamMedium, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left, Parent = StatsCard }, { TextColor3 = "SubText" })

     
    local PerHourLbl = Library.Utils.Make("TextLabel", { Text = "📈 Per Hour: 0", Size = UDim2.new(0.5, -20, 0, 20), Position = UDim2.new(0.5, 5, 0, 15), BackgroundTransparency = 1, Font = Enum.Font.GothamBold, TextSize = 13, TextXAlignment = Enum.TextXAlignment.Right, Parent = StatsCard }, { TextColor3 = "Accent" })
    local PerDayLbl = Library.Utils.Make("TextLabel", { Text = "🗓 Per Day: 0", Size = UDim2.new(0.5, -20, 0, 20), Position = UDim2.new(0.5, 5, 0, 45), BackgroundTransparency = 1, Font = Enum.Font.GothamMedium, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Right, Parent = StatsCard }, { TextColor3 = "SubText" })

     
    getgenv().HalloweenStartTime = getgenv().HalloweenStartTime or os.time()
    getgenv().HalloweenStartCandy = getgenv().HalloweenStartCandy or -1
    
     
    getgenv().HalloweenSessionKeysLooted = getgenv().HalloweenSessionKeysLooted or 0
    getgenv().HalloweenLastKeyCount = getgenv().HalloweenLastKeyCount or -1

    task.spawn(function()
        while task.wait(1) do
            if not StatsCard.Parent then break end
            local DuskCore = getgenv().DuskCore
            if not DuskCore or not DuskCore.M then continue end
            
             
             
             
            local CurrentCandy = DuskCore.M.ClientData.get("candy_2026") or DuskCore.M.ClientData.get("candy") or 0
            
            if getgenv().HalloweenStartCandy == -1 and CurrentCandy > 0 then
                getgenv().HalloweenStartCandy = CurrentCandy
            end
            
            local StartCandy = getgenv().HalloweenStartCandy > 0 and getgenv().HalloweenStartCandy or CurrentCandy
            local Earned = math.max(0, CurrentCandy - StartCandy)
            
             
             
             
            local CurrentKeys = 0
            local Inv = DuskCore.M.ClientData.get("inventory", "Raw") or DuskCore.M.ClientData.get("inventory") or {}
            
             
            if type(Inv) == "table" then
                for Cat, Items in pairs(Inv) do
                    if type(Items) == "table" then
                        for Uid, Item in pairs(Items) do
                            if tostring(Item.kind or Item.id) == "halloween_2026_rusty_key" then
                                CurrentKeys = CurrentKeys + 1
                            end
                        end
                    end
                end
            end

            if getgenv().HalloweenLastKeyCount == -1 then
                getgenv().HalloweenLastKeyCount = CurrentKeys
            else
                 
                if CurrentKeys > getgenv().HalloweenLastKeyCount then
                    getgenv().HalloweenSessionKeysLooted = getgenv().HalloweenSessionKeysLooted + (CurrentKeys - getgenv().HalloweenLastKeyCount)
                end
                 
                getgenv().HalloweenLastKeyCount = CurrentKeys
            end

             
             
             
            local Uptime = os.time() - getgenv().HalloweenStartTime
            if Uptime < 1 then Uptime = 1 end
            
            local PerHour = math.floor((Earned / Uptime) * 3600)
            local PerDay = PerHour * 24
            
            local H = math.floor(Uptime / 3600)
            local m = math.floor((Uptime % 3600) / 60)
            local S = Uptime % 60
            
            local function CommaValue(Amount)
                local Formatted = tostring(Amount)
                while true do  
                    Formatted, k = string.gsub(Formatted, "^(-?%d+)(%d%d%d)", '%1,%2')
                    if (k==0) then break end
                end
                return Formatted
            end
            
            CandyLbl.Text = string.format("🍬 Candy: %s (+%s)", CommaValue(CurrentCandy), CommaValue(Earned))
            UptimeLbl.Text = string.format("⏱ Uptime: %02d:%02d:%02d", H, m, S)
            KeysLbl.Text = string.format("🔑 Keys Looted: %s", CommaValue(getgenv().HalloweenSessionKeysLooted))
            
            if Uptime > 30 and Earned > 0 then
                PerHourLbl.Text = string.format("📈 Per Hour: %s", CommaValue(PerHour))
                PerDayLbl.Text = string.format("🗓 Per Day: %s", CommaValue(PerDay))
            else
                PerHourLbl.Text = "📈 Per Hour: Calc..."
                PerDayLbl.Text = "🗓 Per Day: Calc..."
            end
            
            Library.ThemeObjects[PerHourLbl] = { TextColor3 = "Accent" }
            PerHourLbl.TextColor3 = Library.CurrentTheme and Library.CurrentTheme.Accent or Color3.fromRGB(46, 204, 113)
        end
    end)

     
     
     
    local CryptMaster = Library.Utils.Make("Frame", { Size = UDim2.new(1, 0, 0, 115), BackgroundTransparency = 0.3, ClipsDescendants = true, ZIndex = 1, Parent = Tab.Page }, { BackgroundColor3 = "Section" }) 
