    local function SyncCryptModes()
        local Mode = getgenv().CryptMode
        local Theme = Library.CurrentTheme or Library.Themes.Dark
        local ActiveTextColor = Color3.fromRGB(20, 20, 25)
        if Library.CurrentThemeName == "Galaxy" then ActiveTextColor = Color3.new(1, 1, 1) end

        Library.ThemeObjects[BtnFast] = nil; Library.ThemeObjects[StrFast] = nil
        Library.ThemeObjects[BtnAll] = nil; Library.ThemeObjects[StrAll] = nil
        Library.ThemeObjects[BtnTwigs] = nil; Library.ThemeObjects[StrTwigs] = nil

        local GradF = BtnFast:FindFirstChild("DuskShine_Gradient")
        local GradA = BtnAll:FindFirstChild("DuskShine_Gradient")
        local GradT = BtnTwigs:FindFirstChild("DuskShine_Gradient")
        if Mode ~= "Fast Spider" and GradF then GradF:Destroy() end
        if Mode ~= "All" and GradA then GradA:Destroy() end
        if Mode ~= "Twigs + Spider" and GradT then GradT:Destroy() end

        if Mode == "Fast Spider" then Library.Utils.ApplyGradient(BtnFast, Theme.Accent)
        elseif Mode == "All" then Library.Utils.ApplyGradient(BtnAll, Theme.Accent)
        elseif Mode == "Twigs + Spider" then Library.Utils.ApplyGradient(BtnTwigs, Theme.Accent) end

        local function UpdateBtn(Btn, Str, IsAct)
            TweenService:Create(Btn, TweenInfo.new(0.2), { BackgroundColor3 = IsAct and Theme.Accent or Theme.Sidebar, TextColor3 = IsAct and ActiveTextColor or Theme.SubText }):Play()
            TweenService:Create(Str, TweenInfo.new(0.2), { Color = IsAct and Theme.Accent or Theme.Stroke }):Play()
        end

        UpdateBtn(BtnFast, StrFast, mode == "Fast Spider")
        UpdateBtn(BtnAll, StrAll, mode == "All")
        UpdateBtn(BtnTwigs, StrTwigs, mode == "Twigs + Spider")
    end

    ModeThemeCatcher:GetPropertyChangedSignal("BackgroundColor3"):Connect(SyncCryptModes)
    SyncCryptModes()

    BtnFast.MouseButton1Click:Connect(function() getgenv().CryptMode = "Fast Spider"; SyncCryptModes(); if getgenv().SaveConfig then pcall(getgenv().SaveConfig) end end)
    BtnAll.MouseButton1Click:Connect(function() getgenv().CryptMode = "All"; SyncCryptModes(); if getgenv().SaveConfig then pcall(getgenv().SaveConfig) end end)
    BtnTwigs.MouseButton1Click:Connect(function() getgenv().CryptMode = "Twigs + Spider"; SyncCryptModes(); if getgenv().SaveConfig then pcall(getgenv().SaveConfig) end end)

