            local TargetColor = State and (Library.CurrentTheme and Library.CurrentTheme.Accent or Color3.fromRGB(46, 204, 113)) or (Library.CurrentTheme and Library.CurrentTheme.ToggleOff or Color3.fromRGB(55, 55, 60))
            Library.Utils.TBT(CToggleBg, 0.25, {BackgroundColor3 = TargetColor})
            TweenService:Create(CToggleKnob, TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Position = State and COnP or COffP}):Play()
            if State then
                Library.Utils.ApplyGradient(CToggleBg, Library.CurrentTheme and Library.CurrentTheme.Accent or Color3.fromRGB(46, 204, 113))
            else
                local Grad = CToggleBg:FindFirstChild("DuskShine_Gradient")
                if Grad then Grad:Destroy() end
            end
        end
    }

