            local NestManager = DuskCore.M.ClientData.get("halloween_2026_jacobean_pigeon_nest_manager")
            TwigsContributed = NestManager and NestManager.twigs_contributed or 0
        end

         
        if not TwState and TwigsContributed >= 8 then
            getgenv().UpdateTwigStatus("Unlocked Jacobean Pigeon", false)
            if Library.Notify then Library:Notify("Halloween 2026", "You already unlocked the Jacobean Pigeon! Set up auto-buy in Purchases.", 4) end
            return
        end

        TwState = not TwState
        getgenv().HalloweenEventFarmEnabled = TwState
        
        Library.ThemeObjects[TwigBg] = { BackgroundColor3 = TwState and "Accent" or "ToggleOff" }
        local TargetColor = TwState and (Library.CurrentTheme and Library.CurrentTheme.Accent or Color3.fromRGB(46, 204, 113)) or (Library.CurrentTheme and Library.CurrentTheme.ToggleOff or Color3.fromRGB(55, 55, 60))
        
