            getgenv().UpdateTwigStatus("Searching for twigs...")
        else
            local Grad = TwigBg:FindFirstChild("DuskShine_Gradient")
            if Grad then Grad:Destroy() end
            
            if TwigsContributed >= 8 then
                getgenv().UpdateTwigStatus("Unlocked Jacobean Pigeon", false)
            else
                getgenv().UpdateTwigStatus("Idle", false)
            end
        end
        
        if getgenv().SaveConfig then pcall(getgenv().SaveConfig) end
    end)

     
