                    if Grad then Grad:Destroy() end
                end
            end
        end
    end)

     
    local function CreateHalloweenToggle(Name, Desc, Flag, Default)
        local Card = Library.Utils.Make("Frame", { Size = UDim2.new(1, 0, 0, 60), BackgroundTransparency = 0.3, Parent = Tab.Page }, { BackgroundColor3 = "Section" })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 8), Parent = Card})
        local Stroke = Library.Utils.Make("UIStroke", {Thickness = 1, Parent = Card}, { Color = "Stroke" })
        
        Card.MouseEnter:Connect(function() Library.Utils.TBT(Stroke, 0.25, {Color = Library.CurrentTheme.Accent}) end)
        Card.MouseLeave:Connect(function() Library.Utils.TBT(Stroke, 0.25, {Color = Library.CurrentTheme.Stroke}) end)

        Library.Utils.Make("TextLabel", { Text = Name, Size = UDim2.new(1, -70, 0, 16), Position = UDim2.new(0, 15, 0, 12), BackgroundTransparency = 1, Font = Enum.Font.GothamBold, TextSize = 14, TextXAlignment = Enum.TextXAlignment.Left, Parent = Card }, { TextColor3 = "Text" })
        Library.Utils.Make("TextLabel", { Text = Desc, Size = UDim2.new(1, -70, 0, 14), Position = UDim2.new(0, 15, 0, 32), BackgroundTransparency = 1, Font = Enum.Font.GothamMedium, TextSize = 11, TextXAlignment = Enum.TextXAlignment.Left, Parent = Card }, { TextColor3 = "SubText" })

        local Sw = Library.Utils.Make("TextButton", { Text = "", Size = UDim2.new(0, 44, 0, 24), AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -15, 0.5, 0), BackgroundTransparency = 1, Parent = Card })
        getgenv()[Flag] = getgenv()[Flag] or Default
        local State = getgenv()[Flag]

        local Bg = Library.Utils.Make("Frame", { Size = UDim2.new(1, 0, 1, 0), Parent = Sw }, { BackgroundColor3 = State and "Accent" or "ToggleOff" })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(1,0), Parent = Bg})
        local OnP, OffP = UDim2.new(1, -22, 0.5, -10), UDim2.new(0, 2, 0.5, -10)
        local Knob = Library.Utils.Make("Frame", { Size = UDim2.new(0, 20, 0, 20), Position = State and OnP or OffP, Parent = Bg }, { BackgroundColor3 = "Knob" })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(1,0), Parent = Knob})

        Sw.MouseButton1Click:Connect(function()
            State = not State
            getgenv()[Flag] = State
            Library.ThemeObjects[Bg] = { BackgroundColor3 = State and "Accent" or "ToggleOff" }
            Library.Utils.TBT(Bg, 0.25, {BackgroundColor3 = State and Library.CurrentTheme.Accent or Library.CurrentTheme.ToggleOff})
            Library.Utils.TBT(Knob, 0.25, {Position = State and OnP or OffP})

            if State then
                Library.Utils.ApplyGradient(Bg, Library.CurrentTheme.Accent or Color3.fromRGB(46, 204, 113))
            else
                local Grad = Bg:FindFirstChild("DuskShine_Gradient")
                if Grad then Grad:Destroy() end
            end
            if getgenv().SaveConfig then pcall(getgenv().SaveConfig) end
        end)
    end

