            local lbl = Library.Utils.Make("TextLabel", { Text = name, Size = UDim2.new(1, -30, 1, 0), Position = UDim2.new(0, 12, 0, 0), BackgroundTransparency = 1, Font = Enum.Font.GothamBold, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left, Parent = btn }, { TextColor3 = "Text" })

            local Dot = Library.Utils.Make("Frame", { Size = UDim2.new(0, 8, 0, 8), Position = UDim2.new(1, -15, 0.5, 0), AnchorPoint = Vector2.new(1, 0.5), BackgroundColor3 = Color3.fromRGB(46, 204, 113), Visible = false, Parent = btn })
            Library.Utils.Make("UICorner", { CornerRadius = UDim.new(1, 0), Parent = Dot })
            local DotGlow = Library.Utils.Make("UIStroke", { Thickness = 1, Transparency = 0.5, Color = Color3.fromRGB(46, 204, 113), Parent = Dot })
            
            local PulseAnim = TweenService:Create(DotGlow, TweenInfo.new(1.2, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), {Thickness = 4, Transparency = 0.9})
            local scale = Instance.new("UIScale", btn)

            local function UpdateState()
                local IsActive = getgenv()[FlagName]
                local VisualActive = IsActive and getgenv().MasterPopupsEnabled

                Dot.Visible = VisualActive
                if VisualActive then 
                    PulseAnim:Play() 
                    Library.ThemeObjects[stroke] = { Color = "Accent" }
                    stroke.Color = Library.CurrentTheme and Library.CurrentTheme.Accent or Color3.fromRGB(46, 204, 113)
                else 
                    PulseAnim:Cancel()
                    DotGlow.Thickness = 1
                    DotGlow.Transparency = 0.5
                    Library.ThemeObjects[stroke] = { Color = "Stroke" }
                    stroke.Color = Library.CurrentTheme and Library.CurrentTheme.Stroke or Color3.fromRGB(50, 50, 55)
                end
            end

            btn.MouseEnter:Connect(function() if not getgenv()[FlagName] or not getgenv().MasterPopupsEnabled then Library.Utils.TBT(stroke, 0.2, {Color = Library.CurrentTheme.Accent}) end end)
            btn.MouseLeave:Connect(function() if not getgenv()[FlagName] or not getgenv().MasterPopupsEnabled then Library.Utils.TBT(stroke, 0.2, {Color = Library.CurrentTheme.Stroke}) end end)
            btn.MouseButton1Down:Connect(function() TweenService:Create(scale, TweenInfo.new(0.1), {Scale = 0.95}):Play() end)
            
            btn.MouseButton1Click:Connect(function()
                TweenService:Create(scale, TweenInfo.new(0.15), {Scale = 1}, Enum.EasingStyle.Bounce):Play()
                if not getgenv().MasterPopupsEnabled then return end 
                
                getgenv()[FlagName] = not getgenv()[FlagName]
                UpdateState()
                if getgenv().SaveConfig then pcall(getgenv().SaveConfig) end
            end)

            table.insert(TileUpdaters, UpdateState)
            UpdateState()
        end

        CreateMetroTile("Trade Popups", "DisableTradePopups")
        CreateMetroTile("Invites Popups", "DisablePartyInvites")
        CreateMetroTile("Event Popups", "DisableEventPopups")

         
        local function ForceBlockApp(AppName, FlagName)
            local Pg = LocalPlayer:WaitForChild("PlayerGui")

            local function AttachHook(App)
                if App:IsA("ScreenGui") then
                    if getgenv().MasterPopupsEnabled and getgenv()[FlagName] and App.Enabled then App.Enabled = false end
                    
                    App:GetPropertyChangedSignal("Enabled"):Connect(function()
                        if getgenv().MasterPopupsEnabled and getgenv()[FlagName] and App.Enabled then
                            App.Enabled = false
                        end
                    end)
                end

                if AppName == "EventPopupApp" then
                    local function HookPopup(Child)
                        if Child.Name == "Popup" and Child:IsA("GuiObject") then
                            if getgenv().MasterPopupsEnabled and getgenv()[FlagName] and Child.Visible then Child.Visible = false end
                            Child:GetPropertyChangedSignal("Visible"):Connect(function()
                                if getgenv().MasterPopupsEnabled and getgenv()[FlagName] and Child.Visible then
                                    Child.Visible = false
                                end
                            end)
                        end
                    end
                    for _, Child in ipairs(App:GetChildren()) do HookPopup(Child) end
                    App.ChildAdded:Connect(HookPopup)
                end
            end

            local ExistingApp = Pg:FindFirstChild(AppName)
            if ExistingApp then AttachHook(ExistingApp) end

            Pg.ChildAdded:Connect(function(Child)
                if Child.Name == AppName then
                    AttachHook(Child)
                end
            end)
        end

        ForceBlockApp("DialogApp", "DisableTradePopups")
        ForceBlockApp("PartyInvitationApp", "DisablePartyInvites")
        ForceBlockApp("EventPopupApp", "DisableEventPopups")
    end

     
     
     
    
