    local function CreateMNFRButton(Letter, Order, VarKey)
        local btn = Library.Utils.Make("TextButton", { Text = "", Size = UDim2.new(0.25, -6, 1, 0), BackgroundTransparency = 0.5, LayoutOrder = Order, Parent = MNFRFrame, ClipsDescendants = true }, { BackgroundColor3 = "Section" })
