        Library.Utils.Make("UIStroke", { Thickness = 2, Parent = btn }, { Color = "Stroke" })
        
        local fill = Library.Utils.Make("Frame", { Size = UDim2.new(1.2, 0, 0, 0), Position = UDim2.new(-0.1, 0, 1.1, 0), AnchorPoint = Vector2.new(0, 1), Rotation = math.random(-5, 5), BackgroundColor3 = MnfrColors[Letter], BorderSizePixel = 0, ZIndex = 10, Parent = btn })
        local Txt = Library.Utils.Make("TextLabel", { Text = Letter, Size = UDim2.new(1, 0, 1, 0), Font = Enum.Font.PermanentMarker, TextSize = 42, Rotation = LetterRot[Letter], BackgroundTransparency = 1, ZIndex = 11, Parent = btn }, { TextColor3 = "Text" })

        local IsActive = getgenv().VisualVars[VarKey]
        fill.Size = UDim2.new(1.2, 0, IsActive and 1.2 or 0, 0)
        Txt.TextColor3 = IsActive and Color3.new(1,1,1) or (Library.CurrentTheme and Library.CurrentTheme.Text or Color3.new(1,1,1))

        MnfrUI[VarKey] = { fill = fill, txt = Txt }

        btn.MouseButton1Click:Connect(function()
            getgenv().VisualVars[VarKey] = not getgenv().VisualVars[VarKey]
            local State = getgenv().VisualVars[VarKey]
            for _, Child in ipairs(btn.Parent:GetChildren()) do
                if Child:IsA("TextButton") then Child.ZIndex = 1 end
            end
            btn.ZIndex = State and 5 or 1
            
             
            if State then
                if VarKey == "Mega" and getgenv().VisualVars["Neon"] then
                    getgenv().VisualVars["Neon"] = false
                    TweenService:Create(MnfrUI["Neon"].fill, TweenInfo.new(0.3), { Size = UDim2.new(1.2, 0, 0, 0) }):Play()
                    TweenService:Create(MnfrUI["Neon"].txt, TweenInfo.new(0.2), { TextColor3 = Library.CurrentTheme and Library.CurrentTheme.Text or Color3.new(1,1,1) }):Play()
                elseif VarKey == "Neon" and getgenv().VisualVars["Mega"] then
                    getgenv().VisualVars["Mega"] = false
                    TweenService:Create(MnfrUI["Mega"].fill, TweenInfo.new(0.3), { Size = UDim2.new(1.2, 0, 0, 0) }):Play()
                    TweenService:Create(MnfrUI["Mega"].txt, TweenInfo.new(0.2), { TextColor3 = Library.CurrentTheme and Library.CurrentTheme.Text or Color3.new(1,1,1) }):Play()
                end
            end

            TweenService:Create(fill, TweenInfo.new(0.3, Enum.EasingStyle.Bounce, Enum.EasingDirection.Out), { Size = UDim2.new(1.2, 0, State and 1.2 or 0, 0) }):Play()
            TweenService:Create(Txt, TweenInfo.new(0.2), { TextColor3 = State and Color3.new(1,1,1) or (Library.CurrentTheme and Library.CurrentTheme.Text or Color3.new(1,1,1)) }):Play()
            if Library and type(Library.Notify) == "function" then
                Library:Notify("Pet Visualiser", VarKey .. " mode is " .. (State and "ON" or "OFF"), 2, "rbxassetid://17829956110", "rbxassetid://72958619361915")
            end
        end)
    end

