    local IsGridExpanded = false
    local function UpdatePetGrid()
        local TotalItems = 0
        for _, Child in ipairs(PetGridContainer:GetChildren()) do 
            if not Child:IsA("UILayout") and not Child:IsA("UIPadding") then TotalItems = TotalItems + 1 end 
        end
        
        if TotalItems <= 4 then
            PetGridBg.AutomaticSize = Enum.AutomaticSize.Y
            PetGridBg.Size = UDim2.new(1, 0, 0, 0)
            FadeOverlay.Visible = false
            BottomExpandBtn.Visible = false
        else
            BottomExpandBtn.Visible = true
            
            if IsGridExpanded then
                PetGridBg.AutomaticSize = Enum.AutomaticSize.Y
                PetGridBg.Size = UDim2.new(1, 0, 0, 0)
                FadeOverlay.Visible = false  
                ExpandText.Text = "Show Less ▲"
                HiddenCountLbl.Text = ""
            else
                PetGridBg.AutomaticSize = Enum.AutomaticSize.None
                PetGridBg.Size = UDim2.new(1, 0, 0, 130)
                FadeOverlay.Visible = true  
                ExpandText.Text = "Show More ▼"
                local Cols = math.max(4, math.floor((PetGridBg.AbsoluteSize.X - 20) / 85))
                HiddenCountLbl.Text = "+" .. tostring(math.max(0, TotalItems - Cols)) .. " hidden"
            end
        end
    end

