    local FeedFGCard = CreateFeederToggle("Feed Until FullGrown", "Stops feeding age potions when pet is max level", "FeederUntilFG", getgenv().FeederUntilFG)
    FeedFGCard.LayoutOrder = 6

    local AmountInputCard = CreateFeederInput("Amount to Feed", "Limit how many potions to use (0 = infinite)", tostring(getgenv().FeederAmount), function(text, Box)
        local Num = tonumber(text:match("%d+"))
        if Num then getgenv().FeederAmount = Num else Box.Text = tostring(getgenv().FeederAmount) end
        if getgenv().SaveConfig then pcall(getgenv().SaveConfig) end
    end)
    AmountInputCard.LayoutOrder = 7

     
    local function CreateFeederTile(parent, name, ImgId, IsSelected, Callback)
        local TweenService = game:GetService("TweenService")
        
        local AccentColor = Library.CurrentTheme and Library.CurrentTheme.Accent or Color3.fromRGB(46, 204, 113)
        local StrokeColor = Library.CurrentTheme and Library.CurrentTheme.Stroke or Color3.fromRGB(25, 25, 30)
        
        local OuterGlow = Library.Utils.Make("Frame", {
            Size = UDim2.new(1, 0, 1, 0),
            BackgroundColor3 = Color3.new(1, 1, 1),
            BackgroundTransparency = IsSelected and 0 or 1,
            Parent = parent
        })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 10), Parent = OuterGlow})
        
        local GlowGrad = Instance.new("UIGradient", OuterGlow)
        GlowGrad.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, StrokeColor),
            ColorSequenceKeypoint.new(0.5, AccentColor),
            ColorSequenceKeypoint.new(1, StrokeColor)
        })
        GlowGrad.Offset = Vector2.new(-1, 0)
        
        local GradTween = TweenService:Create(GlowGrad, TweenInfo.new(1.5, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut, -1), {Offset = Vector2.new(1, 0)})
        if IsSelected then GradTween:Play() end
        
        local Card = Library.Utils.Make("TextButton", { 
            Size = UDim2.new(1, -4, 1, -4), 
            Position = UDim2.new(0.5, 0, 0.5, 0),
            AnchorPoint = Vector2.new(0.5, 0.5),
            BackgroundColor3 = Library.CurrentTheme and Library.CurrentTheme.Section or Color3.fromRGB(35, 35, 40), 
            Text = "", 
            Parent = OuterGlow 
        })
        Library.ThemeObjects[Card] = { BackgroundColor3 = "Section" }
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 8), Parent = Card})
        
        local IconContainer = Library.Utils.Make("Frame", { Size = UDim2.new(1, 0, 1, -25), Position = UDim2.new(0, 0, 0, 0), BackgroundTransparency = 1, Parent = Card })
        Library.Utils.Make("ImageLabel", { Size = UDim2.new(0, 44, 0, 44), Position = UDim2.new(0.5, 0, 0.5, 0), AnchorPoint = Vector2.new(0.5, 0.5), BackgroundTransparency = 1, ScaleType = Enum.ScaleType.Fit, Image = ImgId, Parent = IconContainer })
        Library.Utils.Make("TextLabel", { Size = UDim2.new(1, -4, 0, 14), Position = UDim2.new(0, 2, 1, -22), BackgroundTransparency = 1, Text = name, Font = Enum.Font.GothamBold, TextSize = 10, TextColor3 = Color3.fromRGB(255, 255, 255), TextWrapped = true, Parent = Card })

        local AccentLine = Library.Utils.Make("Frame", {
            Size = UDim2.new(0.6, 0, 0, 2),
            Position = UDim2.new(0.5, 0, 1, -6),
            AnchorPoint = Vector2.new(0.5, 0),
            BackgroundColor3 = AccentColor,
            BackgroundTransparency = IsSelected and 0 or 1,
            BorderSizePixel = 0,
            Parent = Card
        })
        Library.ThemeObjects[AccentLine] = { BackgroundColor3 = "Accent" }
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(1, 0), Parent = AccentLine})

        Card.MouseButton1Click:Connect(function()
            local Selected = Callback()
            OuterGlow.BackgroundTransparency = Selected and 0 or 1
            AccentLine.BackgroundTransparency = Selected and 0 or 1
            
            if Selected then
                GradTween:Play()
            else
                GradTween:Pause()
                GlowGrad.Offset = Vector2.new(-1, 0)
            end
        end)
    end

     
    getgenv().PopulateFeederUI = function()
        for _, C in ipairs(PetGridContainer:GetChildren()) do 
            if not C:IsA("UIGridLayout") and not C:IsA("UIPadding") then C:Destroy() end 
        end
        for _, C in ipairs(PotionGridContainer:GetChildren()) do 
            if not C:IsA("UIGridLayout") and not C:IsA("UIPadding") then C:Destroy() end 
        end
        
        local DuskCore = getgenv().DuskCore
        if not DuskCore or not DuskCore.M then return end
        local Inv = DuskCore.M.ClientData.get("inventory")
        if not Inv then return end

        local HasAgePotionSelected = false
        local PetHasFly, petHasRide = false, false

         
        if Inv.pets then
            local OwnedCounts = {}
            local UniquePets = {}
            getgenv().FeederTargetKinds = getgenv().FeederTargetKinds or {}

            for uid, Data in pairs(Inv.pets) do
                local kind = Data.kind or Data.id
                local Db = DuskCore.M.InventoryDB.pets[kind]
                
                if Db and not Db.is_egg then
                    local PetName = Db.name or kind
                    local Query = getgenv().FeederSearchQuery or ""
                    
                    if Query == "" or string.find(string.lower(PetName), Query, 1, true) then 
                        OwnedCounts[kind] = (OwnedCounts[kind] or 0) + 1
                        
                        if not UniquePets[kind] then
                            UniquePets[kind] = { name = PetName, db = Db, data = Data }
                        end
                    end
                end
            end

            for kind, Info in pairs(UniquePets) do
                local IsSelected = getgenv().FeederTargetKinds[kind] == true
                
                if IsSelected then
                    local Props = Info.data.properties or {}
                    if Props.flyable or Props.is_flyable then PetHasFly = true end
                    if Props.rideable or Props.is_rideable then PetHasRide = true end
                end

                local Img = Info.db.icon or Info.db.image or "122697490518955"
                Img = tonumber(Img) and "rbxassetid://"..img or Img

                CreateFeederTile(PetGridContainer, Info.name, Img, IsSelected, function()
                    if getgenv().FeederAutoSelectEquipped then 
                        if Library and type(Library.Notify) == "function" then 
                            Library:Notify("Potion Feeder", "Auto Select is ON! Cannot select manually.", 2, "rbxassetid://132396415044039", "rbxassetid://72958619361915") 
                        end
                        return IsSelected 
                    end
                    
                    if getgenv().FeederTargetKinds[kind] then 
                        getgenv().FeederTargetKinds[kind] = nil
                        if Library and type(Library.Notify) == "function" then 
                            Library:Notify("Potion Feeder", "Removed " .. info.name, 2, "rbxassetid://132396415044039", "rbxassetid://72958619361915") 
                        end
                    else 
                        getgenv().FeederTargetKinds[kind] = true
                        if Library and type(Library.Notify) == "function" then 
                            Library:Notify("Potion Feeder", "Selected " .. info.name, 2, "rbxassetid://132396415044039", "rbxassetid://72958619361915") 
                        end
                    end
                    
                    return getgenv().FeederTargetKinds[kind] == true
                end)

                 
                local Count = OwnedCounts[kind] or 1
                if Count > 1 then
                    local Cards = PetGridContainer:GetChildren()
                    local LastCard = Cards[#Cards]
                    if LastCard then
                        local DisplayCount = Count > 99 and "99+" or tostring(Count)
                        local CountLbl = Library.Utils.Make("TextLabel", { Text = "x" .. displayCount, Size = UDim2.new(0, 24, 0, 15), Position = UDim2.new(0, 4, 0, 4), Rotation = -15, BackgroundTransparency = 1, Font = Enum.Font.GothamBlack, TextSize = 12, ZIndex = 4, Parent = LastCard }, { TextColor3 = "Accent" })
                        local TxtStroke = Instance.new("UIStroke", CountLbl)
                        TxtStroke.Color = Color3.new(0, 0, 0)
                        TxtStroke.Thickness = 1.5
                    end
                end
            end

             
            RenewalCard.Visible = not HasAgePotionSelected
            FeedFGCard.Visible = HasAgePotionSelected

             
            if getgenv().FeederAutoSelectEquipped then
                if PetDivider then PetDivider.Visible = false end
                if PetGridBg then PetGridBg.Visible = false end
            else
                if PetDivider then PetDivider.Visible = true end
                if PetGridBg then PetGridBg.Visible = true end
            end

             
            if UpdatePetGrid then UpdatePetGrid() end

             
            task.spawn(function()
                task.wait(0.1)
                PotGL.CellPadding = UDim2.new(0, 10, 0, 11)
                PotGL.CellPadding = UDim2.new(0, 10, 0, 10)
                PGL.CellPadding = UDim2.new(0, 10, 0, 11)
                PGL.CellPadding = UDim2.new(0, 10, 0, 10)
            end)
        end

         
        local AgePotions = {
            ["pet_age_potion"]=true, ["tiny_pet_age_potion"]=true
        }
        local FlyPotions = {["fly_a_pet_potion"]=true, ["fly_potion"]=true, ["pet_flying_potion"]=true}
        local RidePotions = {["ride_a_pet_potion"]=true, ["ride_potion"]=true, ["pet_riding_potion"]=true}
        local AddedPots = {}
        
        local function UpdateSettingsVisibility()
            local SelectedCount = 0
            local HasAge = false
            local HasRenewable = false

            for K, V in pairs(getgenv().FeederSelectedPotions) do
                if V then
                    SelectedCount = SelectedCount + 1
                    if AgePotions[K] then
                        HasAge = true
                    elseif not FlyPotions[K] and not RidePotions[K] then
                        HasRenewable = true
                    end
                end
            end

            local WasVisible = AmountInputCard.Visible

            if SelectedCount == 0 then
                AmountInputCard.Visible = false
                RenewalCard.Visible = false
                FeedFGCard.Visible = false
            else
                AmountInputCard.Visible = true
                FeedFGCard.Visible = HasAge
                RenewalCard.Visible = HasRenewable
                
                 
                if not WasVisible then
                    local TweenService = game:GetService("TweenService")
                    
                    for _, card in ipairs({AmountInputCard, FeedFGCard, RenewalCard}) do
                        if card.Visible then
                             
                            local scale = card:FindFirstChildOfClass("UIScale") or Instance.new("UIScale", card)
                            scale.Scale = 0.85
                            TweenService:Create(scale, TweenInfo.new(0.5, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1}):Play()
                            
                             
                            local stroke = card:FindFirstChildOfClass("UIStroke")
                            if stroke then
                                local BaseColor = Library.CurrentTheme and Library.CurrentTheme.Stroke or Color3.fromRGB(50, 50, 55)
                                local AccentColor = Library.CurrentTheme and Library.CurrentTheme.Accent or Color3.fromRGB(46, 204, 113)
                                stroke.Color = AccentColor
                                TweenService:Create(stroke, TweenInfo.new(0.8, Enum.EasingStyle.Cubic, Enum.EasingDirection.Out), {Color = BaseColor}):Play()
                            end
                        end
                    end
                    
                     
                    task.spawn(function()
                        task.wait(0.05)  
                        local MaxScroll = math.max(0, FContainer.AbsoluteCanvasSize.Y - FContainer.AbsoluteWindowSize.Y)
                        if MaxScroll > 0 then
                            TweenService:Create(FContainer, TweenInfo.new(0.5, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {CanvasPosition = Vector2.new(0, MaxScroll)}):Play()
                        end
                    end)
                end
            end
        end

        if Inv.food then
            for _, Item in pairs(Inv.food) do
                local kind = Item.id or Item.kind
                if string.find(kind:lower(), "potion") and not AddedPots[kind] then
                    if FlyPotions[kind] and PetHasFly then continue end
                    if RidePotions[kind] and PetHasRide then continue end

                    AddedPots[kind] = true
                    local Db = DuskCore.M.InventoryDB.food[kind] or DuskCore.M.InventoryDB.pets[kind]
                    local Img = Db and (Db.icon or Db.image) or "122697490518955"
                    Img = tonumber(Img) and "rbxassetid://"..img or Img
                    
                    local IsSelected = getgenv().FeederSelectedPotions[kind] == true

                    CreateFeederTile(PotionGridContainer, Db and Db.name or kind, Img, IsSelected, function()
                        getgenv().FeederSelectedPotions[kind] = not getgenv().FeederSelectedPotions[kind]
                        UpdateSettingsVisibility()
                        
                        if Library and type(Library.Notify) == "function" then 
                            Library:Notify("Potion Feeder", (getgenv().FeederSelectedPotions[kind] and "Added " or "Removed ") .. (Db and Db.name or kind), 2, "rbxassetid://132396415044039", "rbxassetid://72958619361915") 
                        end
                        
                        return getgenv().FeederSelectedPotions[kind]
                    end)
                end
            end
        end

        UpdateSettingsVisibility()
        
        if getgenv().FeederAutoSelectEquipped then
            PetGridBg.Visible = false
        else
            PetGridBg.Visible = true
        end
    end

    task.spawn(function() task.wait() getgenv().PopulateFeederUI() end)

     
     
     
