    local CThemeCatcher = Library.Utils.Make("Frame", {Visible = false, Parent = CombineMaster}, {BackgroundColor3 = "Accent"})
    local function CUpdateMasterGradient()
        local BaseColor = CThemeCatcher.BackgroundColor3
        local H, S, v = BaseColor:ToHSV()
        local DarkColor = Color3.fromHSV(H, math.clamp(S + 0.1, 0, 1), math.clamp(V - 0.3, 0, 1))
        CMasterGradient.Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, DarkColor), ColorSequenceKeypoint.new(0.5, BaseColor), ColorSequenceKeypoint.new(1, DarkColor) })
    end
    CThemeCatcher:GetPropertyChangedSignal("BackgroundColor3"):Connect(CUpdateMasterGradient)
    task.spawn(function() task.wait() CUpdateMasterGradient() end)

