    local IsCGridExpanded = false
    local function UpdateCombineGrid()
        local TotalItems = 0
        for _, C in ipairs(CombineGridContainer:GetChildren()) do if not C:IsA("UILayout") and not C:IsA("UIPadding") and C.Visible then TotalItems = TotalItems + 1 end end
        
         
        if TotalItems <= 4 then
            CombineGridBg.AutomaticSize = Enum.AutomaticSize.Y
            CombineGridBg.Size = UDim2.new(1, 0, 0, 0)
            CFadeOverlay.Visible = false
            CBottomBtn.Visible = false
        else
            CBottomBtn.Visible = true
            if IsCGridExpanded then
                CombineGridBg.AutomaticSize = Enum.AutomaticSize.Y
                CombineGridBg.Size = UDim2.new(1, 0, 0, 0)
                CFadeOverlay.Visible = false
                CExpandText.Text = "Show Less ▲"
            else
