    local function SyncFeedUI()
        local IsFeed = getgenv().CombineAutoFeed
        Library.ThemeObjects[FeedBg] = { BackgroundColor3 = IsFeed and "Accent" or "ToggleOff" }
        game:GetService("TweenService"):Create(FeedBg, TweenInfo.new(0.25), {BackgroundColor3 = IsFeed and (Library.CurrentTheme and Library.CurrentTheme.Accent or Color3.fromRGB(46, 204, 113)) or (Library.CurrentTheme and Library.CurrentTheme.ToggleOff or Color3.fromRGB(55, 55, 60))}):Play()
        game:GetService("TweenService"):Create(FeedKnob, TweenInfo.new(0.25, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Position = IsFeed and fOnP or fOffP}):Play()

        if IsFeed then
            Library.Utils.ApplyGradient(FeedBg, Library.CurrentTheme and Library.CurrentTheme.Accent or Color3.fromRGB(46, 204, 113))
        else
            local Grad = FeedBg:FindFirstChild("DuskShine_Gradient")
