        game:GetService("TweenService"):Create(BtnNeon, TweenInfo.new(0.2), { BackgroundColor3 = IsNeon and (Library.CurrentTheme and Library.CurrentTheme.Accent or Color3.fromRGB(46, 204, 113)) or (Library.CurrentTheme and Library.CurrentTheme.Sidebar or Color3.fromRGB(30, 30, 35)), TextColor3 = IsNeon and Color3.fromRGB(20,20,25) or (Library.CurrentTheme and Library.CurrentTheme.SubText or Color3.new(0.6,0.6,0.6)) }):Play()
        game:GetService("TweenService"):Create(BtnMega, TweenInfo.new(0.2), { BackgroundColor3 = not IsNeon and (Library.CurrentTheme and Library.CurrentTheme.Accent or Color3.fromRGB(46, 204, 113)) or (Library.CurrentTheme and Library.CurrentTheme.Sidebar or Color3.fromRGB(30, 30, 35)), TextColor3 = not IsNeon and Color3.fromRGB(20,20,25) or (Library.CurrentTheme and Library.CurrentTheme.SubText or Color3.new(0.6,0.6,0.6)) }):Play()
    end

