    local function RefreshCombineNumbers()
        for _, Tile in ipairs(CombineTiles) do
            local Idx = table.find(getgenv().CombineQueue, Tile.Kind)
            if Idx then
                Library.Utils.TBT(Tile.Stroke, 0.2, {Color = Color3.fromRGB(170, 85, 255)})
                Tile.Label.Text = tostring(Idx)
            else
                local DefStroke = Library.CurrentTheme and Library.CurrentTheme.Stroke or Color3.fromRGB(50, 50, 55)
                Library.Utils.TBT(Tile.Stroke, 0.2, {Color = DefStroke})
                Tile.Label.Text = ""
            end
        end
    end

    local function RenderCombineGrid()
        for _, Child in ipairs(CombineGridContainer:GetChildren()) do 
            if Child:IsA("ImageButton") then Child:Destroy() end 
        end
        table.clear(CombineTiles)

        local DuskCore = getgenv().DuskCore
        if not DuskCore or not DuskCore.M then return end
        local Inv = DuskCore.M.ClientData.get("inventory")
        if not Inv or not Inv.pets then return end

        local UniquePets = {}
        local OwnedCounts = {}  

        for uid, PData in pairs(Inv.pets) do
            local kind = PData.kind or PData.id
            local Db = DuskCore.M.InventoryDB.pets[kind]
            if Db and Db.is_egg ~= true then
                local Props = PData.properties or {}
                local IsMega = (Props.mega_neon == true or Props.mega_neon == 1 or Props.is_mega == true)
                
                if not IsMega then
                    OwnedCounts[kind] = (OwnedCounts[kind] or 0) + 1
                    
                    if not UniquePets[kind] then
                        local Img = Db.icon or Db.image or Db.shop_image or "122697490518955"
                        if not string.find(tostring(Img), "rbxassetid") and tonumber(Img) then Img = "rbxassetid://"..img end
                        UniquePets[kind] = { img = Img, name = Db.name or kind }
                    end
                end
            end
        end

        for kind, Data in pairs(UniquePets) do
            local Btn = Library.Utils.Make("ImageButton", { Image = Data.img, Size = UDim2.new(1, 0, 1, 0), ScaleType = Enum.ScaleType.Fit, Parent = CombineGridContainer }, { BackgroundColor3 = "Section" })
            Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 8), Parent = Btn})
            local Stroke = Library.Utils.Make("UIStroke", {Thickness = 2, Parent = Btn}, {Color = "Stroke"})
            local Label = Library.Utils.Make("TextLabel", { Text = "", Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 1, Font = Enum.Font.GothamBlack, TextSize = 22, ZIndex = 5, Parent = Btn }, { TextColor3 = "Text" })

             
            local Count = OwnedCounts[kind] or 1
            if Count > 1 then
                local DisplayCount = Count > 99 and "99+" or tostring(Count)
                local CountLbl = Library.Utils.Make("TextLabel", { Text = "x" .. displayCount, Size = UDim2.new(0, 24, 0, 15), Position = UDim2.new(0, 4, 0, 4), Rotation = -15, BackgroundTransparency = 1, Font = Enum.Font.GothamBlack, TextSize = 12, ZIndex = 4, Parent = Btn }, { TextColor3 = "Accent" })
                local TxtStroke = Instance.new("UIStroke", CountLbl)
                TxtStroke.Color = Color3.new(0, 0, 0)
                TxtStroke.Thickness = 1.5
            end

            Btn.MouseButton1Click:Connect(function()
                local scale = Instance.new("UIScale", Btn)
                Library.Utils.TBT(scale, 0.1, {Scale = 0.85}).Completed:Connect(function()
                    Library.Utils.TBT(scale, 0.2, {Scale = 1}, Enum.EasingStyle.Bounce, Enum.EasingDirection.Out)
                    task.delay(0.2, function() scale:Destroy() end)
                end)

                local Idx = table.find(getgenv().CombineQueue, kind)
                if Idx then
                    table.remove(getgenv().CombineQueue, Idx)
                    if Library.Notify then Library:Notify("Combine Queue", "Removed from queue", 2, "rbxassetid://6761866149", "rbxassetid://72958619361915") end
                else
                    table.insert(getgenv().CombineQueue, kind)
                    if Library.Notify then Library:Notify("Combine Queue", "Added to queue", 2, "rbxassetid://6761866149", "rbxassetid://72958619361915") end
                end
                RefreshCombineNumbers()
                if getgenv().SaveConfig then pcall(getgenv().SaveConfig) end
            end)

            table.insert(CombineTiles, {Btn = Btn, Stroke = Stroke, Label = Label, Kind = kind, Name = string.lower(Data.name)})
        end
        task.spawn(function()
            task.wait(0.1)
            CGrid.CellPadding = UDim2.new(0, 12, 0, 13)
            CGrid.CellPadding = UDim2.new(0, 12, 0, 12)
        end)

        RefreshCombineNumbers()
    end

