    task.spawn(function()
        local DuskCore = getgenv().DuskCore
        while task.wait(1) do
            if not LStatusText.Parent then break end
            
            if getgenv().AutoLureEnabled then
                local NewStatus = "Idle"
                local ActiveTimers = {}
                
                local LureManager = DuskCore.M.ClientData.get("lures_2023_lure_manager")
                local Gamepasses = DuskCore.M.ClientData.get("gamepass_manager") or {}
                
                local TargetLures = { "BasicLure" }
                
                local HasCozyPass = false
                for K, V in pairs(Gamepasses) do
                    if V == "lures_2023_cozy_home_lure" or K == "lures_2023_cozy_home_lure" then
                        HasCozyPass = true
                        break
                    end
                end
                if HasCozyPass then table.insert(TargetLures, "PremiumLure") end

                local AnyReady, anyNeedCharge = false, false

                if LureManager and LureManager.lures_map then
                    for _, MapName in ipairs(TargetLures) do
                        local Lure = LureManager.lures_map[MapName]
                        if not Lure then
                            AnyNeedCharge = true
                        elseif Lure.finished then
                            AnyReady = true
                        else
                            local ActiveKind = Lure.bait_kind or Lure.bait_id or Lure.bait
                            local TargetLureTime = 14400 
                            
                            pcall(function()
                                local InvDB = DuskCore.M.InventoryDB
                                local DbEntry = InvDB.food[ActiveKind] or InvDB.pets[ActiveKind] or InvDB.toys[ActiveKind]
                                if DbEntry and DbEntry.lure_time then
                                    TargetLureTime = DbEntry.lure_time
                                else
                                    local LureConfig = require(game:GetService("ReplicatedStorage"):WaitForChild("Fsys")).load("LuresConfig")
                                    if LureConfig and LureConfig.Baits and LureConfig.Baits[ActiveKind] then
                                        TargetLureTime = LureConfig.Baits[ActiveKind].Duration or 14400
                                    end
                                end
                            end)
                            
                            local StartTs = Lure.lure_start_timestamp or Lure.start_timestamp
                            if StartTs and StartTs > 0 then
                                local FinishTime = StartTs + TargetLureTime
                                local TimeLeft = math.max(0, FinishTime - os.time())
                                if TimeLeft > 0 then
                                    local H = math.floor(TimeLeft / 3600)
                                    local m = math.floor((TimeLeft % 3600) / 60)
                                    local S = TimeLeft % 60
                                    local TimeStr = H > 0 and string.format("%02d:%02d:%02d", H, m, S) or string.format("%02d:%02d", m, S)
                                    table.insert(ActiveTimers, TimeStr)
                                end
                            else
                                AnyNeedCharge = true
                            end
                        end
                    end
                else
                    AnyNeedCharge = true
                end

                if AnyNeedCharge then
                    NewStatus = "Need Charge"
                elseif AnyReady then
                    NewStatus = "Ready to Collect"
                elseif #ActiveTimers > 0 then
                     
                    NewStatus = table.concat(ActiveTimers, " | ")
                end

                local BackendStatus = getgenv().LureStatusText or "Idle"
                if BackendStatus ~= "Idle" and not string.find(BackendStatus, "Error") then
                    NewStatus = BackendStatus
                end

                LStatusText.Text = "Status: " .. newStatus
                LStatusText.TextColor3 = Library.CurrentTheme.Accent or Color3.fromRGB(46, 204, 113)
            else
                LStatusText.Text = "Teleports home and manages bait box."
                Library.ThemeObjects[LStatusText] = { TextColor3 = "SubText" }
                LStatusText.TextColor3 = Library.CurrentTheme.SubText
            end
        end
    end)

