    local BaitGridCards = {}
    local function PopulateBaitUI()
        for _, C in ipairs(BaitGridBg:GetChildren()) do if not C:IsA("UILayout") then C:Destroy() end end
        table.clear(BaitGridCards)
        
        local DuskCore = getgenv().DuskCore
        if not DuskCore or not DuskCore.M then return end
        
        local OwnedBaits = {}
        local BaitCount = 0
        local Inv = DuskCore.M.ClientData.get("inventory", "Raw") or DuskCore.M.ClientData.get("inventory")
        
        if Inv and Inv.food then
            for uid, Data in pairs(Inv.food) do
                local kind = tostring(Data.kind or Data.id)
                if string.find(kind:lower(), "bait") or string.find(kind:lower(), "lure") then
                    if not OwnedBaits[kind] then
                        local Db = DuskCore.M.InventoryDB.food[kind] or DuskCore.M.InventoryDB.pets[kind] or DuskCore.M.InventoryDB.toys[kind]
                        local Img = Db and (Db.icon or Db.image or Db.shop_image) or "122697490518955"
                        if not string.find(tostring(Img), "rbxassetid") and tonumber(Img) then Img = "rbxassetid://" .. img end
                        OwnedBaits[kind] = { Name = Db and Db.name or kind, Image = Img }
                        BaitCount = BaitCount + 1
                    end
                end
            end
        end

         
        if BaitCount <= 1 then
            LGearBtn.Visible = false
            if BaitCount == 1 then
                for kind, _ in pairs(OwnedBaits) do getgenv().SelectedBait = kind; break end
            end
        else
            LGearBtn.Visible = true
        end
        
        for kind, Data in pairs(OwnedBaits) do
            local IsSelected = (getgenv().SelectedBait == kind)
            
            local Btn = Library.Utils.Make("TextButton", { Text = "", Size = UDim2.new(1, 0, 1, 0), Parent = BaitGridBg }, { BackgroundColor3 = "Section" })
            Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 8), Parent = Btn})
            local Stroke = Library.Utils.Make("UIStroke", {Thickness = 2, Parent = Btn}, {Color = IsSelected and "Accent" or "Stroke"})
            table.insert(BaitGridCards, { Btn = Btn, Name = Data.Name })
            
            Library.Utils.Make("ImageLabel", { Size = UDim2.new(0, 50, 0, 50), Position = UDim2.new(0.5, 0, 0, 10), AnchorPoint = Vector2.new(0.5, 0), BackgroundTransparency = 1, Image = Data.Image, Parent = Btn })
