    getgenv().UpdatePetPenSlot = function(SlotName, uid)
        local Sf = SlotFrames[SlotName]
        if not Sf then return end
        
        Sf.CurrentUID = uid
        if uid then
            local DuskCore = getgenv().DuskCore
            local PetName = "Pet"
            local Img = ""
            if DuskCore and DuskCore.M then
                local Inv = DuskCore.M.ClientData.get("inventory")
                if Inv and Inv.pets and Inv.pets[uid] then
                    local kind = Inv.pets[uid].kind or Inv.pets[uid].id
                    local Db = DuskCore.M.InventoryDB.pets[kind]
                    if Db then
                        PetName = Db.name or kind
                        Img = Db.icon or Db.image or Db.shop_image or "122697490518955"
                        if not string.find(tostring(Img), "rbxassetid") and tonumber(Img) then Img = "rbxassetid://" .. img end
                    end
                end
            end
            Sf.Icon.Image = Img
            Sf.Plus.Visible = false
            Sf.Status.Text = string.sub(PetName, 1, 8)
            Library.ThemeObjects[Sf.Status] = { TextColor3 = "Accent" }
            Sf.Status.TextColor3 = Library.CurrentTheme and Library.CurrentTheme.Accent or Color3.new(1,1,1)
        else
            Sf.Icon.Image = ""
            Sf.Plus.Visible = true
            Sf.Status.Text = "Empty"
            Library.ThemeObjects[Sf.Status] = { TextColor3 = "SubText" }
            Sf.Status.TextColor3 = Library.CurrentTheme and Library.CurrentTheme.SubText or Color3.new(0.5,0.5,0.5)
        end
        
        ActivePetCount = 0
        for _, S in pairs(SlotFrames) do if S.CurrentUID then ActivePetCount = ActivePetCount + 1 end end
    end

     
