    local function SyncPriorityVisuals()
        local IsPetPrio = (getgenv().TargetPetPenMode == "Priority")
        local IsEggPrio = (getgenv().TargetPetPenMode == "EggPriority")

        for _, Data in ipairs(PetGridCards) do
            local PrioIndex = nil
            if IsPetPrio and not Data.IsEgg then PrioIndex = table.find(getgenv().PetPenPriority, Data.Kind) end
            if IsEggPrio and Data.IsEgg then PrioIndex = table.find(getgenv().EggPenPriority, Data.Kind) end

            if PrioIndex then
                local color = PrioColors[((PrioIndex - 1) % #PrioColors) + 1]
                Data.Stroke.Color = color
                Data.Stroke.Thickness = 2
                Library.ThemeObjects[Data.Stroke] = nil 
                
                Data.Badge.Visible = true
                Data.Badge.BackgroundColor3 = color
                Data.BadgeText.Text = tostring(PrioIndex)
            else
                Data.Stroke.Thickness = 1
                Data.Stroke.Color = Library.CurrentTheme.Stroke
                Library.ThemeObjects[Data.Stroke] = { Color = "Stroke" } 
                Data.Badge.Visible = false
            end
        end
    end

    local function ApplyPetFilter()
        local PetQuery = string.lower(PPSearchInput.Text)
        local EggQuery = string.lower(EggSearchInput.Text)

        for _, Data in ipairs(PetGridCards) do
            if Data.IsEgg then
                Data.Btn.Visible = (EggQuery == "" or string.find(string.lower(Data.Name), EggQuery, 1, true))
            else
                Data.Btn.Visible = (PetQuery == "" or string.find(string.lower(Data.Name), PetQuery, 1, true))
            end
        end
        task.spawn(function()
            task.wait(0.05)
            if PrioGridBg then
                local Layout = PrioGridBg:FindFirstChildOfClass("UIGridLayout")
                if Layout then Layout.CellPadding = UDim2.new(0, 10, 0, 11); Layout.CellPadding = UDim2.new(0, 10, 0, 10) end
            end
            if EggGridBg then
                local Elayout = EggGridBg:FindFirstChildOfClass("UIGridLayout")
                if Elayout then Elayout.CellPadding = UDim2.new(0, 10, 0, 11); Elayout.CellPadding = UDim2.new(0, 10, 0, 10) end
            end
        end)
    end
    PPSearchInput:GetPropertyChangedSignal("Text"):Connect(ApplyPetFilter)
    EggSearchInput:GetPropertyChangedSignal("Text"):Connect(ApplyPetFilter)

    getgenv().PopulatePetPenGrid = function()
        if PrioGridBg then 
            PrioGridBg.Visible = false  
            for _, C in ipairs(PrioGridBg:GetChildren()) do if not C:IsA("UILayout") and not C:IsA("UIPadding") then C:Destroy() end end 
        end
        if EggGridBg then 
            EggGridBg.Visible = false  
            for _, C in ipairs(EggGridBg:GetChildren()) do if not C:IsA("UILayout") and not C:IsA("UIPadding") then C:Destroy() end end 
        end
        
        table.clear(PetGridCards)
        local DuskCore = getgenv().DuskCore
        if not DuskCore or not DuskCore.M then return end

         
        local function IsMaxAge(PData)
            local Props = PData.properties or {}
            local Age = tonumber(Props.age) or 0
            local IsMega = (Props.mega_neon == true or Props.mega_neon == 1 or Props.is_mega == true)
             
            return (Age >= 6) or IsMega
        end
        
        local OwnedCounts = {}
        local RawInv = DuskCore.M.ClientData.get("inventory", "Raw")
        if type(RawInv) ~= "table" or not RawInv.pets then RawInv = DuskCore.M.ClientData.get("inventory") end
        
         
        if RawInv and RawInv.pets then
            for uid, PData in pairs(RawInv.pets) do
                local K = PData.kind or PData.id
                if K and not IsMaxAge(PData) then OwnedCounts[K] = (OwnedCounts[K] or 0) + 1 end
            end
        end

         
        local Ipm = DuskCore.M.ClientData.get("idle_progression_manager")
        if Ipm and Ipm.active_pets then
            for uid, PData in pairs(Ipm.active_pets) do
                if PData.item_info then
                    local K = PData.item_info.kind or PData.item_info.id
                    if K and not IsMaxAge(PData.item_info) then OwnedCounts[K] = (OwnedCounts[K] or 0) + 1 end
                end
            end
        end
        
         
        local EqMan = DuskCore.M.ClientData.get("equip_manager")
        if EqMan and EqMan.pets then
            for _, PData in pairs(EqMan.pets) do
                local K = PData.kind or PData.id
                if K and not IsMaxAge(PData) then OwnedCounts[K] = (OwnedCounts[K] or 0) + 1 end
            end
        end
        
        local RenderList = {}
        if getgenv().PetPenViewMode == "Inventory" then
            if RawInv and RawInv.pets then
                for uid, Data in pairs(RawInv.pets) do
                    local kind = Data.kind or Data.id
                    if kind == "practice_dog" or string.find(kind, "starter_egg") or IsMaxAge(Data) then continue end
                    local Db = DuskCore.M.InventoryDB.pets[kind]
                    if Db and not RenderList[kind] then RenderList[kind] = { name = Db.name or kind, uid = uid, db = Db } end
                end
            end
            if Ipm and Ipm.active_pets then
                for uid, PData in pairs(Ipm.active_pets) do
                    if PData.item_info then
                        local kind = PData.item_info.kind or PData.item_info.id
                        if kind == "practice_dog" or string.find(kind, "starter_egg") or IsMaxAge(PData.item_info) then continue end
                        local Db = DuskCore.M.InventoryDB.pets[kind]
                        if Db and not RenderList[kind] then RenderList[kind] = { name = Db.name or kind, uid = uid, db = Db } end
                    end
                end
            end
            if EqMan and EqMan.pets then
                for _, PData in pairs(EqMan.pets) do
                    local kind = PData.kind or PData.id
                    if kind == "practice_dog" or string.find(kind, "starter_egg") or IsMaxAge(PData) then continue end
                    local Db = DuskCore.M.InventoryDB.pets[kind]
                    if Db and not RenderList[kind] then RenderList[kind] = { name = Db.name or kind, uid = PData.unique, db = Db } end
                end
            end
        else
             
            for kind, Db in pairs(DuskCore.M.InventoryDB.pets) do
                if kind == "practice_dog" or string.find(kind, "starter_egg") then continue end
                if Db then RenderList[kind] = { name = Db.name or kind, uid = nil, db = Db } end
            end
        end

        local SortedList = {}
        for kind, Data in pairs(RenderList) do table.insert(SortedList, {kind = kind, data = Data}) end
        table.sort(SortedList, function(A, B) return A.data.name < B.data.name end)

        task.spawn(function()
            for Index, Item in ipairs(SortedList) do
                local kind = Item.kind
                local Data = Item.data

                local Img = Data.db.icon or Data.db.image or Data.db.shop_image or "122697490518955"
                if not string.find(tostring(Img), "rbxassetid") and tonumber(Img) then Img = "rbxassetid://"..img end
                
                local isEgg = Data.db.is_egg
                local TargetParent = isEgg and EggGridBg or PrioGridBg
                local Count = OwnedCounts[kind] or 0

                local Btn = Library.Utils.Make("TextButton", { Size = UDim2.new(1, 0, 1, 0), Text = "", BackgroundTransparency = 0.3, Parent = TargetParent }, { BackgroundColor3 = "Section" })
                Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 8), Parent = Btn})
                local Stroke = Library.Utils.Make("UIStroke", {Thickness = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Parent = Btn}, {Color = "Stroke"})
                Library.Utils.Make("ImageLabel", { Size = UDim2.new(0, 50, 0, 50), Position = UDim2.new(0.5, -25, 0, 8), BackgroundTransparency = 1, Image = Img, Parent = Btn })
                Library.Utils.Make("TextLabel", { Text = Data.name, Size = UDim2.new(1, -4, 0, 15), Position = UDim2.new(0, 2, 1, -20), BackgroundTransparency = 1, Font = Enum.Font.GothamMedium, TextSize = 10, TextWrapped = true, Parent = Btn }, { TextColor3 = "Text" })

                if Count > 1 then
                    local DisplayCount = Count > 99 and "99+" or tostring(Count)
                    local CountLbl = Library.Utils.Make("TextLabel", { Text = "x" .. displayCount, Size = UDim2.new(0, 24, 0, 15), Position = UDim2.new(0, 4, 0, 4), Rotation = -15, BackgroundTransparency = 1, Font = Enum.Font.GothamBlack, TextSize = 12, ZIndex = 4, Parent = Btn }, { TextColor3 = "Accent" })
                    local TxtStroke = Instance.new("UIStroke", CountLbl)
                    TxtStroke.Color = Color3.new(0, 0, 0)
                    TxtStroke.Thickness = 1.5
                end

                local Badge = Library.Utils.Make("Frame", { Size = UDim2.new(0, 20, 0, 20), Position = UDim2.new(1, -25, 0, 5), Visible = false, Parent = Btn })
                Library.Utils.Make("UICorner", {CornerRadius = UDim.new(1, 0), Parent = Badge})
                local BadgeText = Library.Utils.Make("TextLabel", { Text = "1", Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 1, Font = Enum.Font.GothamBold, TextSize = 12, TextColor3 = Color3.new(1,1,1), Parent = Badge })

                table.insert(PetGridCards, { Btn = Btn, Kind = kind, Name = Data.name, Stroke = Stroke, Badge = Badge, BadgeText = BadgeText, Uid = Data.uid, IsEgg = isEgg })

                local BScale = Instance.new("UIScale", Btn)
                Btn.MouseButton1Click:Connect(function()
                    Library.Utils.TBT(BScale, 0.1, {Scale = 0.85}).Completed:Connect(function() Library.Utils.TBT(BScale, 0.15, {Scale = 1}, Enum.EasingStyle.Bounce) end)
                    
                    if getgenv().TargetPetPenMode == "Slot" then
                        local TargetUid = Data.uid
                        if not TargetUid then
                            if RawInv and RawInv.pets then
                                for U, D in pairs(RawInv.pets) do if (D.kind or D.id) == kind then TargetUid = U; break end end
                            end
                        end
                        if not TargetUid then if Library.Notify then Library:Notify("Pet Pen", "You don't own this pet!", 2) end return end

                        local Sf = SlotFrames[getgenv().TargetPetPenSlot]
                        if Sf then
                            Sf.Icon.Image = Img
                            Sf.Plus.Visible = false
                            Sf.Status.Text = string.sub(Data.name, 1, 8)
                            Library.ThemeObjects[Sf.Status] = { TextColor3 = "Accent" }
                            Sf.Status.TextColor3 = Library.CurrentTheme and Library.CurrentTheme.Accent or Color3.new(1,1,1)
                            Sf.CurrentUID = TargetUid
                        end

                        task.spawn(function() pcall(function() DuskCore.API.AddPetAPI:FireServer(TargetUid) end) end)
                        if Library.Notify then Library:Notify("Pet Pen", "Assigned " .. data.name, 2, Img, "rbxassetid://72958619361915") end
                        if isEgg then EggPage:Close() else PriorityPage:Close() end
                    
                    elseif getgenv().TargetPetPenMode == "Priority" then
                        local PrioIndex = table.find(getgenv().PetPenPriority, kind)
                        local Msg = ""
                        if PrioIndex then 
                            table.remove(getgenv().PetPenPriority, PrioIndex)
                            Msg = "Removed from priority: "
                        else 
                            table.insert(getgenv().PetPenPriority, kind) 
                            Msg = "Added to priority: "
                        end
                        if getgenv().SaveConfig then pcall(getgenv().SaveConfig) end
                        SyncPriorityVisuals()
                        if Library.Notify then Library:Notify("Pet Pen", Msg .. data.name, 2, Img, "rbxassetid://72958619361915") end
                    
                    elseif getgenv().TargetPetPenMode == "EggPriority" then
                        local PrioIndex = table.find(getgenv().EggPenPriority, kind)
                        local Msg = ""
                        if PrioIndex then 
                            table.remove(getgenv().EggPenPriority, PrioIndex) 
                            Msg = "Removed from priority: "
                        else 
                            table.insert(getgenv().EggPenPriority, kind) 
                            Msg = "Added to priority: "
                        end
                        if getgenv().SaveConfig then pcall(getgenv().SaveConfig) end
                        SyncPriorityVisuals()
                        if Library.Notify then Library:Notify("Egg Queue", Msg .. data.name, 2, Img, "rbxassetid://72958619361915") end
                    end
                end)

                if Index % 25 == 0 then task.wait() end  
            end
            
            PPSearchInput.Text = ""
            EggSearchInput.Text = ""
            ApplyPetFilter()
            SyncPriorityVisuals()
            
             
            if PrioGridBg then PrioGridBg.Visible = true end
            if EggGridBg then EggGridBg.Visible = true end
        end)
    end

     
    local function CreateAdvancedPPToggle(name, Desc, Flag, Default, Order, Opt)
        Opt = Opt or {}
        local CardHeight = Opt.ViewModes and 85 or 60  
        
        local Card = Library.Utils.Make("Frame", { Size = UDim2.new(1, 0, 0, CardHeight), BackgroundTransparency = 0.3, LayoutOrder = Order, Parent = PPContainer }, { BackgroundColor3 = "Section" })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 8), Parent = Card})
        
         
        local CardStroke = Library.Utils.Make("UIStroke", {Thickness = 1, Parent = Card}, { Color = "Stroke" })
        Card.MouseEnter:Connect(function() Library.Utils.TBT(CardStroke, 0.25, {Color = Library.CurrentTheme.Accent}) end)
        Card.MouseLeave:Connect(function() Library.Utils.TBT(CardStroke, 0.25, {Color = Library.CurrentTheme.Stroke}) end)
        
        local TextWidthOffset = -120
        Library.Utils.Make("TextLabel", { Text = name, Size = UDim2.new(1, TextWidthOffset, 0, 16), Position = UDim2.new(0, 15, 0, 12), BackgroundTransparency = 1, Font = Enum.Font.GothamBold, TextSize = 14, TextXAlignment = Enum.TextXAlignment.Left, Parent = Card }, { TextColor3 = "Text" })
        Library.Utils.Make("TextLabel", { Text = Desc, Size = UDim2.new(1, TextWidthOffset, 0, 14), Position = UDim2.new(0, 15, 0, 32), BackgroundTransparency = 1, Font = Enum.Font.GothamMedium, TextSize = 11, TextXAlignment = Enum.TextXAlignment.Left, Parent = Card }, { TextColor3 = "SubText" })

        local CurrentRightOffset = -15
        local InteractY = Opt.ViewModes and 30 or 0.5  
        
         
        local Sw = Library.Utils.Make("TextButton", { Text = "", Size = UDim2.new(0, 44, 0, 24), AnchorPoint = Vector2.new(1, Opt.ViewModes and 0 or 0.5), Position = UDim2.new(1, CurrentRightOffset, Opt.ViewModes and 0 or 0.5, InteractY), BackgroundTransparency = 1, Parent = Card })
        local TState = Default
        getgenv()[Flag] = TState
        
        local ToggleBg = Library.Utils.Make("Frame", { Size = UDim2.new(1, 0, 1, 0), Parent = Sw }, { BackgroundColor3 = TState and "Accent" or "ToggleOff" })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(1,0), Parent = ToggleBg})
        local TOnP, tOffP = UDim2.new(1, -22, 0.5, -10), UDim2.new(0, 2, 0.5, -10)
        local Kn = Library.Utils.Make("Frame", { Size = UDim2.new(0, 20, 0, 20), Position = TState and TOnP or TOffP, Parent = ToggleBg }, { BackgroundColor3 = "Knob" })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(1,0), Parent = Kn})

        Sw.MouseButton1Click:Connect(function()
            TState = not TState
            getgenv()[Flag] = TState
            Library.ThemeObjects[ToggleBg] = { BackgroundColor3 = TState and "Accent" or "ToggleOff" }
            local TargetColor = TState and (Library.CurrentTheme and Library.CurrentTheme.Accent or Color3.fromRGB(46, 204, 113)) or (Library.CurrentTheme and Library.CurrentTheme.ToggleOff or Color3.fromRGB(55, 55, 60))
            Library.Utils.TBT(ToggleBg, 0.25, {BackgroundColor3 = TargetColor})
            Library.Utils.TBT(Kn, 0.25, {Position = TState and TOnP or TOffP})
            if getgenv().SaveConfig then pcall(getgenv().SaveConfig) end
            
            if TState then
                Library.Utils.ApplyGradient(ToggleBg, Library.CurrentTheme and Library.CurrentTheme.Accent or Color3.fromRGB(46, 204, 113))
            else
                local Grad = ToggleBg:FindFirstChild("DuskShine_Gradient")
                if Grad then Grad:Destroy() end
            end

             
            if Library and type(Library.Notify) == "function" then
                local Msg = TState and "Enabled." or "Disabled."
                Library:Notify(name, Msg, 2, "rbxassetid://14400244301", "rbxassetid://72958619361915")
            end
        end)
        
        CurrentRightOffset = CurrentRightOffset - 44 - 10

         
        if Opt.Gear then
            local GearBtn = Library.Utils.Make("TextButton", { Size = UDim2.new(0, 24, 0, 24), AnchorPoint = Vector2.new(1, Opt.ViewModes and 0 or 0.5), Position = UDim2.new(1, CurrentRightOffset, Opt.ViewModes and 0 or 0.5, InteractY), BackgroundTransparency = 1, Text = "", Parent = Card })
            local GearIcon = Library.Utils.Make("ImageLabel", { Image = "rbxassetid://7734053495", Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 1, Parent = GearBtn }, { ImageColor3 = "SubText" })
            local GScale = Instance.new("UIScale", GearBtn)
            GearBtn.MouseEnter:Connect(function() Library.Utils.TBT(GearIcon, 0.2, {ImageColor3 = Library.CurrentTheme.Accent}) end)
            GearBtn.MouseLeave:Connect(function() Library.Utils.TBT(GearIcon, 0.2, {ImageColor3 = Library.CurrentTheme.SubText}) end)
            GearBtn.MouseButton1Click:Connect(function()
                Library.Utils.TBT(GScale, 0.1, {Scale = 0.85}).Completed:Connect(function() Library.Utils.TBT(GScale, 0.2, {Scale = 1}, Enum.EasingStyle.Bounce) end)
                Opt.Gear()
            end)
            CurrentRightOffset = CurrentRightOffset - 24 - 10
        end

         
        if Opt.ViewModes then
            getgenv().PetPenViewMode = getgenv().PetPenViewMode or "Inventory"
            
            local ViewModeContainer = Library.Utils.Make("Frame", { Size = UDim2.new(0, 140, 0, 24), Position = UDim2.new(0, 15, 0, 52), BackgroundTransparency = 1, Parent = Card })
            Library.Utils.Make("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, HorizontalAlignment = Enum.HorizontalAlignment.Left, Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder, Parent = ViewModeContainer })

            local BtnInv = Library.Utils.Make("TextButton", { Text = "Inv", Size = UDim2.new(0, 50, 1, 0), LayoutOrder = 1, Font = Enum.Font.GothamBold, TextSize = 11, Parent = ViewModeContainer })
            Instance.new("UICorner", BtnInv).CornerRadius = UDim.new(0, 6)
            local StrInv = Library.Utils.Make("UIStroke", {Thickness = 1, Parent = BtnInv})

            local BtnAll = Library.Utils.Make("TextButton", { Text = "All", Size = UDim2.new(0, 50, 1, 0), LayoutOrder = 2, Font = Enum.Font.GothamBold, TextSize = 11, Parent = ViewModeContainer })
            Instance.new("UICorner", BtnAll).CornerRadius = UDim.new(0, 6)
            local StrAll = Library.Utils.Make("UIStroke", {Thickness = 1, Parent = BtnAll})

            local ModeThemeCatcher = Library.Utils.Make("Frame", {Visible = false, Parent = ViewModeContainer}, {BackgroundColor3 = "Accent"})

            local function SyncViewButtons()
                local IsInv = getgenv().PetPenViewMode == "Inventory"
                local ThemeName = Library.CurrentThemeName
                local Theme = Library.CurrentTheme or Library.Themes.Dark
                
                local ActiveTextColor = Color3.new(1, 1, 1)
                if ThemeName == "Light" or ThemeName == "Amethelyst" or ThemeName == "Dark" then
                    ActiveTextColor = Color3.fromRGB(20, 20, 25) 
                end

                Library.ThemeObjects[BtnInv] = nil; Library.ThemeObjects[StrInv] = nil
                Library.ThemeObjects[BtnAll] = nil; Library.ThemeObjects[StrAll] = nil

                local GradInv = BtnInv:FindFirstChild("DuskShine_Gradient")
                local GradAll = BtnAll:FindFirstChild("DuskShine_Gradient")
                if GradInv then GradInv:Destroy() end
                if GradAll then GradAll:Destroy() end

                if IsInv then Library.Utils.ApplyGradient(BtnInv, Theme.Accent) else Library.Utils.ApplyGradient(BtnAll, Theme.Accent) end

                game:GetService("TweenService"):Create(BtnInv, TweenInfo.new(0.2), {
                    BackgroundColor3 = IsInv and Theme.Accent or Theme.Sidebar, TextColor3 = IsInv and ActiveTextColor or Theme.SubText
                }):Play()
                game:GetService("TweenService"):Create(StrInv, TweenInfo.new(0.2), { Color = IsInv and Theme.Accent or Theme.Stroke }):Play()
                
                game:GetService("TweenService"):Create(BtnAll, TweenInfo.new(0.2), {
                    BackgroundColor3 = not IsInv and Theme.Accent or Theme.Sidebar, TextColor3 = not IsInv and ActiveTextColor or Theme.SubText
                }):Play()
                game:GetService("TweenService"):Create(StrAll, TweenInfo.new(0.2), { Color = not IsInv and Theme.Accent or Theme.Stroke }):Play()
            end

            ModeThemeCatcher:GetPropertyChangedSignal("BackgroundColor3"):Connect(SyncViewButtons)
            SyncViewButtons()

            BtnInv.MouseButton1Click:Connect(function() 
                getgenv().PetPenViewMode = "Inventory"; SyncViewButtons(); 
                if getgenv().PopulatePetPenGrid then getgenv().PopulatePetPenGrid() end 
                if getgenv().SaveConfig then pcall(getgenv().SaveConfig) end  
                if Library and type(Library.Notify) == "function" then Library:Notify(name, "View Mode: Inventory", 2, "rbxassetid://14400244301", "rbxassetid://72958619361915") end
            end)

            BtnAll.MouseButton1Click:Connect(function() 
                getgenv().PetPenViewMode = "All"; SyncViewButtons(); 
                if getgenv().PopulatePetPenGrid then getgenv().PopulatePetPenGrid() end 
                if getgenv().SaveConfig then pcall(getgenv().SaveConfig) end  
                if Library and type(Library.Notify) == "function" then Library:Notify(name, "View Mode: All", 2, "rbxassetid://14400244301", "rbxassetid://72958619361915") end
            end)
        end

        return Card
    end
    if Tab.CreateDivider then Tab:CreateDivider({ Text = "Claiming Options", Parent = PPContainer, LayoutOrder = 3 }) end

     
    local function CreatePPToggleWithSlider(name, Desc, Flag, Default, Order, LimitVar, LimitDefault, MinVal, MaxVal, Opt)
        Opt = Opt or {}
        local Card = Library.Utils.Make("Frame", { Size = UDim2.new(1, 0, 0, 90), BackgroundTransparency = 0.3, LayoutOrder = Order, Parent = PPContainer }, { BackgroundColor3 = "Section" })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 8), Parent = Card})
        
        local CardStroke = Library.Utils.Make("UIStroke", {Thickness = 1, Parent = Card}, { Color = "Stroke" })
        Card.MouseEnter:Connect(function() Library.Utils.TBT(CardStroke, 0.25, {Color = Library.CurrentTheme.Accent}) end)
        Card.MouseLeave:Connect(function() Library.Utils.TBT(CardStroke, 0.25, {Color = Library.CurrentTheme.Stroke}) end)
        
        Library.Utils.Make("TextLabel", { Text = name, Size = UDim2.new(1, -70, 0, 16), Position = UDim2.new(0, 15, 0, 12), BackgroundTransparency = 1, Font = Enum.Font.GothamBold, TextSize = 14, TextXAlignment = Enum.TextXAlignment.Left, Parent = Card }, { TextColor3 = "Text" })
        Library.Utils.Make("TextLabel", { Text = Desc, Size = UDim2.new(1, -70, 0, 14), Position = UDim2.new(0, 15, 0, 32), BackgroundTransparency = 1, Font = Enum.Font.GothamMedium, TextSize = 11, TextXAlignment = Enum.TextXAlignment.Left, Parent = Card }, { TextColor3 = "SubText" })

        local Sw = Library.Utils.Make("TextButton", { Text = "", Size = UDim2.new(0, 44, 0, 24), AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -15, 0, 12), BackgroundTransparency = 1, Parent = Card })
        local TState = Default
        getgenv()[Flag] = TState
        
        local ToggleBg = Library.Utils.Make("Frame", { Size = UDim2.new(1, 0, 1, 0), Parent = Sw }, { BackgroundColor3 = TState and "Accent" or "ToggleOff" })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(1,0), Parent = ToggleBg})
        local TOnP, tOffP = UDim2.new(1, -22, 0.5, -10), UDim2.new(0, 2, 0.5, -10)
        local Kn = Library.Utils.Make("Frame", { Size = UDim2.new(0, 20, 0, 20), Position = TState and TOnP or TOffP, Parent = ToggleBg }, { BackgroundColor3 = "Knob" })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(1,0), Parent = Kn})

        Sw.MouseButton1Click:Connect(function()
            TState = not TState
            getgenv()[Flag] = TState
            Library.ThemeObjects[ToggleBg] = { BackgroundColor3 = TState and "Accent" or "ToggleOff" }
            local TargetColor = TState and (Library.CurrentTheme and Library.CurrentTheme.Accent or Color3.fromRGB(46, 204, 113)) or (Library.CurrentTheme and Library.CurrentTheme.ToggleOff or Color3.fromRGB(55, 55, 60))
            Library.Utils.TBT(ToggleBg, 0.25, {BackgroundColor3 = TargetColor})
            Library.Utils.TBT(Kn, 0.25, {Position = TState and TOnP or TOffP})
            if getgenv().SaveConfig then pcall(getgenv().SaveConfig) end

            if TState then
                Library.Utils.ApplyGradient(ToggleBg, Library.CurrentTheme and Library.CurrentTheme.Accent or Color3.fromRGB(46, 204, 113))
            else
                local Grad = ToggleBg:FindFirstChild("DuskShine_Gradient")
                if Grad then Grad:Destroy() end
            end

            if Library and type(Library.Notify) == "function" then
                local Msg = TState and "Enabled." or "Disabled."
                Library:Notify(name, Msg, 2, "rbxassetid://14400244301", "rbxassetid://72958619361915")
            end
        end)

        local Val = getgenv()[LimitVar] or LimitDefault
        Val = math.clamp(Val, MinVal, MaxVal)
        getgenv()[LimitVar] = Val

        local InputBg = Library.Utils.Make("Frame", { Size = UDim2.new(0, 50, 0, 24), AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -15, 0, 55), Parent = Card }, { BackgroundColor3 = "Sidebar" })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 6), Parent = InputBg})
        local InputBgStroke = Library.Utils.Make("UIStroke", {Thickness = 1, Parent = InputBg}, {Color = "Stroke"})
        local InputBox = Library.Utils.Make("TextBox", { Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 1, Text = tostring(Val), Font = Enum.Font.GothamMedium, TextSize = 11, ClearTextOnFocus = false, Parent = InputBg }, { TextColor3 = "Text" })

        local Track = Library.Utils.Make("Frame", { Size = UDim2.new(1, -90, 0, 6), Position = UDim2.new(0, 15, 0, 64), Parent = Card }, { BackgroundColor3 = "Sidebar" })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(1, 0), Parent = Track})
        
        local Pct = (Val - MinVal) / (MaxVal - MinVal)
        local Fill = Library.Utils.Make("Frame", { Size = UDim2.new(Pct, 0, 1, 0), Parent = Track }, { BackgroundColor3 = "Accent" })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(1, 0), Parent = Fill})
        local Trigger = Library.Utils.Make("TextButton", { Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 1, Text = "", Parent = Track })

        local Dragging = false
        local function UpdateSlider(InputObj, RawVal, IsTyping)
            local NewVal = RawVal
            if not NewVal then
                local Pos = math.clamp((InputObj.Position.X - Track.AbsolutePosition.X) / Track.AbsoluteSize.X, 0, 1)
                NewVal = math.floor(MinVal + ((MaxVal - MinVal) * Pos))
            end
            NewVal = math.clamp(NewVal, MinVal, MaxVal)
            local FillPct = (NewVal - MinVal) / (MaxVal - MinVal)
            
            Fill.Size = UDim2.new(FillPct, 0, 1, 0)
            getgenv()[LimitVar] = NewVal
            if not IsTyping then InputBox.Text = tostring(NewVal) end
        end

        InputBox:GetPropertyChangedSignal("Text"):Connect(function()
            local Num = tonumber(InputBox.Text)
            if Num then UpdateSlider(nil, Num, true) end
        end)

        InputBox.FocusLost:Connect(function()
            local Num = tonumber(InputBox.Text)
            if not Num then Num = getgenv()[LimitVar] end
            UpdateSlider(nil, Num, false)
            if getgenv().SaveConfig then pcall(getgenv().SaveConfig) end
        end)

        Trigger.InputBegan:Connect(function(InputObj) 
            if InputObj.UserInputType == Enum.UserInputType.MouseButton1 or InputObj.UserInputType == Enum.UserInputType.Touch then Dragging = true; UpdateSlider(InputObj) end 
