        end

        local function Close()
            if InstantNav.Stack[#InstantNav.Stack] ~= SubPageUI then return end
            table.remove(InstantNav.Stack, #InstantNav.Stack); SubPageUI.Visible = false
            
            if #InstantNav.Stack == 0 then
                 
                for _, Child in ipairs(InstantNav.HiddenRootElements) do if Child then Child.Visible = true end end
                table.clear(InstantNav.HiddenRootElements)
                
                 
                task.spawn(function()
                    task.wait() 
                    Tab.Page.CanvasPosition = InstantNav.SavedCanvasPos
                end)
            else 
                InstantNav.Stack[#InstantNav.Stack].Visible = true 
            end
        end

        CloseBtn.MouseButton1Click:Connect(Close)
        return { Container = Scroll, Open = Open, Close = Close, UI = SubPageUI }
    end

