    local function SyncModeButtons()
        local IsTarget = getgenv().AutoAcceptMode == "Target"
        local ThemeName = Library.CurrentThemeName
        local Theme = Library.CurrentTheme or Library.Themes.Dark
        
        local ActiveTextColor = Color3.fromRGB(20, 20, 25)
        if ThemeName == "Galaxy" then
            ActiveTextColor = Color3.new(1, 1, 1)
        end

         
        Library.ThemeObjects[BtnTarget] = nil
        Library.ThemeObjects[StrTarget] = nil
        Library.ThemeObjects[BtnAll] = nil
        Library.ThemeObjects[StrAll] = nil

         
        if not IsTarget then
            local Grad = BtnTarget:FindFirstChild("DuskShine_Gradient")
            if Grad then Grad:Destroy() end
        else
            local Grad = BtnAll:FindFirstChild("DuskShine_Gradient")
            if Grad then Grad:Destroy() end
        end

         
        Library.Utils.ApplyGradient(IsTarget and BtnTarget or BtnAll, Theme.Accent)

         
        TweenService:Create(BtnTarget, TweenInfo.new(0.2), {
            BackgroundColor3 = IsTarget and Theme.Accent or Theme.Sidebar, 
            TextColor3 = IsTarget and ActiveTextColor or Theme.SubText
        }):Play()
        TweenService:Create(StrTarget, TweenInfo.new(0.2), {
            Color = IsTarget and Theme.Accent or Theme.Stroke
        }):Play()
        
        TweenService:Create(BtnAll, TweenInfo.new(0.2), {
            BackgroundColor3 = not IsTarget and Theme.Accent or Theme.Sidebar, 
            TextColor3 = not IsTarget and ActiveTextColor or Theme.SubText
        }):Play()
        TweenService:Create(StrAll, TweenInfo.new(0.2), {
            Color = not IsTarget and Theme.Accent or Theme.Stroke
        }):Play()
    end

     
    ModeThemeCatcher:GetPropertyChangedSignal("BackgroundColor3"):Connect(SyncModeButtons)
    SyncModeButtons()

