    local function CreateDisableInnerToggle(parent, name, Desc, Flag, Default)
        local Card = Library.Utils.Make("Frame", { Size = UDim2.new(1, 0, 0, 60), Parent = parent }, { BackgroundColor3 = "Section" })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 8), Parent = Card}); Library.Utils.Make("UIStroke", {Thickness = 1, Parent = Card}, { Color = "Stroke" })
        Library.Utils.Make("TextLabel", { Text = name, Size = UDim2.new(1, -70, 0, 16), Position = UDim2.new(0, 15, 0, 12), BackgroundTransparency = 1, Font = Enum.Font.GothamBold, TextSize = 14, TextXAlignment = Enum.TextXAlignment.Left, Parent = Card }, { TextColor3 = "Text" })
        Library.Utils.Make("TextLabel", { Text = Desc, Size = UDim2.new(1, -70, 0, 14), Position = UDim2.new(0, 15, 0, 32), BackgroundTransparency = 1, Font = Enum.Font.GothamMedium, TextSize = 11, TextXAlignment = Enum.TextXAlignment.Left, Parent = Card }, { TextColor3 = "SubText" })

        local Sw = Library.Utils.Make("TextButton", { Text = "", Size = UDim2.new(0, 44, 0, 24), AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -15, 0.5, 0), BackgroundTransparency = 1, Parent = Card })
        getgenv()[Flag] = getgenv()[Flag] or Default
        local State = getgenv()[Flag]
        
        local ToggleBgInner = Library.Utils.Make("Frame", { Size = UDim2.new(1, 0, 1, 0), Parent = Sw }, { BackgroundColor3 = State and "Accent" or "ToggleOff" })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(1,0), Parent = ToggleBgInner})
        local KnobInner = Library.Utils.Make("Frame", { Size = UDim2.new(0, 20, 0, 20), Position = State and DOnP or DOffP, Parent = ToggleBgInner }, { BackgroundColor3 = "Knob" })
        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(1,0), Parent = KnobInner})

        Sw.MouseButton1Click:Connect(function()
            State = not State; getgenv()[Flag] = State
            Library.ThemeObjects[ToggleBgInner] = { BackgroundColor3 = State and "Accent" or "ToggleOff" }
            Library.Utils.TBT(ToggleBgInner, 0.25, {BackgroundColor3 = State and (Library.CurrentTheme.Accent) or (Library.CurrentTheme.ToggleOff)})
            TweenService:Create(KnobInner, TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Position = State and DOnP or DOffP}):Play()
            Library:Notify(name, State and "Disabled." or "Enabled.", 2, "rbxassetid://80493264138470", "rbxassetid://72958619361915")
            if getgenv().SaveConfig then pcall(getgenv().SaveConfig) end

            if State then
                Library.Utils.ApplyGradient(ToggleBgInner, Library.CurrentTheme and Library.CurrentTheme.Accent or Color3.fromRGB(46, 204, 113))
            else
                local Grad = ToggleBgInner:FindFirstChild("DuskShine_Gradient")
                if Grad then Grad:Destroy() end
            end
        end)
    end

