    local function ApplyPlayerFilter()
        local Query = string.lower(POSearchInput.Text)
        for _, Data in ipairs(PlayerCards) do
            if Data.Player then
                local PName = string.lower(tostring(Data.Player.Name))
                local PDisp = Data.Player.DisplayName and string.lower(tostring(Data.Player.DisplayName)) or ""
                
                if Query == "" or string.find(PName, Query, 1, true) or string.find(PDisp, Query, 1, true) then
                    Data.Card.Visible = true
                else
                    Data.Card.Visible = false
                end
            end
        end
        POScroll.CanvasPosition = Vector2.new(0, 0)
    end

    POSearchInput:GetPropertyChangedSignal("Text"):Connect(ApplyPlayerFilter)

    local function GetDistance(TargetPlayer)
        local LChar = LocalPlayer.Character
        local TChar = TargetPlayer.Character
        if not LChar or not LChar:FindFirstChild("HumanoidRootPart") then return "N/A" end
        if not TChar or not TChar:FindFirstChild("HumanoidRootPart") then return "Loading..." end
        local Dist = (LChar.HumanoidRootPart.Position - TChar.HumanoidRootPart.Position).Magnitude
        return math.floor(Dist) .. " studs"
    end

    local function PopulatePlayers()
        for _, C in pairs(POScroll:GetChildren()) do if C:IsA("TextButton") then C:Destroy() end end
        table.clear(PlayerCards)

        for _, P in pairs(Players:GetPlayers()) do
            if P == LocalPlayer then continue end

            local Card = Instance.new("TextButton", POScroll)
            Card.Text = ""; Card.ZIndex = 202
            Card.BackgroundColor3 = Library.CurrentTheme.Section
            Library.ThemeObjects[Card] = { BackgroundColor3 = "Section" }
            Instance.new("UICorner", Card).CornerRadius = UDim.new(0, 10)
            
            local CardStroke = Instance.new("UIStroke", Card)
            CardStroke.Thickness = 1.5
            CardStroke.Color = Library.CurrentTheme.Stroke
            Library.ThemeObjects[CardStroke] = { Color = "Stroke" }

             
