            NameLbl.Text = P.Name; NameLbl.Font = Enum.Font.GothamBold; NameLbl.TextSize = 13; NameLbl.TextXAlignment = Enum.TextXAlignment.Left; NameLbl.ZIndex = 203
            NameLbl.TextColor3 = Library.CurrentTheme.Text
