            local DistLbl = Instance.new("TextLabel", Card)
            DistLbl.Size = UDim2.new(1, -65, 0, 14); DistLbl.Position = UDim2.new(0, 65, 0, 32); DistLbl.BackgroundTransparency = 1
            DistLbl.Text = "Calculating..."; DistLbl.Font = Enum.Font.GothamMedium; DistLbl.TextSize = 11; DistLbl.TextXAlignment = Enum.TextXAlignment.Left; DistLbl.ZIndex = 203
            DistLbl.TextColor3 = Library.CurrentTheme.SubText
            Library.ThemeObjects[DistLbl] = { TextColor3 = "SubText" }

             
            local NearTag = Instance.new("Frame", Card)
            NearTag.Size = UDim2.new(0, 36, 0, 14); NearTag.Position = UDim2.new(1, -8, 0, 8); NearTag.AnchorPoint = Vector2.new(1, 0)
            NearTag.BackgroundColor3 = Color3.fromRGB(46, 204, 113); NearTag.Visible = false; NearTag.ZIndex = 203
            Instance.new("UICorner", NearTag).CornerRadius = UDim.new(0, 4)
            
            local NearTxt = Instance.new("TextLabel", NearTag)
            NearTxt.Size = UDim2.new(1, 0, 1, 0); NearTxt.BackgroundTransparency = 1; NearTxt.Text = "NEAR"
            NearTxt.TextColor3 = Color3.fromRGB(20, 20, 25); NearTxt.Font = Enum.Font.GothamBold; NearTxt.TextSize = 9; NearTxt.ZIndex = 204

             
            local CheckBoxBg = Instance.new("Frame", Card)
            CheckBoxBg.Size = UDim2.new(0, 16, 0, 16); CheckBoxBg.Position = UDim2.new(1, -8, 1, -8); CheckBoxBg.AnchorPoint = Vector2.new(1, 1)
            CheckBoxBg.BackgroundColor3 = Library.CurrentTheme.Background
            Library.ThemeObjects[CheckBoxBg] = { BackgroundColor3 = "Background" }
            CheckBoxBg.ZIndex = 203
            Instance.new("UICorner", CheckBoxBg).CornerRadius = UDim.new(0, 4)
            
            local CheckBoxStroke = Instance.new("UIStroke", CheckBoxBg)
            CheckBoxStroke.Color = Library.CurrentTheme.Stroke
            Library.ThemeObjects[CheckBoxStroke] = { Color = "Stroke" }

            local CheckIcon = Instance.new("ImageLabel", CheckBoxBg)
            CheckIcon.Size = UDim2.new(1, -2, 1, -2); CheckIcon.Position = UDim2.new(0.5, 0, 0.5, 0); CheckIcon.AnchorPoint = Vector2.new(0.5, 0.5)
            CheckIcon.BackgroundTransparency = 1; CheckIcon.Image = "rbxassetid://6031094667"; CheckIcon.ImageColor3 = Color3.fromRGB(46, 204, 113); CheckIcon.ZIndex = 204
            
            local CheckScale = Instance.new("UIScale", CheckIcon)
            CheckScale.Scale = (getgenv().TradeTargetPlayer == P.Name) and 1 or 0
            
            if CheckScale.Scale == 1 then 
                CardStroke.Color = Color3.fromRGB(46, 204, 113)
                CheckBoxStroke.Color = Color3.fromRGB(46, 204, 113)
                Library.ThemeObjects[CardStroke] = nil 
                Library.ThemeObjects[CheckBoxStroke] = nil 
            end

            Card.MouseButton1Click:Connect(function()
                if getgenv().TradeTargetPlayer == P.Name then
                    getgenv().TradeTargetPlayer = ""  
                    if Library.Notify then Library:Notify("Target Removed", "Deselected target player.", 2, "rbxassetid://117259180607823", "rbxassetid://72958619361915") end
                    TweenService:Create(CheckScale, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {Scale = 0}):Play()
                    TweenService:Create(CardStroke, TweenInfo.new(0.2), {Color = Library.CurrentTheme.Stroke}):Play()
                    TweenService:Create(CheckBoxStroke, TweenInfo.new(0.2), {Color = Library.CurrentTheme.Stroke}):Play()
                    
                     
                    Library.ThemeObjects[CardStroke] = { Color = "Stroke" }
                    Library.ThemeObjects[CheckBoxStroke] = { Color = "Stroke" }
                else
                    getgenv().TradeTargetPlayer = P.Name  
                    if Library.Notify then Library:Notify("Target Selected", "Now trading with: " .. p.Name, 2, "rbxassetid://117259180607823", "rbxassetid://72958619361915") end
                    for _, Other in ipairs(PlayerCards) do
                        TweenService:Create(Other.CheckScale, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {Scale = 0}):Play()
                        TweenService:Create(Other.CardStroke, TweenInfo.new(0.2), {Color = Library.CurrentTheme.Stroke}):Play()
                        TweenService:Create(Other.CheckBoxStroke, TweenInfo.new(0.2), {Color = Library.CurrentTheme.Stroke}):Play()
                        
                         
                        Library.ThemeObjects[Other.CardStroke] = { Color = "Stroke" }
                        Library.ThemeObjects[Other.CheckBoxStroke] = { Color = "Stroke" }
                    end
                    TweenService:Create(CheckScale, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1}):Play()
                    TweenService:Create(CardStroke, TweenInfo.new(0.2), {Color = Color3.fromRGB(46, 204, 113)}):Play()
                    TweenService:Create(CheckBoxStroke, TweenInfo.new(0.2), {Color = Color3.fromRGB(46, 204, 113)}):Play()
                    
                     
                    Library.ThemeObjects[CardStroke] = nil
                    Library.ThemeObjects[CheckBoxStroke] = nil
                end
                if getgenv().SaveConfig then pcall(getgenv().SaveConfig) end
            end)
            
            table.insert(PlayerCards, {Card = Card, Player = P, DistLbl = DistLbl, NearTag = NearTag, CheckScale = CheckScale, CardStroke = CardStroke, CheckBoxStroke = CheckBoxStroke})
        end
        ApplyPlayerFilter()
    end

