    local function IsRealItem(Uid, CategoryName, ItemData, Inv)
        if not Inv or not CategoryName or not ItemData then return false end
        if type(Uid) ~= "string" then return false end
        
        local LowerUid = string.lower(Uid)
        if string.find(LowerUid, "elysium") or string.find(LowerUid, "dx%-") then return false end
        
        local IsStandardUUID = string.match(Uid, "^%x%x%x%x%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%x%x%x%x%x%x%x%x$")
        local IsAdoptMeHash = string.match(Uid, "^%d+_%x+$")
        if not (IsStandardUUID or IsAdoptMeHash) then return false end

        if ItemData.newness_order and ItemData.newness_order > 45000 then return false end

        local Props = ItemData.properties or {}
        local Kind = ItemData.kind or ItemData.id
        
        if Props.admin_abuse or Props.trade_lock_expiration or Props.reverted or Props.is_reverted or Props.tradeable_timestamp then return false end

        local DuskCore = getgenv().DuskCore
        if DuskCore and DuskCore.M and DuskCore.M.InventoryDB then
            local DbEntry = DuskCore.M.InventoryDB[CategoryName] and DuskCore.M.InventoryDB[CategoryName][Kind]
            if DbEntry then
                if DbEntry.donatable == false or DbEntry.is_tradeable == false or DbEntry.temporary == true then return false end
            else
                return false
            end
        end
        return true
    end

     
