    UpdateVariantBtns = function(Kind)
        local Vars = nil
        if Kind then Vars = getgenv().TradeFilters.CustomVariants[Kind] end
        
        if type(Vars) ~= "table" then
            Vars = {All = true, NoPot = false, R = false, F = false, N = false, M = false}
        end
        
        local Theme = Library.CurrentTheme or Library.Themes.Dark
        local r, g, b = Theme.Accent.R, Theme.Accent.G, Theme.Accent.B
        local Brightness = (r * 299 + g * 587 + b * 114) / 1000
        local ActiveText = Brightness > 0.5 and Color3.fromRGB(20, 20, 25) or Color3.new(1, 1, 1)
        
        for _, BData in ipairs(VariantBtns) do
            local IsActive = Vars[BData.Id]
            
            if IsActive then
                BData.Btn.BackgroundColor3 = Theme.Accent
                BData.Btn.TextColor3 = ActiveText
                BData.Stroke.Color = Theme.Accent
            else
                BData.Btn.BackgroundColor3 = Theme.Sidebar
                BData.Btn.TextColor3 = Theme.Text
                BData.Stroke.Color = Theme.Stroke
            end
        end
    end

