                GlowGrad.Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, SCol), ColorSequenceKeypoint.new(0.5, ACol), ColorSequenceKeypoint.new(1, SCol) })
                AccentLine.BackgroundColor3 = ACol
                IconState.Image = "rbxassetid://6031094667"; IconState.ImageColor3 = Color3.fromRGB(46, 204, 113); IconState.ImageTransparency = 0
            else
