        local function UpdateState(NewState)
            IsSelected = NewState
            OuterGlow.BackgroundTransparency = IsSelected and 0 or 1
            AccentLine.BackgroundTransparency = IsSelected and 0 or 1
            if IsSelected then GradTween:Play() else GradTween:Pause(); GlowGrad.Offset = Vector2.new(-1, 0) end
            UpdateCardVisuals()
        end

        local CScale = Instance.new("UIScale", Card)
