            Library.Utils.TBT(CScale, 0.1, {Scale = 0.85}).Completed:Connect(function() Library.Utils.TBT(CScale, 0.15, {Scale = 1}, Enum.EasingStyle.Bounce) end)
            local NewActive = OnClickCallback(Kind, PImg, Item.name, Count, UpdateState)
            UpdateState(NewActive)
        end)
        
        return OuterGlow, UpdateState
    end

     
    local CustomLazyLoad = { IsLoading = false, RenderedCount = 0, ChunkSize = 50, List = {}, Connection = nil }
    local CustomCardsCache = {}
    local CustomRenderTicket = 0

    RenderCustomGrid = function()
        CustomRenderTicket = CustomRenderTicket + 1
        local CurrentTicket = CustomRenderTicket

        local DuskCore = getgenv().DuskCore
        if not DuskCore or not DuskCore.M then return end
        
        local Inv = DuskCore.M.ClientData.get("inventory")
        local DbCat = DuskCore.M.InventoryDB[SelectedCat] or {}
        
        local OwnedCounts = {}
        if Inv and Inv[SelectedCat] then
            for Uid, ItemData in pairs(Inv[SelectedCat]) do
                 
                if IsRealItem(Uid, SelectedCat, ItemData, Inv) then
                    local Kind = ItemData.id or ItemData.kind
                    OwnedCounts[Kind] = (OwnedCounts[Kind] or 0) + 1
                end
            end
        end
        
        local RenderList = {}
        local Q = string.lower(getgenv().CustomSearchQuery)

        if getgenv().CustomShowAll then
             
            for Kind, Db in pairs(DbCat) do
                if Db.donatable == false or Db.is_tradeable == false or Db.temporary then continue end
                local Count = OwnedCounts[Kind] or 0
                local name = Db.name or Kind
                if Q ~= "" and not string.find(string.lower(name), Q, 1, true) then continue end
                table.insert(RenderList, {kind = Kind, db = Db, count = Count, name = name})
            end
        else
             
            for Kind, Count in pairs(OwnedCounts) do
                local Db = DbCat[Kind] or {}
                local name = Db.name or Kind
                if Q ~= "" and not string.find(string.lower(name), Q, 1, true) then continue end
                table.insert(RenderList, {kind = Kind, db = Db, count = Count, name = name})
            end
        end
        
        table.sort(RenderList, function(A, b) return A.name < b.name end)

        CustomLazyLoad.List = RenderList
        CustomLazyLoad.RenderedCount = 0
        CustomLazyLoad.IsLoading = false

        for _, Cache in pairs(CustomCardsCache) do Cache.InUse = false; Cache.UI.Visible = false end

        local function LoadNextChunk()
            if CustomLazyLoad.IsLoading then return end
            if CustomLazyLoad.RenderedCount >= #CustomLazyLoad.List then return end
            if CustomRenderTicket ~= CurrentTicket then return end

            CustomLazyLoad.IsLoading = true
            local StartIdx = CustomLazyLoad.RenderedCount + 1
            local EndIdx = math.min(StartIdx + CustomLazyLoad.ChunkSize - 1, #CustomLazyLoad.List)
            local FrameTimer = os.clock()

            for I = StartIdx, EndIdx do
                if CustomRenderTicket ~= CurrentTicket then break end
                local Item = CustomLazyLoad.List[I]
                local Kind = Item.kind
                
                local Limits = getgenv().TradeFilters.CustomLimits
                local IsSelected = (Limits[Kind] ~= nil and Limits[Kind] > 0)

                if CustomCardsCache[Kind] then
                    local Cache = CustomCardsCache[Kind]
                    Cache.InUse = true; Cache.UI.Visible = true; Cache.UI.LayoutOrder = I
                    Cache.Update(IsSelected)
                else
                    local Ui, updateFunc = CreateCustomTradeCard(ItemsScroll, Item, IsSelected, function(ClickedKind, PImg, IName, Count, UpdateRef)
                        ActiveItem = { kind = ClickedKind, name = IName, max = Count, img = PImg, updateFunc = UpdateRef }
                        InspIcon.Image = PImg
                        InspTitle.Text = IName .. " (Max: " .. count .. ")"
                        UpdateVariantBtns(ClickedKind)
                        
                        local WasSelected = (Limits[ClickedKind] ~= nil and Limits[ClickedKind] > 0)
                        if not WasSelected then
                            Limits[ClickedKind] = (Count > 0) and Count or 1
                            LimitInput.Text = tostring(Limits[ClickedKind])
                        else
                            Limits[ClickedKind] = nil
                            LimitInput.Text = "0"
                        end
                        
                        if getgenv().SaveConfig then pcall(getgenv().SaveConfig) end
                        return not WasSelected
                    end)
                    Ui.LayoutOrder = I
                    CustomCardsCache[Kind] = { UI = Ui, Update = UpdateFunc, InUse = true }
                end

                if os.clock() - FrameTimer > 0.012 then task.wait(); frameTimer = os.clock() end
            end
            CustomLazyLoad.RenderedCount = EndIdx
            CustomLazyLoad.IsLoading = false
        end

        task.spawn(LoadNextChunk)

        if CustomLazyLoad.Connection then CustomLazyLoad.Connection:Disconnect() end
        CustomLazyLoad.Connection = ItemsScroll:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
            if ItemsScroll.CanvasPosition.Y + ItemsScroll.AbsoluteWindowSize.Y >= ItemsScroll.AbsoluteCanvasSize.Y - 100 then
                task.spawn(LoadNextChunk)
            end
        end)
    end

    local function RenderCats()
        for _, C in ipairs(CatsScroll:GetChildren()) do if C:IsA("TextButton") then C:Destroy() end end
        for _, Cat in ipairs(CatList) do
            local btn = Library.Utils.Make("TextButton", { Size = UDim2.new(1, 0, 0, 30), Text = Cat.name, Font = Enum.Font.GothamBold, TextSize = 11, Parent = CatsScroll }, { BackgroundColor3 = (SelectedCat == Cat.id) and "Accent" or "Sidebar", TextColor3 = (SelectedCat == Cat.id) and "Background" or "Text" })
            Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 6), Parent = btn})
            btn.MouseButton1Click:Connect(function()
                SelectedCat = Cat.id
                
                 
                if VariantsContainer then
                    VariantsContainer.Visible = (SelectedCat == "pets")
                end
                
                RenderCats()
                RenderCustomGrid()
            end)
        end
    end

