        getgenv().TradeFilters.CustomLimits[ActiveItem.kind] = (Num > 0) and Num or nil
        LimitInput.Text = tostring(Num)
        
        if ActiveItem.updateFunc then ActiveItem.updateFunc(Num > 0) end
        if getgenv().SaveConfig then pcall(getgenv().SaveConfig) end
    end)

     
