    RenderSDropdown = function()
        for _, C in pairs(DropList:GetChildren()) do if C:IsA("TextButton") then C:Destroy() end end
        for _, It in ipairs(CatItems) do
            local IsSel = false
            for _, V in pairs(getgenv().TradeCategory) do if V == It.Value then IsSel = true break end end
            
            local Opt = Library.Utils.Make("TextButton", { Size = UDim2.new(1, 0, 0, 30), BackgroundTransparency = 1, Text = "      " .. it.Name, Font = Enum.Font.GothamMedium, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left, AutoButtonColor = false, Parent = DropList }, { BackgroundColor3 = "Section" })
            local OptScale = Instance.new("UIScale", Opt)
            
            if IsSel then Library.ThemeObjects[Opt] = { TextColor3 = "Accent" }; Opt.TextColor3 = Library.CurrentTheme.Accent else Library.ThemeObjects[Opt] = { TextColor3 = "SubText" }; Opt.TextColor3 = Library.CurrentTheme.SubText end
            local Check = Library.Utils.Make("ImageLabel", { Size = UDim2.new(0, 16, 0, 16), Position = UDim2.new(1, -25, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5), BackgroundTransparency = 1, Image = "rbxassetid://6031094667", Visible = IsSel, Parent = Opt })
            if IsSel then Library.ThemeObjects[Check] = { ImageColor3 = "Accent" }; Check.ImageColor3 = Library.CurrentTheme.Accent end

            Opt.MouseEnter:Connect(function() Opt.ZIndex = 5; Check.ZIndex = 5; TweenService:Create(OptScale, TweenInfo.new(0.2, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1.03}):Play(); TweenService:Create(Opt, TweenInfo.new(0.2), {BackgroundTransparency = 0.8}):Play() end)
            Opt.MouseLeave:Connect(function() Opt.ZIndex = 1; Check.ZIndex = 1; TweenService:Create(OptScale, TweenInfo.new(0.2), {Scale = 1}):Play(); TweenService:Create(Opt, TweenInfo.new(0.2), {BackgroundTransparency = 1}):Play() end)
            Opt.MouseButton1Down:Connect(function() TweenService:Create(OptScale, TweenInfo.new(0.1), {Scale = 0.98}):Play() end)
            Opt.MouseButton1Up:Connect(function() TweenService:Create(OptScale, TweenInfo.new(0.2, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1.02}):Play() end)

            Opt.MouseButton1Click:Connect(function()
                ToggleCategory(It.Value, not IsSel)
                if getgenv().SaveConfig then pcall(getgenv().SaveConfig) end
                UpdateSimpleDisplay(); RenderSDropdown()
            end)
        end
    end

    local IsSDropOpen = false
