        if IsSDropOpen then
            local T = TweenService:Create(DropListContainer, TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Size = UDim2.new(1, 0, 0, TargetHeight)})
            T:Play(); T.Completed:Connect(function() if IsSDropOpen then DropListContainer.ClipsDescendants = false end end)
        else
            DropListContainer.ClipsDescendants = true
            TweenService:Create(DropListContainer, TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Size = UDim2.new(1, 0, 0, TargetHeight)}):Play()
        end
    end

