    local function PopulateBlacklist()
        for _, Child in ipairs(BLGridContainer:GetChildren()) do if Child:IsA("TextButton") then Child:Destroy() end end
        table.clear(BlCards)
        
        local DuskCore = getgenv().DuskCore
        if not DuskCore or not DuskCore.M or not DuskCore.M.InventoryDB then return end
        
        local DbPets = DuskCore.M.InventoryDB.pets
        local ItemsToRender = {}

        if getgenv().ShowAllADMPets then
            for Kind, Db in pairs(DbPets) do table.insert(ItemsToRender, { key = Kind, kind = Kind, name = Db.name or Kind }) end
        else
            local Inv = DuskCore.M.ClientData.get("inventory")
            if Inv and Inv.pets then
                for Uid, PetData in pairs(Inv.pets) do
                    local Kind = PetData.kind or PetData.id
                    local Db = DbPets[Kind] or {}
                    local Props = PetData.properties or {}
                    
                    local BaseName = Db.name or Kind
                    local RpName = Props.rp_name
                    local displayName = (RpName and RpName ~= "") and ('"'..rpName..'" ('..baseName..')') or BaseName
                    
                    local Prefix = ""
                    if Props.mega_neon or Props.is_mega then Prefix = "M " elseif Props.neon or Props.is_neon then Prefix = "N " end
                    local f = Props.flyable or Props.is_flyable
                    local r = Props.rideable or Props.is_rideable
                    if f and r then Prefix = Prefix .. "FR " elseif f then Prefix = Prefix .. "F " elseif r then Prefix = Prefix .. "R " end
                    
                    table.insert(ItemsToRender, { key = Uid, kind = Kind, name = Prefix .. displayName })
                end
            end
        end

        for _, Item in ipairs(ItemsToRender) do
            local IsBlocked = getgenv().TradeBlacklist[Item.key] == true
            local Db = DbPets[Item.kind] or {}
            
             
             
            local Card = Library.Utils.Make("TextButton", { Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 0.3, Text = "", AutoButtonColor = false, Parent = BLGridContainer }, { BackgroundColor3 = "Section" })
            Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 8), Parent = Card})
            local CardScale = Instance.new("UIScale", Card)
            
             
            local Stroke = Library.Utils.Make("UIStroke", {Thickness = 1.5, ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Parent = Card})
            if IsBlocked then
                Stroke.Color = Color3.fromRGB(255, 75, 75)
            else
                Stroke.Color = Library.CurrentTheme.Stroke
                Library.ThemeObjects[Stroke] = { Color = "Stroke" }  
            end
            
            local PImg = Db.icon or Db.image or Db.shop_image or "13793170713"
            if not string.find(tostring(PImg), "rbxassetid") and tonumber(PImg) then PImg = "rbxassetid://"..pImg end
            
             
            Library.Utils.Make("ImageLabel", { Size = UDim2.new(0, 45, 0, 45), Position = UDim2.new(0, 8, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5), BackgroundTransparency = 1, ScaleType = Enum.ScaleType.Fit, Image = PImg, Parent = Card })
            
             
            Library.Utils.Make("TextLabel", { Size = UDim2.new(1, -135, 0, 28), Position = UDim2.new(0, 60, 0, 8), BackgroundTransparency = 1, Text = Item.name, Font = Enum.Font.GothamBold, TextSize = 11, TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top, TextWrapped = true, Parent = Card }, { TextColor3 = "Text" })
            
             
             
             
            local ActiveColor = IsBlocked and Color3.fromRGB(255, 75, 75) or Color3.fromRGB(46, 204, 113)
            
             
            local StatusDot = Library.Utils.Make("Frame", { Size = UDim2.new(0, 8, 0, 8), Position = UDim2.new(1, -12, 0, 16), AnchorPoint = Vector2.new(1, 0.5), BackgroundColor3 = ActiveColor, Parent = Card })
            Library.Utils.Make("UICorner", {CornerRadius = UDim.new(1, 0), Parent = StatusDot})
            
            local DotGlow = Library.Utils.Make("UIStroke", {Thickness = 1, Transparency = 0.5, Color = ActiveColor, Parent = StatusDot})
            local PulseAnim = TweenService:Create(DotGlow, TweenInfo.new(1.2, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), {Thickness = 4, Transparency = 0.9})
            PulseAnim:Play()
            
             
            local StatusLbl = Library.Utils.Make("TextLabel", { Size = UDim2.new(0, 60, 0, 14), Position = UDim2.new(1, -26, 0, 16), AnchorPoint = Vector2.new(1, 0.5), BackgroundTransparency = 1, Text = IsBlocked and "blocked" or "allowed", Font = Enum.Font.Gotham, TextSize = 11, TextXAlignment = Enum.TextXAlignment.Right, TextColor3 = ActiveColor, Parent = Card })

             
             
             
            Card.MouseEnter:Connect(function()
                TweenService:Create(CardScale, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1.03}):Play()
                TweenService:Create(Card, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Rotation = 1.5}):Play()
            end)
            Card.MouseLeave:Connect(function()
                TweenService:Create(CardScale, TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Scale = 1}):Play()
                TweenService:Create(Card, TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Rotation = 0}):Play()
            end)
            Card.MouseButton1Down:Connect(function()
                TweenService:Create(CardScale, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Scale = 0.96}):Play()
            end)
            Card.MouseButton1Up:Connect(function()
                TweenService:Create(CardScale, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1.03}):Play()
            end)

            Card.MouseButton1Click:Connect(function()
                getgenv().TradeBlacklist[Item.key] = not getgenv().TradeBlacklist[Item.key]
                local Blocked = getgenv().TradeBlacklist[Item.key]
                local NewColor = Blocked and Color3.fromRGB(255, 75, 75) or Color3.fromRGB(46, 204, 113)
                StatusLbl.Text = Blocked and "blocked" or "allowed"
                if Library.Notify then Library:Notify("Pet Blacklist", (Blocked and "Blocked: " or "Allowed: ") .. item.name, 2, PImg, "rbxassetid://72958619361915") end
                
                TweenService:Create(StatusLbl, TweenInfo.new(0.2), {TextColor3 = NewColor}):Play()
                TweenService:Create(StatusDot, TweenInfo.new(0.2), {BackgroundColor3 = NewColor}):Play()
                TweenService:Create(DotGlow, TweenInfo.new(0.2), {Color = NewColor}):Play()
                
                if Blocked then
                     
                    Library.ThemeObjects[Stroke] = nil
                    TweenService:Create(Stroke, TweenInfo.new(0.2), {Color = Color3.fromRGB(255, 75, 75)}):Play()
                else
                     
                    Library.ThemeObjects[Stroke] = { Color = "Stroke" }
                    TweenService:Create(Stroke, TweenInfo.new(0.2), {Color = Library.CurrentTheme.Stroke}):Play()
                end
                
                if getgenv().SaveConfig then pcall(getgenv().SaveConfig) end
            end)
            
            table.insert(BlCards, { Card = Card, Name = Item.name })
        end
    end

     
