    local function SyncValButtons()
        local CurrentVal = getgenv().TradeValueType
        local ThemeName = Library.CurrentThemeName
        local Theme = Library.CurrentTheme or Library.Themes.Dark
        
        local ActiveTextColor = Color3.fromRGB(20, 20, 25)
