            Library.ThemeObjects[BData.Btn] = nil
            Library.ThemeObjects[BData.Str] = nil
            
            local Grad = BData.Btn:FindFirstChild("DuskShine_Gradient")
            if Grad then Grad:Destroy() end

            if IsSel then Library.Utils.ApplyGradient(BData.Btn, Theme.Accent) end

            TweenService:Create(BData.Btn, TweenInfo.new(0.2), {
                BackgroundColor3 = IsSel and Theme.Accent or Theme.Sidebar, 
                TextColor3 = IsSel and ActiveTextColor or Theme.SubText
            }):Play()
            
            TweenService:Create(BData.Str, TweenInfo.new(0.2), {
                Color = IsSel and Theme.Accent or Theme.Stroke
            }):Play()
        end
    end

