    local function ForceCleanAdoptUI()
        local Pg = LocalPlayer:FindFirstChild("PlayerGui")
        local TradeApp = Pg and Pg:FindFirstChild("TradeApp")
        local Body = TradeApp and TradeApp:FindFirstChild("Frame") and TradeApp.Frame:FindFirstChild("NegotiationFrame") and TradeApp.Frame.NegotiationFrame:FindFirstChild("Body")
        
        if Body then
            local TradeIcon = Body:FindFirstChild("TradeIcon")
            if TradeIcon then
                 
                TradeIcon.ImageColor3 = Color3.fromRGB(35, 35, 35)
                
                if TradeIcon:FindFirstChild("DuskGrad") then TradeIcon.DuskGrad:Destroy() end
                if TradeIcon:FindFirstChild("DuskTradeInject") then TradeIcon.DuskTradeInject:Destroy() end
                if TradeIcon:FindFirstChild("DuskIconStroke") then TradeIcon.DuskIconStroke:Destroy() end
            end
            
            for _, GridName in ipairs({"MyOffer", "PartnerOffer"}) do
                local Grid = Body:FindFirstChild(GridName)
                local SlotsFolder = Grid and Grid:FindFirstChild("Slots")
                if SlotsFolder then
                    for _, Slot in ipairs(SlotsFolder:GetChildren()) do
                        if Slot:FindFirstChild("DuskSlotVal") then Slot.DuskSlotVal:Destroy() end
                    end
                end
            end
        end
        
         
        if CalcGui then
            if CalcGui:FindFirstChild("MySlotsOverlay") then CalcGui.MySlotsOverlay:Destroy() end
            if CalcGui:FindFirstChild("TheirSlotsOverlay") then CalcGui.TheirSlotsOverlay:Destroy() end
        end
    end

    getgenv().DuskTradeUI_Destroy = function()
        if CalcGui then CalcGui:Destroy() end
        getgenv().TradeCalcUI_Update = nil  
        ForceCleanAdoptUI()
    end

