        Library.Utils.Make("UICorner", {CornerRadius = UDim.new(0, 8), Parent = Panel})
        local Stroke = Library.Utils.Make("UIStroke", {Thickness = 1.5, Transparency = 1, Parent = Panel})
        if Library.CurrentTheme then Stroke.Color = Library.CurrentTheme.Accent end

        local Title = Library.Utils.Make("TextLabel", {
            Size = UDim2.new(1, 0, 0, 30), Position = UDim2.new(0, 0, 0, 5), BackgroundTransparency = 1,
            Text = TitleText, Font = Enum.Font.GothamBold, TextSize = 14, 
