    local MyPanel, MyList, MyStroke, MyTitle = CreateDemandPanel("Your Offer")
    local TheirPanel, TheirList, TheirStroke, TheirTitle = CreateDemandPanel("Their Offer")
    local PanelsVisible = false

    local function ApplySlotValues(OfferGrid, ListData)
        if not OfferGrid then return end
        
        local SlotsContainer = OfferGrid:FindFirstChild("Slots")
        if not SlotsContainer then return end

        local Slots = {}
        for _, V in ipairs(SlotsContainer:GetChildren()) do
             
            if V:IsA("GuiObject") and V.Name:match("^Slot%d+") then
                table.insert(Slots, V)
            end
        end

         
        table.sort(Slots, function(A, b)
            local NumA = tonumber(A.Name:match("%d+")) or 0
            local NumB = tonumber(b.Name:match("%d+")) or 0
            return NumA < NumB
        end)

        for I, Slot in ipairs(Slots) do
            local Inj = Slot:FindFirstChild("DuskSlotVal")
            
             
            if type(ListData) == "table" and ListData[I] then
                local ValToShow = tonumber(ListData[I].val) or 0
                
                if not Inj then
                    Inj = Instance.new("TextLabel")
                    Inj.Name = "DuskSlotVal"
                    Inj.Size = UDim2.new(1, 0, 1, 0)
                    Inj.BackgroundTransparency = 1
                    Inj.Font = Enum.Font.GothamBlack
                    Inj.TextSize = 13
                    Inj.TextColor3 = Color3.fromRGB(255, 215, 0)
                    
                     
                    Inj.TextXAlignment = Enum.TextXAlignment.Center
                    Inj.TextYAlignment = Enum.TextYAlignment.Bottom
                    local Pad = Instance.new("UIPadding", Inj)
                    Pad.PaddingBottom = UDim.new(0, 4)
                    
                    local stroke = Instance.new("UIStroke", Inj)
                    stroke.Thickness = 1.5
                    
                    Inj.ZIndex = 50  
                    Inj.Parent = Slot
                end
                
                local FormattedVal = string.format("%.4f", ValToShow):gsub("%.?0+$", "")
                if FormattedVal == "" then FormattedVal = "0" end
                Inj.Text = FormattedVal
                Inj.Visible = true
            elseif Inj then
                Inj.Visible = false
            end
        end
    end

    getgenv().TradeCalcUI_Update = function(IsVisible, MyVal, TheirVal, MyDem, TheirDem, myList, theirList)
        local Pg = LocalPlayer:FindFirstChild("PlayerGui")
        local TradeApp = Pg and Pg:FindFirstChild("TradeApp")
        local MainFrame = TradeApp and TradeApp:FindFirstChild("Frame")
        
         
        if not IsVisible or not MainFrame then
            ForceCleanAdoptUI()
            if PanelsVisible then
                PanelsVisible = false
                for _, Obj in pairs({MyPanel, TheirPanel}) do Library.Utils.TBT(Obj, 0.3, {BackgroundTransparency = 1}) end
                for _, Obj in pairs({MyList, TheirList, MyTitle, TheirTitle}) do Library.Utils.TBT(Obj, 0.3, {TextTransparency = 1}) end
                for _, Obj in pairs({MyStroke, TheirStroke}) do Library.Utils.TBT(Obj, 0.3, {Transparency = 1}) end
                
                task.delay(0.3, function()
                    if not PanelsVisible then MyPanel.Visible = false; TheirPanel.Visible = false end
                end)
            end
            
             
            local Body = MainFrame and MainFrame:FindFirstChild("NegotiationFrame") and MainFrame.NegotiationFrame:FindFirstChild("Body")
            local Body = MainFrame:FindFirstChild("NegotiationFrame") and MainFrame.NegotiationFrame:FindFirstChild("Body")
            if Body then
                 
                ApplySlotValues(Body:FindFirstChild("MyOffer"), myList, true)
                ApplySlotValues(Body:FindFirstChild("PartnerOffer"), theirList, false)
                local TradeIcon = Body:FindFirstChild("TradeIcon")
                if TradeIcon then
                    TradeIcon.ImageColor3 = Color3.fromRGB(255, 255, 255)  
                    if TradeIcon:FindFirstChild("DuskGrad") then TradeIcon.DuskGrad:Destroy() end
                    if TradeIcon:FindFirstChild("DuskTradeInject") then TradeIcon.DuskTradeInject:Destroy() end
                end
                
                 
                for _, OfferGrid in ipairs({Body:FindFirstChild("MyOffer"), Body:FindFirstChild("PartnerOffer")}) do
                    if OfferGrid then
                        for _, Slot in ipairs(OfferGrid:GetChildren()) do
                            if Slot:FindFirstChild("DuskSlotVal") then Slot.DuskSlotVal.Visible = false end
                        end
                    end
                end
            end
            return
        end

        local Profit = (TheirVal or 0) - (MyVal or 0)
        local Prefix = Profit > 0 and "+" or ""
        
        local PColor = Color3.fromRGB(255, 170, 0); local PLetter = "F"
        if Profit >= 0.01 then PColor = Color3.fromRGB(46, 204, 113); pLetter = "W"
        elseif Profit <= -0.01 then PColor = Color3.fromRGB(255, 60, 60); pLetter = "L" end

         
        local MyStrList, theirStrList = {}, {}
        if type(myList) == "table" then for _, V in ipairs(myList) do table.insert(MyStrList, V.str or V) end end
        if type(theirList) == "table" then for _, V in ipairs(theirList) do table.insert(TheirStrList, V.str or V) end end
        local IsAMVGG = getgenv().TradeValueType == "AMVGG" or getgenv().TradeValueType == "AMVGG (Beta)"
        
        if getgenv().ShowTradeDemands and IsAMVGG then
            if not PanelsVisible then
                PanelsVisible = true
                MyPanel.Visible = true; TheirPanel.Visible = true
                for _, Obj in pairs({MyPanel, TheirPanel}) do Library.Utils.TBT(Obj, 0.4, {BackgroundTransparency = 0.4}) end
                for _, Obj in pairs({MyList, TheirList, MyTitle, TheirTitle}) do Library.Utils.TBT(Obj, 0.4, {TextTransparency = 0}) end
                for _, Obj in pairs({MyStroke, TheirStroke}) do Library.Utils.TBT(Obj, 0.4, {Transparency = 0}) end
            end

            MyList.Text = table.concat(MyStrList, "\n")
            TheirList.Text = table.concat(TheirStrList, "\n")
            
             
            local NegFrame = MainFrame:FindFirstChild("NegotiationFrame")
            if NegFrame then
                local AbsPos, absSize = NegFrame.AbsolutePosition, NegFrame.AbsoluteSize
                local PanelWidth = 180
                
                 
                local Inset = game:GetService("GuiService"):GetGuiInset()
                local TrueCenterY = AbsPos.Y + Inset.Y + (AbsSize.Y / 2)
                
                 
                MyPanel.AnchorPoint = Vector2.new(1, 0.5)
                MyPanel.Size = UDim2.new(0, PanelWidth, 0, AbsSize.Y)
                MyPanel.Position = UDim2.new(0, AbsPos.X - 10, 0, TrueCenterY)
                
                 
                TheirPanel.AnchorPoint = Vector2.new(0, 0.5)
                TheirPanel.Size = UDim2.new(0, PanelWidth, 0, AbsSize.Y)
                TheirPanel.Position = UDim2.new(0, AbsPos.X + AbsSize.X + 10, 0, TrueCenterY)
            end
            
            if Library.CurrentTheme then
                MyStroke.Color = Library.CurrentTheme.Accent
                TheirStroke.Color = Library.CurrentTheme.Accent
            end
        else
            PanelsVisible = false
            MyPanel.Visible = false; TheirPanel.Visible = false
        end

        local Body = MainFrame:FindFirstChild("NegotiationFrame") and MainFrame.NegotiationFrame:FindFirstChild("Body")
        if Body then
             
            ApplySlotValues(Body:FindFirstChild("MyOffer"), myList)
            ApplySlotValues(Body:FindFirstChild("PartnerOffer"), theirList)

            local TradeIcon = Body:FindFirstChild("TradeIcon")
            if TradeIcon then
                TradeIcon.ImageColor3 = Color3.new(1, 1, 1) 
                
                local Grad = TradeIcon:FindFirstChild("DuskGrad")
                if not Grad then Grad = Instance.new("UIGradient", TradeIcon); Grad.Name = "DuskGrad"; Grad.Rotation = 90 end
                local H, S, v = PColor:ToHSV()
                local DarkColor = Color3.fromHSV(H, S, math.clamp(V - 0.4, 0, 1))
                Grad.Color = ColorSequence.new({ColorSequenceKeypoint.new(0, PColor), ColorSequenceKeypoint.new(1, DarkColor)})
                
                 
                if TradeIcon:FindFirstChild("DuskIconStroke") then TradeIcon.DuskIconStroke:Destroy() end
                
                local ProfitLbl = TradeIcon:FindFirstChild("DuskTradeInject")
                if not ProfitLbl then
                    ProfitLbl = Library.Utils.Make("TextLabel", {
                        Name = "DuskTradeInject", Size = UDim2.new(2, 0, 0, 40),
                        Position = UDim2.new(0.5, 0, 0, -45), AnchorPoint = Vector2.new(0.5, 1),
                        BackgroundTransparency = 1, Font = Enum.Font.GothamBold, TextSize = 22, Parent = TradeIcon
                    })
                    
                     
                    local TextStroke = Instance.new("UIStroke", ProfitLbl)
                    TextStroke.Color = Color3.new(0, 0, 0)
                    TextStroke.Thickness = 2.5
                end
                 
                local FormattedProfit = string.format("%.4f", Profit):gsub("%.?0+$", "")
                if FormattedProfit == "" then FormattedProfit = "0" end
                
                ProfitLbl.Text = string.format("%s\n%s%s", PLetter, Prefix, FormattedProfit)
                ProfitLbl.TextColor3 = PColor
            end
        end
    end

    local LicenseBtn = Library.Utils.Make("TextButton", {
        Size = UDim2.new(1, 0, 0, 45),
        BackgroundTransparency = 0.3,
        Text = "📜 Get Trade License",
        Font = Enum.Font.GothamBold,
