    LicenseBtn.MouseLeave:Connect(function() Library.Utils.TBT(LicStroke, 0.25, {Color = Library.CurrentTheme.Stroke}) end)
    
    LicenseBtn.MouseButton1Click:Connect(function()
        if getgenv().SetStatusVisual and getgenv().TransferStatusLbl then
            getgenv().TransferStatusLbl.Text = "Status: Getting trade license..."
            getgenv().TransferStatusLbl.TextColor3 = Color3.fromRGB(255, 255, 255)
            getgenv().SetStatusVisual(true)
        end

        task.spawn(function()
            pcall(function()
                local Rs = game:GetService("ReplicatedStorage")
                if Rs.API:FindFirstChild("TradeAPI/BeginQuiz") then
                    Rs.API["TradeAPI/BeginQuiz"]:InvokeServer()
                    for I = 1, 3 do
                        Rs.API["TradeAPI/AnswerQuizQuestion"]:InvokeServer(true)
                    end
                end
            end)
            
             
            task.wait(1)
            if getgenv().SetStatusVisual and getgenv().TransferStatusLbl then
                getgenv().TransferStatusLbl.Text = "Status: Idle"
                getgenv().TransferStatusLbl.TextColor3 = Color3.fromRGB(150, 150, 160)
                getgenv().SetStatusVisual(false)
            end
        end)
        
        if real_print then real_print("[D&S] U got trade license!") end
        if Library.Notify then 
            Library:Notify("License Acquired!", "You successfully passed the quiz and got the Trade License.", 4, "rbxassetid://17829956110", "rbxassetid://72958619361915") 
        end
    end)
end

return Module]==],
}

 
