		}

		local V64, v65 = V19(DuskDomain .. "/raw/dusk_logic_bundle_raw?nocache=" .. tostring(tick()))

		getgenv().DuskLogicBundle = {}

		if not V64 or not V65 or V65 == "" or V65:match("404 Not Found") then
			Clonefunction2("⛔ [Loader] Logic Bundle 404 or network error.")
		else
			local Chunk, v67 = loadstring(V65, "@DuskLogic")

			if type(Chunk) == "function" then
