				if Ok5 and type(duskLogicBundle) == "table" then
					getgenv().DuskLogicBundle = duskLogicBundle
					Clonefunction("🛡️ Logic Bundle loaded successfully!")
				else
					Clonefunction2("⛔ [Loader] Runtime error in Logic Bundle: " .. tostring(duskLogicBundle))
				end
			else
				Clonefunction2("⛔ [Loader] Failed to compile Logic Bundle: " .. tostring(V67))
			end
		end

		local function V70(P2)
			if P2.Loaded then
				return
			end

			task.spawn(function()
				if not P2.Tab and P2.Name ~= "Icons" and P2.Name ~= "Home" and P2.Name ~= "AutoFarmMode" and P2.Name ~= "AutoFarmEvent" then
					local V71 = string.lower(P2.Name)

					if V71 == "trade" then
						V71 = "trading"
					elseif V71 == "shop" then
						V71 = "purchases"
					elseif V71 == "locs" then
						V71 = "teleports"
					end

					if getgenv().DuskLogicBundle[V71] then
						task.spawn(function()
							local V72 = getgenv().DuskLogicBundle[V71]()

							if V72 then
								if type(V72.Init) == "function" then
									V72:Init(Lib, V53, P2.Tab)
								end
							end
						end)
						Clonefunction("⚡ Logic Linked & Started: " .. v71)
						P2.Loaded = true

						return
					end
				end

				local V73, v74 = V19(P2.Url)

				if V73 and V74 and not V74:match("404 Not Found") then
					local Chunk, v76 = loadstring(V74, "@" .. p2.Name)

					if type(Chunk) == "function" then
						local Ok5, result5 = pcall(function()
							local V79 = Chunk()

							if V79 and type(V79.Init) == "function" then
								V79:Init(Lib, V53, P2.Tab)
							end
						end)

						if not Ok5 then
							Clonefunction2("⛔ [Init Error] " .. p2.Name .. ":\n" .. tostring(Result5))
						end
					else
						Clonefunction2("⚠️ [Syntax] " .. p2.Name .. ":\n" .. tostring(V76))
					end

					P2.Loaded = true
					Clonefunction("✅ Loaded Async (RAM): " .. p2.Name)
				else
					Clonefunction2("🌐 [Network] Fetch failed: " .. p2.Name)
					P2.Loaded = true
				end
			end)
		end

		V70(T2[1])
		V70(T2[2])
		V70(T2[3])
		task.spawn(function()
			for I = 4, #T2 do
				V70(T2[I])
			end

			local V81 = false

			while not V81 do
				V81 = true

				for I = 4, #T2 do
					if not T2[I].Loaded then
						V81 = false

