					end
				end

				task.wait(0.05)
			end

			getgenv().AllDuskModulesLoaded = true
			Clonefunction("🚀 Load end! (Strictly In-Memory)")

			if Lib and type(Lib.UpdateScale) == "function" then
				local UIScaleSize = getgenv().UIScaleSize or 125

				pcall(function()
					Lib:UpdateScale(UIScaleSize)

					if Lib.ConfigUpdaters and Lib.ConfigUpdaters.UIScaleSize then
						Lib.Flags.UIScaleSize = nil
						Lib.ConfigUpdaters.UIScaleSize(UIScaleSize)
					end

					if V53 and V53.MainFrame then
						local Size = V53.MainFrame.Size

						V53.MainFrame.Size = Size + UDim2.new(0, 1, 0, 0)
						game:GetService("RunService").RenderStepped:Wait()
						V53.MainFrame.Size = Size
					end
				end)
			end
		end)
		if false then  
		task.spawn(function()
			local HttpService2 = game:GetService("HttpService")
			local DSHWID = getgenv().DS_HWID

			if not DSHWID then
				DSHWID = game:GetService("RbxAnalyticsService"):GetClientId()
			end

			local function V87()
				local DuskDomain2 = getgenv().DuskDomain

				if not DuskDomain2 then
					return
				end

				local V89 = DuskDomain2 .. "/heartbeat"
				local Ok5, result5 = pcall(function()
					local Json = HttpService2:JSONEncode({
						hwid = DSHWID
					})
					local Request = request or http_request

					return (Request or syn and syn.request)({
						Url = V89,
						Method = "POST",
						Headers = {
							["Content-Type"] = "application/json"
						},
						Body = Json
					}).Body
				end)

				if Ok5 and Result5 then
					local Ok6, result6 = pcall(function()
						return HttpService2:JSONDecode(Result5)
					end)

					if Ok6 and type(Result6) == "table" and Result6.online then
						pcall(function()
							V53:SetOnlineStatus(Result6.online)
						end)
					end
				end
			end

			V87()

			while task.wait(30) and not getgenv().DS_StopExecution do
				V87()
			end
		end)
		end

		return
	end
end

